const EMBEDDED_PUBLIC = {
  "app.js": "// CraftOrbit Pro Client Application\r\nlet ws = null;\r\nlet currentTab = 'dashboard';\r\nlet currentFilePath = '';\r\nlet editingFilePath = '';\r\nlet commandHistory = [];\r\nlet historyIndex = -1;\r\nlet serverStatus = 'offline';\r\nlet configuredMaxRamBytes = 6 * 1024 * 1024 * 1024; // Default 6GB\r\nlet audioEnabled = localStorage.getItem('craftorbit_audio') !== 'false';\r\nlet aiConversationHistory = [];\r\nlet cachedMods = [];\r\nlet cachedLocalIp = '127.0.0.1';\r\nlet serverTps = 20.0;\r\n\r\n// Performance Chart & Storage Doughnut instances\r\nlet perfChart = null;\r\nlet storageChart = null;\r\nconst perfData = {\r\n  labels: [],\r\n  ram: [],\r\n  cpu: []\r\n};\r\n\r\n// ================= AUDIO SYNTHESIZER =================\r\nconst audioCtx = (window.AudioContext || window.webkitAudioContext) ? new (window.AudioContext || window.webkitAudioContext)() : null;\r\n\r\nfunction playSound(type) {\r\n  if (!audioEnabled || !audioCtx) return;\r\n  try {\r\n    if (audioCtx.state === 'suspended') {\r\n      audioCtx.resume();\r\n    }\r\n    const now = audioCtx.currentTime;\r\n    const osc = audioCtx.createOscillator();\r\n    const gain = audioCtx.createGain();\r\n    osc.connect(gain);\r\n    gain.connect(audioCtx.destination);\r\n\r\n    if (type === 'start') {\r\n      // Ascending chime\r\n      osc.type = 'sine';\r\n      osc.frequency.setValueAtTime(440, now);\r\n      osc.frequency.exponentialRampToValueAtTime(880, now + 0.18);\r\n      gain.gain.setValueAtTime(0.12, now);\r\n      gain.gain.exponentialRampToValueAtTime(0.01, now + 0.2);\r\n      osc.start(now);\r\n      osc.stop(now + 0.22);\r\n    } else if (type === 'stop') {\r\n      // Descending tone\r\n      osc.type = 'sine';\r\n      osc.frequency.setValueAtTime(600, now);\r\n      osc.frequency.exponentialRampToValueAtTime(220, now + 0.2);\r\n      gain.gain.setValueAtTime(0.12, now);\r\n      gain.gain.exponentialRampToValueAtTime(0.01, now + 0.22);\r\n      osc.start(now);\r\n      osc.stop(now + 0.24);\r\n    } else if (type === 'cmd') {\r\n      // Short click\r\n      osc.type = 'triangle';\r\n      osc.frequency.setValueAtTime(900, now);\r\n      gain.gain.setValueAtTime(0.05, now);\r\n      gain.gain.exponentialRampToValueAtTime(0.001, now + 0.05);\r\n      osc.start(now);\r\n      osc.stop(now + 0.06);\r\n    } else if (type === 'alert') {\r\n      // High ping\r\n      osc.type = 'sine';\r\n      osc.frequency.setValueAtTime(1046, now);\r\n      gain.gain.setValueAtTime(0.1, now);\r\n      gain.gain.exponentialRampToValueAtTime(0.01, now + 0.25);\r\n      osc.start(now);\r\n      osc.stop(now + 0.26);\r\n    }\r\n  } catch (e) {}\r\n}\r\n\r\nfunction toggleAudio() {\r\n  audioEnabled = !audioEnabled;\r\n  localStorage.setItem('craftorbit_audio', audioEnabled);\r\n  const icon = document.getElementById('soundIcon');\r\n  if (icon) {\r\n    icon.setAttribute('data-lucide', audioEnabled ? 'volume-2' : 'volume-x');\r\n    lucide.createIcons();\r\n  }\r\n  showToast(audioEnabled ? 'UI sound effects enabled' : 'UI sound effects muted', 'info');\r\n}\r\n\r\n// Format bytes helper\r\nfunction formatBytes(bytes, decimals = 2) {\r\n  if (!bytes || bytes === 0) return '0 B';\r\n  const k = 1024;\r\n  const dm = decimals < 0 ? 0 : decimals;\r\n  const sizes = ['B', 'KB', 'MB', 'GB', 'TB'];\r\n  const i = Math.floor(Math.log(bytes) / Math.log(k));\r\n  return parseFloat((bytes / Math.pow(k, i)).toFixed(dm)) + ' ' + sizes[i];\r\n}\r\n\r\n// Toast notification helper\r\nfunction showToast(msg, type = 'info') {\r\n  const container = document.getElementById('toastContainer');\r\n  const toast = document.createElement('div');\r\n  const colorClasses = {\r\n    info: 'bg-[#121212] border-[#2e2e2e] text-neutral-200',\r\n    success: 'bg-white text-black border-white font-medium',\r\n    warning: 'bg-[#181818] border-[#3e3e3e] text-white',\r\n    error: 'bg-[#1c1c1c] border-white text-white'\r\n  }[type] || 'bg-[#121212] border-[#2e2e2e] text-neutral-200';\r\n\r\n  toast.className = `pointer-events-auto px-4 py-2.5 rounded-xl border shadow-2xl text-xs font-medium flex items-center gap-2 transition-all transform duration-300 translate-y-2 opacity-0 ${colorClasses}`;\r\n  toast.innerHTML = `<span>${msg}</span>`;\r\n  container.appendChild(toast);\r\n\r\n  requestAnimationFrame(() => {\r\n    toast.classList.remove('translate-y-2', 'opacity-0');\r\n  });\r\n\r\n  setTimeout(() => {\r\n    toast.classList.add('opacity-0', '-translate-y-2');\r\n    setTimeout(() => toast.remove(), 300);\r\n  }, 4000);\r\n}\r\n\r\n// Tab Switching\r\nfunction switchTab(tabId) {\r\n  currentTab = tabId;\r\n  const tabs = ['dashboard', 'ai', 'mods', 'players', 'storage', 'playit', 'console', 'files', 'settings'];\r\n\r\n  tabs.forEach(t => {\r\n    const view = document.getElementById(`view-${t}`);\r\n    const btn = document.getElementById(`tab-${t}`);\r\n    const sideBtn = document.getElementById(`side-tab-${t}`);\r\n\r\n    if (view) {\r\n      if (t === tabId) {\r\n        view.classList.remove('hidden');\r\n      } else {\r\n        view.classList.add('hidden');\r\n      }\r\n    }\r\n    if (btn) {\r\n      if (t === tabId) {\r\n        btn.classList.add('active');\r\n      } else {\r\n        btn.classList.remove('active');\r\n      }\r\n    }\r\n    if (sideBtn) {\r\n      if (t === tabId) {\r\n        sideBtn.classList.add('active');\r\n      } else {\r\n        sideBtn.classList.remove('active');\r\n      }\r\n    }\r\n  });\r\n\r\n  // Update Breadcrumb Title in Sidebar Mode\r\n  const breadcrumbEl = document.getElementById('breadcrumbActiveTitle');\r\n  const titleMap = {\r\n    dashboard: 'Workspace Overview',\r\n    console: 'Live Console',\r\n    settings: 'Server Settings',\r\n    ai: 'AI Server Sage',\r\n    files: 'File Manager',\r\n    mods: 'Mod Manager',\r\n    storage: 'Backups & Storage',\r\n    playit: 'Global Network',\r\n    players: 'Players & Roster'\r\n  };\r\n  if (breadcrumbEl && titleMap[tabId]) {\r\n    breadcrumbEl.textContent = titleMap[tabId];\r\n  }\r\n\r\n  if (tabId === 'storage') {\r\n    loadStorageOverview();\r\n    loadBackups();\r\n  } else if (tabId === 'playit') {\r\n    loadPlayitStatus();\r\n  } else if (tabId === 'mods') {\r\n    loadModsList();\r\n  } else if (tabId === 'players') {\r\n    loadPlayersData();\r\n  } else if (tabId === 'files') {\r\n    loadFiles(currentFilePath);\r\n  } else if (tabId === 'settings') {\r\n    loadSettings();\r\n  }\r\n}\r\n\r\n// ================= CHART.JS INITIALIZATION =================\r\nfunction initTelemetryCharts() {\r\n  // 1. Performance Chart (RAM & CPU Line Chart) - Monochrome\r\n  const perfCtx = document.getElementById('perfChartCanvas');\r\n  if (perfCtx) {\r\n    perfChart = new Chart(perfCtx, {\r\n      type: 'line',\r\n      data: {\r\n        labels: perfData.labels,\r\n        datasets: [\r\n          {\r\n            label: 'RAM (MB)',\r\n            data: perfData.ram,\r\n            borderColor: '#ffffff',\r\n            backgroundColor: 'rgba(255, 255, 255, 0.08)',\r\n            fill: true,\r\n            tension: 0.3,\r\n            borderWidth: 2,\r\n            pointRadius: 0,\r\n            yAxisID: 'yRam'\r\n          },\r\n          {\r\n            label: 'CPU (%)',\r\n            data: perfData.cpu,\r\n            borderColor: '#71717a',\r\n            backgroundColor: 'rgba(113, 113, 122, 0.04)',\r\n            fill: true,\r\n            tension: 0.3,\r\n            borderWidth: 1.5,\r\n            borderDash: [4, 4],\r\n            pointRadius: 0,\r\n            yAxisID: 'yCpu'\r\n          }\r\n        ]\r\n      },\r\n      options: {\r\n        responsive: true,\r\n        maintainAspectRatio: false,\r\n        animation: false,\r\n        scales: {\r\n          x: {\r\n            display: false\r\n          },\r\n          yRam: {\r\n            type: 'linear',\r\n            position: 'left',\r\n            min: 0,\r\n            suggestedMax: 6144, // 6GB\r\n            grid: { color: 'rgba(255, 255, 255, 0.05)' },\r\n            ticks: {\r\n              color: '#a1a1aa',\r\n              font: { size: 10, family: 'monospace' },\r\n              callback: (v) => v + ' MB'\r\n            }\r\n          },\r\n          yCpu: {\r\n            type: 'linear',\r\n            position: 'right',\r\n            min: 0,\r\n            max: 100,\r\n            grid: { drawOnChartArea: false },\r\n            ticks: {\r\n              color: '#71717a',\r\n              font: { size: 10, family: 'monospace' },\r\n              callback: (v) => v + '%'\r\n            }\r\n          }\r\n        },\r\n        plugins: {\r\n          legend: { display: false },\r\n          tooltip: {\r\n            mode: 'index',\r\n            intersect: false,\r\n            backgroundColor: '#0a0a0a',\r\n            borderColor: '#262626',\r\n            borderWidth: 1,\r\n            titleColor: '#ffffff',\r\n            bodyColor: '#e4e4e7'\r\n          }\r\n        }\r\n      }\r\n    });\r\n  }\r\n\r\n  // 2. Storage Doughnut Chart - Monochrome Grayscale\r\n  const storageCtx = document.getElementById('storageDoughnutCanvas');\r\n  if (storageCtx) {\r\n    storageChart = new Chart(storageCtx, {\r\n      type: 'doughnut',\r\n      data: {\r\n        labels: ['World Data', 'Mods', 'Setup Zip', 'Libraries', 'Logs', 'Other'],\r\n        datasets: [{\r\n          data: [2790, 848, 782, 117, 30, 61],\r\n          backgroundColor: [\r\n            '#ffffff', // Pure White (World)\r\n            '#d4d4d8', // Off White (Mods)\r\n            '#a1a1aa', // Silver (Zip)\r\n            '#71717a', // Neutral Grey (Libraries)\r\n            '#52525b', // Darker Grey (Logs)\r\n            '#27272a'  // Charcoal (Configs)\r\n          ],\r\n          borderColor: '#0a0a0a',\r\n          borderWidth: 2\r\n        }]\r\n      },\r\n      options: {\r\n        responsive: true,\r\n        maintainAspectRatio: false,\r\n        cutout: '72%',\r\n        plugins: {\r\n          legend: { display: false },\r\n          tooltip: {\r\n            backgroundColor: '#0a0a0a',\r\n            borderColor: '#262626',\r\n            borderWidth: 1,\r\n            callbacks: {\r\n              label: (ctx) => ` ${ctx.label}: ${ctx.raw} MB`\r\n            }\r\n          }\r\n        }\r\n      }\r\n    });\r\n  }\r\n}\r\n\r\n// Push live telemetry data point to Chart\r\nfunction recordTelemetryPoint(ramMB, cpuPercent) {\r\n  const timeLabel = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });\r\n  perfData.labels.push(timeLabel);\r\n  perfData.ram.push(ramMB);\r\n  perfData.cpu.push(cpuPercent);\r\n\r\n  // Keep last 25 points\r\n  if (perfData.labels.length > 25) {\r\n    perfData.labels.shift();\r\n    perfData.ram.shift();\r\n    perfData.cpu.shift();\r\n  }\r\n\r\n  if (perfChart) {\r\n    perfChart.update();\r\n  }\r\n}\r\n\r\n// ================= WEBSOCKET CONNECTION =================\r\nfunction connectWebSocket() {\r\n  const protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';\r\n  const wsUrl = `${protocol}//${window.location.host}`;\r\n  ws = new WebSocket(wsUrl);\r\n\r\n  ws.onopen = () => {\r\n    console.log('[WS] Connected to dashboard server');\r\n  };\r\n\r\n  ws.onmessage = (event) => {\r\n    try {\r\n      const msg = JSON.parse(event.data);\r\n      if (msg.type === 'log') {\r\n        renderLogLine(msg.data);\r\n      } else if (msg.type === 'logs_history') {\r\n        const miniScreen = document.getElementById('dashMiniConsole');\r\n        const fullScreen = document.getElementById('fullConsoleScreen');\r\n        miniScreen.innerHTML = '';\r\n        fullScreen.innerHTML = '';\r\n        msg.data.forEach(renderLogLine);\r\n      } else if (msg.type === 'status') {\r\n        updateServerStatusUI(msg.data);\r\n      } else if (msg.type === 'playit_status') {\r\n        updatePlayitUI(msg.data);\r\n      } else if (msg.type === 'playit_log') {\r\n        renderPlayitLog(msg.data);\r\n      } else if (msg.type === 'provision_progress') {\r\n        updateProvisionProgress(msg.data);\r\n      } else if (msg.type === 'telemetry') {\r\n        updateTelemetryUI(msg.data);\r\n      }\r\n    } catch (e) {\r\n      console.error('Error handling WS message:', e);\r\n    }\r\n  };\r\n\r\n  ws.onclose = () => {\r\n    console.log('[WS] Disconnected, reconnecting in 2s...');\r\n    setTimeout(connectWebSocket, 2000);\r\n  };\r\n}\r\n\r\n// Render log lines with syntax coloring\r\nfunction renderLogLine(logEntry) {\r\n  const text = logEntry.text || '';\r\n  const miniScreen = document.getElementById('dashMiniConsole');\r\n  const fullScreen = document.getElementById('fullConsoleScreen');\r\n\r\n  let logClass = 'log-info';\r\n  if (text.includes('[Dashboard ERROR]') || text.includes('/ERROR]') || text.includes('Exception:') || text.includes('Crash')) {\r\n    logClass = 'log-error';\r\n    playSound('alert');\r\n  } else if (text.includes('/WARN]')) {\r\n    logClass = 'log-warn';\r\n  } else if (text.includes('<') && text.includes('>')) {\r\n    logClass = 'log-chat';\r\n  } else if (text.startsWith('[Dashboard]')) {\r\n    logClass = 'log-dash';\r\n  }\r\n\r\n  // Mini console\r\n  const miniLine = document.createElement('div');\r\n  miniLine.className = `log-line ${logClass} truncate`;\r\n  miniLine.textContent = text;\r\n  miniScreen.appendChild(miniLine);\r\n  if (miniScreen.children.length > 60) {\r\n    miniScreen.removeChild(miniScreen.firstChild);\r\n  }\r\n  miniScreen.scrollTop = miniScreen.scrollHeight;\r\n\r\n  // Full console\r\n  const fullLine = document.createElement('div');\r\n  fullLine.className = `log-line ${logClass}`;\r\n  fullLine.textContent = text;\r\n\r\n  // Filter check\r\n  const filterVal = document.getElementById('consoleFilter').value.toLowerCase();\r\n  if (filterVal && !text.toLowerCase().includes(filterVal)) {\r\n    fullLine.style.display = 'none';\r\n  }\r\n\r\n  fullScreen.appendChild(fullLine);\r\n  if (fullScreen.children.length > 2000) {\r\n    fullScreen.removeChild(fullScreen.firstChild);\r\n  }\r\n\r\n  const autoScroll = document.getElementById('autoScrollCheck').checked;\r\n  if (autoScroll) {\r\n    fullScreen.scrollTop = fullScreen.scrollHeight;\r\n  }\r\n}\r\n\r\nfunction filterConsoleLogs() {\r\n  const filter = document.getElementById('consoleFilter').value.toLowerCase();\r\n  const lines = document.getElementById('fullConsoleScreen').children;\r\n  for (let i = 0; i < lines.length; i++) {\r\n    const text = lines[i].textContent.toLowerCase();\r\n    lines[i].style.display = text.includes(filter) ? '' : 'none';\r\n  }\r\n}\r\n\r\nfunction clearConsoleView() {\r\n  document.getElementById('fullConsoleScreen').innerHTML = '';\r\n}\r\n\r\n// Update Status Badge & Controls\r\nfunction updateServerStatusUI(data) {\r\n  const prevStatus = serverStatus;\r\n  serverStatus = data.status || 'offline';\r\n  const statusBadge = document.getElementById('statusBadge');\r\n  const statusDot = document.getElementById('statusDot');\r\n  const statusText = document.getElementById('statusText');\r\n  const btnStart = document.getElementById('btnStart');\r\n  const btnStop = document.getElementById('btnStop');\r\n  const heroStatusText = document.getElementById('heroStatusText');\r\n  const heroStatusDot = document.getElementById('heroStatusDot');\r\n  const heroBtnStart = document.getElementById('heroBtnStart');\r\n  const heroBtnStop = document.getElementById('heroBtnStop');\r\n\r\n  if (serverStatus === 'online') {\r\n    statusBadge.className = 'flex items-center gap-2 px-3 py-1.5 rounded-full bg-white text-black border border-white text-xs font-mono font-semibold';\r\n    statusDot.className = 'w-2 h-2 rounded-full bg-black pulse-active';\r\n    statusText.textContent = 'ONLINE';\r\n    if (heroStatusText) heroStatusText.textContent = 'ONLINE';\r\n    if (heroStatusDot) heroStatusDot.className = 'w-2 h-2 rounded-full bg-emerald-400 pulse-active';\r\n    btnStart.disabled = true;\r\n    btnStart.classList.add('opacity-40', 'cursor-not-allowed');\r\n    btnStop.disabled = false;\r\n    btnStop.classList.remove('opacity-50', 'cursor-not-allowed');\r\n    if (heroBtnStart) { heroBtnStart.disabled = true; heroBtnStart.classList.add('opacity-40', 'cursor-not-allowed'); }\r\n    if (heroBtnStop) { heroBtnStop.disabled = false; heroBtnStop.classList.remove('opacity-50', 'cursor-not-allowed'); }\r\n    if (prevStatus === 'starting') playSound('start');\r\n  } else if (serverStatus === 'starting') {\r\n    statusBadge.className = 'flex items-center gap-2 px-3 py-1.5 rounded-full bg-[#181818] border border-[#333] text-xs font-mono text-white';\r\n    statusDot.className = 'w-2 h-2 rounded-full bg-white animate-ping';\r\n    statusText.textContent = 'STARTING...';\r\n    if (heroStatusText) heroStatusText.textContent = 'STARTING...';\r\n    if (heroStatusDot) heroStatusDot.className = 'w-2 h-2 rounded-full bg-amber-400 animate-ping';\r\n    btnStart.disabled = true;\r\n    btnStart.classList.add('opacity-40', 'cursor-not-allowed');\r\n    btnStop.disabled = false;\r\n    btnStop.classList.remove('opacity-50', 'cursor-not-allowed');\r\n    if (heroBtnStart) { heroBtnStart.disabled = true; heroBtnStart.classList.add('opacity-40', 'cursor-not-allowed'); }\r\n    if (heroBtnStop) { heroBtnStop.disabled = false; heroBtnStop.classList.remove('opacity-50', 'cursor-not-allowed'); }\r\n  } else if (serverStatus === 'stopping') {\r\n    statusBadge.className = 'flex items-center gap-2 px-3 py-1.5 rounded-full bg-[#141414] border border-[#333] text-xs font-mono text-neutral-400';\r\n    statusDot.className = 'w-2 h-2 rounded-full bg-neutral-400';\r\n    statusText.textContent = 'STOPPING...';\r\n    if (heroStatusText) heroStatusText.textContent = 'STOPPING...';\r\n    if (heroStatusDot) heroStatusDot.className = 'w-2 h-2 rounded-full bg-neutral-400';\r\n    btnStart.disabled = true;\r\n    btnStop.disabled = true;\r\n    btnStop.classList.add('opacity-50', 'cursor-not-allowed');\r\n    if (heroBtnStart) { heroBtnStart.disabled = true; heroBtnStart.classList.add('opacity-40', 'cursor-not-allowed'); }\r\n    if (heroBtnStop) { heroBtnStop.disabled = true; heroBtnStop.classList.add('opacity-50', 'cursor-not-allowed'); }\r\n  } else {\r\n    statusBadge.className = 'flex items-center gap-2 px-3 py-1.5 rounded-full bg-[#0a0a0a] border border-[#262626] text-xs font-mono text-neutral-400';\r\n    statusDot.className = 'w-2 h-2 rounded-full bg-neutral-600';\r\n    statusText.textContent = 'OFFLINE';\r\n    if (heroStatusText) heroStatusText.textContent = 'OFFLINE';\r\n    if (heroStatusDot) heroStatusDot.className = 'w-2 h-2 rounded-full bg-neutral-600';\r\n    btnStart.disabled = false;\r\n    btnStart.classList.remove('opacity-40', 'cursor-not-allowed');\r\n    btnStop.disabled = true;\r\n    btnStop.classList.add('opacity-50', 'cursor-not-allowed');\r\n    if (heroBtnStart) { heroBtnStart.disabled = false; heroBtnStart.classList.remove('opacity-40', 'cursor-not-allowed'); }\r\n    if (heroBtnStop) { heroBtnStop.disabled = true; heroBtnStop.classList.add('opacity-50', 'cursor-not-allowed'); }\r\n    if (prevStatus === 'stopping' || prevStatus === 'online') playSound('stop');\r\n  }\r\n\r\n  // Uptime\r\n  if (data.uptime && data.uptime > 0) {\r\n    const hrs = Math.floor(data.uptime / 3600);\r\n    const mins = Math.floor((data.uptime % 3600) / 60);\r\n    const secs = data.uptime % 60;\r\n    document.getElementById('uptimeBadge').textContent = `Uptime: ${hrs}h ${mins}m ${secs}s`;\r\n  } else {\r\n    document.getElementById('uptimeBadge').textContent = 'Uptime: --';\r\n  }\r\n\r\n  // Players\r\n  if (data.players) {\r\n    document.getElementById('onlinePlayersCount').innerHTML = `${data.players.length} <span class=\"text-xs font-normal text-slate-500\">/ 5 max</span>`;\r\n    document.getElementById('onlinePlayersList').textContent = data.players.length > 0 ? data.players.join(', ') : 'No players connected';\r\n  }\r\n\r\n  // RAM configuration max\r\n  if (data.config && data.config.maxRam) {\r\n    document.getElementById('serverRamMax').textContent = `Allocated: -Xmx${data.config.maxRam}`;\r\n    const ramNum = parseFloat(data.config.maxRam);\r\n    if (data.config.maxRam.toUpperCase().includes('G')) {\r\n      configuredMaxRamBytes = ramNum * 1024 * 1024 * 1024;\r\n    } else if (data.config.maxRam.toUpperCase().includes('M')) {\r\n      configuredMaxRamBytes = ramNum * 1024 * 1024;\r\n    }\r\n  }\r\n\r\n  // Welcome Hero vs Server Controls\r\n  const welcomeHero = document.getElementById('welcomeHeroCard');\r\n  const isDummy = !activeInstanceData || activeInstanceData.id === 'none';\r\n\r\n  if (welcomeHero) {\r\n    if (isDummy) {\r\n      welcomeHero.classList.remove('hidden');\r\n    } else {\r\n      welcomeHero.classList.add('hidden');\r\n    }\r\n  }\r\n\r\n  updateShareInviteUI();\r\n}\r\n\r\n// Update Telemetry UI\r\nfunction updateTelemetryUI(telemetry) {\r\n  if (telemetry.server) {\r\n    updateServerStatusUI(telemetry.server);\r\n  }\r\n  if (telemetry.playit) {\r\n    updatePlayitUI(telemetry.playit);\r\n  }\r\n\r\n  let curRamMB = 0;\r\n  if (telemetry.process && telemetry.process.memoryBytes) {\r\n    const memBytes = telemetry.process.memoryBytes;\r\n    curRamMB = telemetry.process.memoryMB || Math.round(memBytes / (1024 * 1024));\r\n    document.getElementById('serverRamUsage').textContent = formatBytes(memBytes);\r\n    const percent = Math.min(100, Math.round((memBytes / configuredMaxRamBytes) * 100));\r\n    document.getElementById('ramPercentText').textContent = `${percent}%`;\r\n    document.getElementById('ramBar').style.width = `${percent}%`;\r\n  } else if (serverStatus === 'offline') {\r\n    document.getElementById('serverRamUsage').textContent = '0 MB';\r\n    document.getElementById('ramPercentText').textContent = '0%';\r\n    document.getElementById('ramBar').style.width = '0%';\r\n  }\r\n\r\n  let curCpu = 0;\r\n  if (telemetry.system) {\r\n    curCpu = telemetry.system.cpuPercent || 0;\r\n    document.getElementById('cpuUsageVal').textContent = `${curCpu}%`;\r\n    document.getElementById('cpuPercentText').textContent = `${curCpu}%`;\r\n    document.getElementById('cpuBar').style.width = `${curCpu}%`;\r\n  }\r\n\r\n    recordTelemetryPoint(curRamMB, curCpu);\r\n\r\n    // Sync Server Hero Workspace Card\r\n    const heroCpu = document.getElementById('heroCpuPercent');\r\n    const heroCpuBar = document.getElementById('heroCpuBar');\r\n    if (heroCpu) heroCpu.textContent = `${curCpu}%`;\r\n    if (heroCpuBar) heroCpuBar.style.width = `${Math.min(100, curCpu)}%`;\r\n\r\n    const heroRam = document.getElementById('heroRamUsage');\r\n    const heroRamBar = document.getElementById('heroRamBar');\r\n    const ramUsageEl = document.getElementById('serverRamUsage');\r\n    const ramBarEl = document.getElementById('ramBar');\r\n    if (heroRam && ramUsageEl) heroRam.textContent = ramUsageEl.textContent;\r\n    if (heroRamBar && ramBarEl) heroRamBar.style.width = ramBarEl.style.width;\r\n\r\n    if (telemetry.serverPing) {\r\n      const badge = document.getElementById('slpPingBadge');\r\n      if (badge) {\r\n        if (telemetry.serverPing.online) {\r\n          badge.textContent = `Ping: ${telemetry.serverPing.latencyMs} ms`;\r\n          badge.className = 'font-mono text-white text-[10px] font-bold';\r\n        } else if (serverStatus === 'online') {\r\n          badge.textContent = 'Server starting...';\r\n          badge.className = 'font-mono text-neutral-400 text-[10px]';\r\n        } else {\r\n          badge.textContent = 'Ping: -- ms';\r\n          badge.className = 'font-mono text-neutral-500 text-[10px]';\r\n        }\r\n      }\r\n    }\r\n\r\n    if (telemetry.drive && telemetry.drive.total) {\r\n    const freeGb = (telemetry.drive.free / (1024 * 1024 * 1024)).toFixed(1);\r\n    const totalGb = (telemetry.drive.total / (1024 * 1024 * 1024)).toFixed(1);\r\n    document.getElementById('diskFreeVal').textContent = `${freeGb} GB Available`;\r\n    document.getElementById('diskTotalVal').textContent = `Total: ${totalGb} GB (${telemetry.drive.usedPercent}% used)`;\r\n    document.getElementById('diskPercentText').textContent = `${telemetry.drive.usedPercent}%`;\r\n    document.getElementById('diskBar').style.width = `${telemetry.drive.usedPercent}%`;\r\n    document.getElementById('driveFreeLabel').textContent = `${freeGb} GB`;\r\n\r\n    const heroDisk = document.getElementById('heroDiskUsage');\r\n    const heroDiskBar = document.getElementById('heroDiskBar');\r\n    if (heroDisk) heroDisk.textContent = `${freeGb} GB`;\r\n    if (heroDiskBar) heroDiskBar.style.width = `${telemetry.drive.usedPercent}%`;\r\n  }\r\n}\r\n\r\n// Copy Server IP\r\nfunction copyServerIp() {\r\n  const ipText = document.getElementById('headerServerIp').textContent;\r\n  navigator.clipboard.writeText(ipText).then(() => {\r\n    playSound('cmd');\r\n    showToast('Server IP copied to clipboard! (localhost:25402)', 'success');\r\n  });\r\n}\r\n\r\n// Server Control Actions\r\nasync function startServer() {\r\n  try {\r\n    playSound('cmd');\r\n    showToast('Starting Forge Minecraft Server with 6GB RAM...', 'info');\r\n    const res = await fetch('/api/server/start', { method: 'POST' });\r\n    const data = await res.json();\r\n    if (data.error) throw new Error(data.error);\r\n    showToast('Server launch command issued!', 'success');\r\n  } catch (e) {\r\n    showToast(`Error: ${e.message}`, 'error');\r\n  }\r\n}\r\n\r\nasync function stopServer() {\r\n  if (!confirm('Are you sure you want to stop the Minecraft server?')) return;\r\n  try {\r\n    playSound('cmd');\r\n    showToast('Gracefully stopping server (/stop)...', 'warning');\r\n    const res = await fetch('/api/server/stop', { method: 'POST' });\r\n    const data = await res.json();\r\n    if (data.error) throw new Error(data.error);\r\n  } catch (e) {\r\n    showToast(`Error: ${e.message}`, 'error');\r\n  }\r\n}\r\n\r\nasync function restartServer() {\r\n  if (!confirm('Restart Minecraft server now?')) return;\r\n  try {\r\n    playSound('cmd');\r\n    showToast('Restarting server...', 'info');\r\n    const res = await fetch('/api/server/restart', { method: 'POST' });\r\n    const data = await res.json();\r\n    if (data.error) throw new Error(data.error);\r\n  } catch (e) {\r\n    showToast(`Error: ${e.message}`, 'error');\r\n  }\r\n}\r\n\r\nasync function killServer() {\r\n  if (!confirm('Force kill the server process immediately?')) return;\r\n  try {\r\n    playSound('stop');\r\n    const res = await fetch('/api/server/kill', { method: 'POST' });\r\n    const data = await res.json();\r\n    showToast('Server process terminated.', 'warning');\r\n  } catch (e) {\r\n    showToast(`Error: ${e.message}`, 'error');\r\n  }\r\n}\r\n\r\n// Command execution\r\nasync function sendCommand(cmd) {\r\n  if (!cmd || !cmd.trim()) return;\r\n  try {\r\n    playSound('cmd');\r\n    if (ws && ws.readyState === WebSocket.OPEN) {\r\n      ws.send(JSON.stringify({ type: 'command', command: cmd }));\r\n    } else {\r\n      await fetch('/api/server/command', {\r\n        method: 'POST',\r\n        headers: { 'Content-Type': 'application/json' },\r\n        body: JSON.stringify({ command: cmd })\r\n      });\r\n    }\r\n  } catch (e) {\r\n    showToast(`Failed to send command: ${e.message}`, 'error');\r\n  }\r\n}\r\n\r\nfunction handleQuickCommand(e) {\r\n  e.preventDefault();\r\n  const input = document.getElementById('dashCommandInput');\r\n  const cmd = input.value.trim();\r\n  if (cmd) {\r\n    sendCommand(cmd);\r\n    input.value = '';\r\n  }\r\n}\r\n\r\nfunction handleFullConsoleCommand(e) {\r\n  e.preventDefault();\r\n  const input = document.getElementById('fullConsoleInput');\r\n  const cmd = input.value.trim();\r\n  if (cmd) {\r\n    commandHistory.push(cmd);\r\n    historyIndex = commandHistory.length;\r\n    sendCommand(cmd);\r\n    input.value = '';\r\n  }\r\n}\r\n\r\nfunction sendQuickCommand(cmd) {\r\n  sendCommand(cmd);\r\n  showToast(`Executed: /${cmd}`, 'info');\r\n}\r\n\r\n// ================= AI COPILOT & DIAGNOSTICS =================\r\nfunction formatAiResponse(raw) {\r\n  // Replace Minecraft commands like `/command` or `/cmd args` into clickable buttons\r\n  let formatted = raw.replace(/`(\\/[a-zA-Z0-9_\\-:]+(?:\\s+[^`\\n]+)?)`/g, (match, cmd) => {\r\n    return `<button class=\"cmd-chip\" onclick=\"executeFromAi('${cmd}')\" title=\"Click to run on server\">▶ ${cmd}</button>`;\r\n  });\r\n\r\n  // Basic markdown bullet points & linebreaks\r\n  formatted = formatted.replace(/\\n\\n/g, '<br><br>');\r\n  formatted = formatted.replace(/\\n- /g, '<br>&bull; ');\r\n  formatted = formatted.replace(/\\n(\\d+)\\. /g, '<br><strong>$1.</strong> ');\r\n  return formatted;\r\n}\r\n\r\nfunction executeFromAi(cmd) {\r\n  sendCommand(cmd);\r\n  showToast(`Command sent: ${cmd}`, 'success');\r\n}\r\n\r\nfunction appendAiMessage(role, text) {\r\n  const windowEl = document.getElementById('aiChatWindow');\r\n  const wrapper = document.createElement('div');\r\n  wrapper.className = `flex gap-3 items-start ${role === 'user' ? 'justify-end' : ''}`;\r\n\r\n  if (role === 'user') {\r\n    wrapper.innerHTML = `\r\n      <div class=\"bg-white text-black font-medium border border-white rounded-xl p-3 text-xs max-w-xl shadow\">\r\n        ${text}\r\n      </div>\r\n      <div class=\"w-8 h-8 rounded-lg bg-neutral-900 border border-[#333] text-white flex items-center justify-center shrink-0 mt-0.5\">\r\n        <i data-lucide=\"user\" class=\"w-4 h-4\"></i>\r\n      </div>\r\n    `;\r\n  } else {\r\n    wrapper.innerHTML = `\r\n      <div class=\"w-8 h-8 rounded-lg bg-white text-black flex items-center justify-center shrink-0 mt-0.5\">\r\n        <i data-lucide=\"bot\" class=\"w-4 h-4\"></i>\r\n      </div>\r\n      <div class=\"bg-[#0e0e0e] border border-[#222] rounded-xl p-4 text-xs leading-relaxed max-w-3xl text-neutral-200 space-y-2\">\r\n        ${formatAiResponse(text)}\r\n      </div>\r\n    `;\r\n  }\r\n\r\n  windowEl.appendChild(wrapper);\r\n  windowEl.scrollTop = windowEl.scrollHeight;\r\n  lucide.createIcons();\r\n}\r\n\r\nasync function handleAiSubmit(e) {\r\n  if (e) e.preventDefault();\r\n  const input = document.getElementById('aiUserInput');\r\n  const message = input.value.trim();\r\n  if (!message) return;\r\n\r\n  input.value = '';\r\n  appendAiMessage('user', message);\r\n  aiConversationHistory.push({ role: 'user', content: message });\r\n\r\n  // Add loading placeholder\r\n  const loadingPlaceholder = document.createElement('div');\r\n  loadingPlaceholder.id = 'aiLoadingIndicator';\r\n  loadingPlaceholder.className = 'flex gap-3 items-center text-xs text-neutral-400 font-mono italic';\r\n  loadingPlaceholder.innerHTML = `<span class=\"w-2 h-2 rounded-full bg-white animate-ping\"></span> AI Copilot is thinking...`;\r\n  document.getElementById('aiChatWindow').appendChild(loadingPlaceholder);\r\n\r\n  try {\r\n    const res = await fetch('/api/ai/chat', {\r\n      method: 'POST',\r\n      headers: { 'Content-Type': 'application/json' },\r\n      body: JSON.stringify({ message, history: aiConversationHistory })\r\n    });\r\n    const data = await res.json();\r\n    loadingPlaceholder.remove();\r\n\r\n    if (data.error) throw new Error(data.error);\r\n    appendAiMessage('assistant', data.reply);\r\n    aiConversationHistory.push({ role: 'assistant', content: data.reply });\r\n  } catch (err) {\r\n    if (loadingPlaceholder) loadingPlaceholder.remove();\r\n    appendAiMessage('assistant', `⚠️ Error connecting to 9Router AI: ${err.message}`);\r\n  }\r\n}\r\n\r\nfunction sendAiPreset(prompt) {\r\n  switchTab('ai');\r\n  document.getElementById('aiUserInput').value = prompt;\r\n  handleAiSubmit();\r\n}\r\n\r\nasync function runQuickDiagnosis() {\r\n  switchTab('ai');\r\n  appendAiMessage('user', 'Running full server diagnostics (Logs, stack traces & crash reports)...');\r\n  showToast('Analyzing server logs with AI Doctor...', 'info');\r\n\r\n  const loadingPlaceholder = document.createElement('div');\r\n  loadingPlaceholder.id = 'aiLoadingIndicator';\r\n  loadingPlaceholder.className = 'flex gap-3 items-center text-xs text-neutral-400 font-mono italic';\r\n  loadingPlaceholder.innerHTML = `<span class=\"w-2 h-2 rounded-full bg-white animate-ping\"></span> Reading logs and generating diagnosis...`;\r\n  document.getElementById('aiChatWindow').appendChild(loadingPlaceholder);\r\n\r\n  try {\r\n    const res = await fetch('/api/ai/diagnose', { method: 'POST' });\r\n    const data = await res.json();\r\n    loadingPlaceholder.remove();\r\n\r\n    if (data.error) throw new Error(data.error);\r\n\r\n    appendAiMessage('assistant', data.diagnosis);\r\n    document.getElementById('quickAiStatus').textContent = `Last Diagnosis: ${new Date().toLocaleTimeString()} - Analyzed ${data.rawErrorCount || 0} log events.`;\r\n  } catch (e) {\r\n    if (loadingPlaceholder) loadingPlaceholder.remove();\r\n    appendAiMessage('assistant', `Diagnosis failed: ${e.message}`);\r\n  }\r\n}\r\n\r\nfunction clearAiChat() {\r\n  aiConversationHistory = [];\r\n  document.getElementById('aiChatWindow').innerHTML = `\r\n    <div class=\"flex gap-3 items-start\">\r\n      <div class=\"w-8 h-8 rounded-lg bg-white text-black flex items-center justify-center shrink-0 mt-0.5\">\r\n        <i data-lucide=\"bot\" class=\"w-4 h-4\"></i>\r\n      </div>\r\n      <div class=\"bg-[#0e0e0e] border border-[#222] rounded-xl p-4 text-xs leading-relaxed max-w-3xl text-neutral-200\">\r\n        <p class=\"font-semibold text-white\">Chat cleared.</p>\r\n        <p class=\"text-neutral-400 text-[11px] mt-1\">Ready for your next question or diagnosis.</p>\r\n      </div>\r\n    </div>\r\n  `;\r\n  lucide.createIcons();\r\n}\r\n\r\n// ================= MOD MANAGER & MODRINTH STORE =================\r\nlet currentModSubtab = 'installed';\r\nlet modStoreHits = [];\r\n\r\nfunction switchModSubtab(tab) {\r\n  currentModSubtab = tab;\r\n  const btnInstalled = document.getElementById('subtab-installed');\r\n  const btnStore = document.getElementById('subtab-store');\r\n  const viewInstalled = document.getElementById('modSubviewInstalled');\r\n  const viewStore = document.getElementById('modSubviewStore');\r\n\r\n  if (tab === 'installed') {\r\n    btnInstalled.className = 'px-3 py-1.5 rounded-lg text-xs font-semibold bg-white text-black transition flex items-center gap-1.5';\r\n    btnStore.className = 'px-3 py-1.5 rounded-lg text-xs font-semibold bg-[#141414] hover:bg-[#202020] text-neutral-300 border border-[#333] transition flex items-center gap-1.5';\r\n    viewInstalled.classList.remove('hidden');\r\n    viewStore.classList.add('hidden');\r\n    loadModsList();\r\n  } else {\r\n    btnStore.className = 'px-3 py-1.5 rounded-lg text-xs font-semibold bg-white text-black transition flex items-center gap-1.5';\r\n    btnInstalled.className = 'px-3 py-1.5 rounded-lg text-xs font-semibold bg-[#141414] hover:bg-[#202020] text-neutral-300 border border-[#333] transition flex items-center gap-1.5';\r\n    viewStore.classList.remove('hidden');\r\n    viewInstalled.classList.add('hidden');\r\n    if (modStoreHits.length === 0) {\r\n      searchModrinthStore();\r\n    }\r\n  }\r\n}\r\n\r\nasync function searchModrinthStore(e) {\r\n  if (e) e.preventDefault();\r\n  const query = document.getElementById('modStoreQuery')?.value.trim() || '';\r\n  const catalogType = document.getElementById('modStoreCatalogType')?.value || 'mod';\r\n  const grid = document.getElementById('modStoreResultsGrid');\r\n  if (grid) {\r\n    grid.innerHTML = `<div class=\"col-span-full py-12 text-center text-neutral-500 text-xs font-mono\"><span class=\"w-2 h-2 rounded-full bg-white animate-ping inline-block mr-2\"></span>Searching Modrinth ${catalogType}s...</div>`;\r\n  }\r\n\r\n  try {\r\n    const version = activeInstanceData?.mcVersion || '';\r\n    const loader = activeInstanceData?.type || '';\r\n    const res = await fetch(`/api/modrinth/search?query=${encodeURIComponent(query)}&version=${encodeURIComponent(version)}&loader=${encodeURIComponent(loader)}&type=${encodeURIComponent(catalogType)}&limit=15`);\r\n    const data = await res.json();\r\n    modStoreHits = data.hits || [];\r\n    renderModStoreGrid(modStoreHits, catalogType);\r\n  } catch (err) {\r\n    if (grid) {\r\n      grid.innerHTML = `<div class=\"col-span-full py-12 text-center text-neutral-500 text-xs font-mono\">Failed to load Modrinth catalog: ${err.message}</div>`;\r\n    }\r\n  }\r\n}\r\n\r\nfunction quickStoreSearch(term, catalogType = 'mod') {\r\n  const input = document.getElementById('modStoreQuery');\r\n  const typeSelect = document.getElementById('modStoreCatalogType');\r\n  if (input) input.value = term;\r\n  if (typeSelect && catalogType) typeSelect.value = catalogType;\r\n  searchModrinthStore();\r\n}\r\n\r\nfunction renderModStoreGrid(hits, catalogType = 'mod') {\r\n  const grid = document.getElementById('modStoreResultsGrid');\r\n  if (!grid) return;\r\n\r\n  if (!hits || hits.length === 0) {\r\n    grid.innerHTML = '<div class=\"col-span-full py-12 text-center text-neutral-500 text-xs font-mono\">No items found matching your query.</div>';\r\n    return;\r\n  }\r\n\r\n  const isModpack = catalogType === 'modpack';\r\n\r\n  grid.innerHTML = hits.map(h => `\r\n    <div class=\"bg-[#0e0e0e] border border-[#222] hover:border-[#3a3a3a] rounded-xl p-3.5 flex flex-col justify-between transition\">\r\n      <div class=\"flex items-start gap-3\">\r\n        <img src=\"${h.iconUrl || 'https://cdn.jsdelivr.net/gh/twitter/twemoji@latest/assets/72x72/1f9e9.png'}\" class=\"w-10 h-10 rounded-lg object-cover bg-black border border-[#222] shrink-0\" onerror=\"this.src='https://cdn.jsdelivr.net/gh/twitter/twemoji@latest/assets/72x72/1f9e9.png'\">\r\n        <div class=\"min-w-0 flex-1\">\r\n          <div class=\"flex items-center justify-between gap-1\">\r\n            <h4 class=\"font-bold text-xs text-white truncate\" title=\"${h.title}\">${h.title}</h4>\r\n            ${isModpack ? '<span class=\"text-[9px] font-mono px-1.5 py-0.2 rounded bg-neutral-900 border border-[#333] text-neutral-300\">PACK</span>' : ''}\r\n          </div>\r\n          <p class=\"text-[11px] text-neutral-400 line-clamp-2 mt-1 leading-snug\">${h.description || 'No description provided'}</p>\r\n        </div>\r\n      </div>\r\n      <div class=\"mt-3 pt-2.5 border-t border-[#1a1a1a] flex items-center justify-between\">\r\n        <span class=\"text-[10px] text-neutral-500 font-mono\">📥 ${(h.downloads || 0).toLocaleString()}</span>\r\n        ${isModpack ? `\r\n          <a href=\"https://modrinth.com/modpack/${h.slug || h.id}\" target=\"_blank\" class=\"px-3 py-1 rounded-lg bg-[#141414] hover:bg-[#202020] text-neutral-200 border border-[#333] text-xs transition flex items-center gap-1\">\r\n            <i data-lucide=\"external-link\" class=\"w-3 h-3\"></i> View Pack\r\n          </a>\r\n        ` : `\r\n          <button onclick=\"installModrinthMod('${h.id}', '${h.title.replace(/'/g, \"\\\\'\")}')\" id=\"btnInstall-${h.id}\" class=\"px-3 py-1 rounded-lg bg-white hover:bg-neutral-200 text-black font-semibold text-xs transition flex items-center gap-1\">\r\n            <i data-lucide=\"download\" class=\"w-3 h-3\"></i> Install\r\n          </button>\r\n        `}\r\n      </div>\r\n    </div>\r\n  `).join('');\r\n\r\n  lucide.createIcons();\r\n}\r\n\r\nasync function installModrinthMod(projectId, title) {\r\n  const btn = document.getElementById(`btnInstall-${projectId}`);\r\n  if (btn) {\r\n    btn.disabled = true;\r\n    btn.className = 'px-3 py-1 rounded-lg bg-[#222] text-neutral-400 text-xs font-mono';\r\n    btn.textContent = 'Installing...';\r\n  }\r\n\r\n  try {\r\n    playSound('cmd');\r\n    showToast(`Downloading and installing ${title}...`, 'info');\r\n    const res = await fetch('/api/modrinth/install', {\r\n      method: 'POST',\r\n      headers: { 'Content-Type': 'application/json' },\r\n      body: JSON.stringify({ projectId })\r\n    });\r\n    const data = await res.json();\r\n    if (data.error) throw new Error(data.error);\r\n\r\n    playSound('alert');\r\n    showToast(`Installed: ${data.fileName}! (Restart server to load)`, 'success');\r\n    if (btn) {\r\n      btn.className = 'px-3 py-1 rounded-lg bg-black text-white border border-[#333] text-xs font-mono';\r\n      btn.textContent = 'Installed ✓';\r\n    }\r\n  } catch (e) {\r\n    showToast(`Install failed: ${e.message}`, 'error');\r\n    if (btn) {\r\n      btn.disabled = false;\r\n      btn.className = 'px-3 py-1 rounded-lg bg-white hover:bg-neutral-200 text-black font-semibold text-xs';\r\n      btn.textContent = 'Install';\r\n    }\r\n  }\r\n}\r\n\r\nasync function loadModsList() {\r\n  try {\r\n    const res = await fetch('/api/mods');\r\n    const data = await res.json();\r\n    cachedMods = data.mods || [];\r\n\r\n    document.getElementById('modStatTotal').textContent = data.totalCount;\r\n    document.getElementById('modStatEnabled').textContent = data.enabledCount;\r\n    document.getElementById('modStatDisabled').textContent = data.disabledCount;\r\n    document.getElementById('modStatSize').textContent = formatBytes(data.totalBytes);\r\n    document.getElementById('badgeModCount').textContent = data.totalCount;\r\n    const sideModBadge = document.getElementById('sidebarBadgeModCount');\r\n    if (sideModBadge) sideModBadge.textContent = data.totalCount;\r\n\r\n    const countSubtab = document.getElementById('modSubtabCount');\r\n    if (countSubtab) countSubtab.textContent = data.totalCount;\r\n\r\n    renderModsTable(cachedMods);\r\n  } catch (e) {\r\n    showToast(`Failed to load mods: ${e.message}`, 'error');\r\n  }\r\n}\r\n\r\nfunction renderModsTable(mods) {\r\n  const tbody = document.getElementById('modsTableBody');\r\n  if (!mods || mods.length === 0) {\r\n    tbody.innerHTML = `<tr><td colspan=\"4\" class=\"py-6 text-center text-neutral-500\">No matching mods found.</td></tr>`;\r\n    return;\r\n  }\r\n\r\n  tbody.innerHTML = mods.map(m => `\r\n    <tr class=\"hover:bg-[#121212] transition\">\r\n      <td class=\"py-2 px-4\">\r\n        <span class=\"inline-flex items-center gap-1.5 px-2 py-0.5 rounded text-[11px] font-mono font-medium ${m.enabled ? 'bg-white/10 text-white border border-white/20' : 'bg-neutral-900 text-neutral-500 border border-neutral-800'}\">\r\n          <span class=\"w-1.5 h-1.5 rounded-full ${m.enabled ? 'bg-white' : 'bg-neutral-600'}\"></span>\r\n          ${m.enabled ? 'Enabled' : 'Disabled'}\r\n        </span>\r\n      </td>\r\n      <td class=\"py-2 px-4 font-mono text-neutral-200\">\r\n        ${m.name}\r\n      </td>\r\n      <td class=\"py-2 px-4 font-mono text-neutral-400\">${formatBytes(m.size)}</td>\r\n      <td class=\"py-2 px-4 text-right\">\r\n        <button onclick=\"toggleMod('${m.fileName}')\" class=\"px-3 py-1 rounded-lg text-xs font-medium transition ${m.enabled ? 'bg-[#141414] hover:bg-[#222] text-neutral-300 border border-[#333]' : 'bg-white hover:bg-neutral-200 text-black font-semibold'}\">\r\n          ${m.enabled ? 'Disable' : 'Enable'}\r\n        </button>\r\n      </td>\r\n    </tr>\r\n  `).join('');\r\n}\r\n\r\nfunction filterModsList() {\r\n  const q = document.getElementById('modSearchInput').value.toLowerCase();\r\n  const filtered = cachedMods.filter(m => m.name.toLowerCase().includes(q) || m.fileName.toLowerCase().includes(q));\r\n  renderModsTable(filtered);\r\n}\r\n\r\nasync function toggleMod(fileName) {\r\n  try {\r\n    playSound('cmd');\r\n    const res = await fetch('/api/mods/toggle', {\r\n      method: 'POST',\r\n      headers: { 'Content-Type': 'application/json' },\r\n      body: JSON.stringify({ fileName })\r\n    });\r\n    const data = await res.json();\r\n    if (data.error) throw new Error(data.error);\r\n\r\n    showToast(`Mod ${data.enabled ? 'enabled' : 'disabled'}: ${data.newName}`, 'success');\r\n    loadModsList();\r\n  } catch (e) {\r\n    showToast(`Error: ${e.message}`, 'error');\r\n  }\r\n}\r\n\r\n// ================= PLAYER ROSTER & ACTIONS =================\r\nasync function loadPlayersData() {\r\n  try {\r\n    const res = await fetch('/api/players/data');\r\n    const data = await res.json();\r\n    const container = document.getElementById('playerCardsGrid');\r\n\r\n    if (!data.players || data.players.length === 0) {\r\n      container.innerHTML = `<div class=\"col-span-full py-8 text-center text-slate-500 text-xs\">No known players recorded in server yet.</div>`;\r\n      return;\r\n    }\r\n\r\n    container.innerHTML = data.players.map(p => `\r\n      <div class=\"bg-black border ${p.isOnline ? 'border-white/50' : 'border-[#222]'} rounded-xl p-4 flex flex-col justify-between\">\r\n        <div class=\"flex items-center gap-3\">\r\n          <img src=\"https://mc-heads.net/avatar/${encodeURIComponent(p.name)}/56\" alt=\"${p.name}\" class=\"w-11 h-11 rounded-lg border border-[#333] bg-[#141414]\" onerror=\"this.src='https://mc-heads.net/avatar/Steve/56'\">\r\n          <div class=\"flex-1 min-w-0\">\r\n            <div class=\"flex items-center gap-2\">\r\n              <h4 class=\"font-bold text-sm text-white truncate\">${p.name}</h4>\r\n              ${p.isOp ? '<span class=\"text-xs text-white font-bold\" title=\"Server Operator\">OP</span>' : ''}\r\n            </div>\r\n            <div class=\"flex items-center gap-1.5 mt-1\">\r\n              <span class=\"inline-flex items-center gap-1 text-[10px] font-mono px-2 py-0.2 rounded-full ${p.isOnline ? 'bg-white text-black font-semibold' : 'bg-[#141414] text-neutral-400 border border-[#262626]'}\">\r\n                <span class=\"w-1.5 h-1.5 rounded-full ${p.isOnline ? 'bg-black' : 'bg-neutral-600'}\"></span>\r\n                ${p.isOnline ? 'Online' : 'Offline'}\r\n              </span>\r\n              ${p.isBanned ? '<span class=\"text-[10px] font-mono bg-neutral-900 border border-[#333] text-neutral-400 px-1.5 rounded\">Banned</span>' : ''}\r\n              ${p.isWhitelisted ? '<span class=\"text-[10px] font-mono bg-white/10 text-white border border-white/20 px-1.5 rounded\">WL</span>' : ''}\r\n            </div>\r\n          </div>\r\n        </div>\r\n\r\n        <div class=\"mt-4 pt-3 border-t border-[#1e1e1e] flex items-center justify-between gap-1 text-xs\">\r\n          <button onclick=\"playerAction('${p.name}', '${p.isOp ? 'deop' : 'op'}')\" class=\"px-2 py-1 rounded bg-[#141414] hover:bg-[#222] text-neutral-300 border border-[#262626] transition text-[11px]\">\r\n            ${p.isOp ? 'De-OP' : 'OP'}\r\n          </button>\r\n          <button onclick=\"playerAction('${p.name}', '${p.isWhitelisted ? 'whitelist_remove' : 'whitelist_add'}')\" class=\"px-2 py-1 rounded bg-[#141414] hover:bg-[#222] text-neutral-300 border border-[#262626] transition text-[11px]\">\r\n            ${p.isWhitelisted ? '- WL' : '+ WL'}\r\n          </button>\r\n          <button onclick=\"playerAction('${p.name}', 'kick')\" class=\"px-2 py-1 rounded bg-[#141414] hover:bg-[#222] text-neutral-300 border border-[#262626] transition text-[11px]\">\r\n            Kick\r\n          </button>\r\n          <button onclick=\"playerAction('${p.name}', '${p.isBanned ? 'pardon' : 'ban'}')\" class=\"px-2 py-1 rounded bg-[#141414] hover:bg-neutral-900 text-neutral-400 hover:text-white border border-[#262626] transition text-[11px]\">\r\n            ${p.isBanned ? 'Unban' : 'Ban'}\r\n          </button>\r\n        </div>\r\n\r\n        <!-- In-Game Powers Row -->\r\n        <div class=\"mt-2 pt-2 border-t border-[#141414] flex flex-wrap items-center justify-between gap-1 text-[10px]\">\r\n          <span class=\"text-neutral-500 font-mono\">Powers:</span>\r\n          <button onclick=\"playerAction('${p.name}', 'give_diamonds')\" class=\"px-1.5 py-0.5 rounded bg-[#111] hover:bg-white hover:text-black border border-[#262626] text-neutral-300 transition\" title=\"Give 64x Diamonds\">💎 64x</button>\r\n          <button onclick=\"playerAction('${p.name}', 'heal')\" class=\"px-1.5 py-0.5 rounded bg-[#111] hover:bg-white hover:text-black border border-[#262626] text-neutral-300 transition\" title=\"Instant Health & Feed\">💖 Heal</button>\r\n          <button onclick=\"playerAction('${p.name}', 'gm_creative')\" class=\"px-1.5 py-0.5 rounded bg-[#111] hover:bg-white hover:text-black border border-[#262626] text-neutral-300 transition\" title=\"Set Gamemode: Creative\">⚡ Creative</button>\r\n          <button onclick=\"playerAction('${p.name}', 'gm_survival')\" class=\"px-1.5 py-0.5 rounded bg-[#111] hover:bg-white hover:text-black border border-[#262626] text-neutral-300 transition\" title=\"Set Gamemode: Survival\">🏹 Survival</button>\r\n        </div>\r\n      </div>\r\n    `).join('');\r\n\r\n    lucide.createIcons();\r\n  } catch (e) {\r\n    showToast(`Error loading players: ${e.message}`, 'error');\r\n  }\r\n}\r\n\r\nasync function playerAction(player, action) {\r\n  try {\r\n    playSound('cmd');\r\n    const res = await fetch('/api/players/action', {\r\n      method: 'POST',\r\n      headers: { 'Content-Type': 'application/json' },\r\n      body: JSON.stringify({ action, player })\r\n    });\r\n    const data = await res.json();\r\n    if (data.error) throw new Error(data.error);\r\n\r\n    showToast(`Action executed: ${data.command}`, 'success');\r\n    loadPlayersData();\r\n  } catch (e) {\r\n    showToast(`Action failed: ${e.message}`, 'error');\r\n  }\r\n}\r\n\r\nfunction handleQuickPlayerAction(e) {\r\n  e.preventDefault();\r\n  const input = document.getElementById('quickPlayerNameInput');\r\n  const action = document.getElementById('quickPlayerActionSelect').value;\r\n  const player = input.value.trim();\r\n  if (!player) return;\r\n\r\n  playerAction(player, action);\r\n  input.value = '';\r\n}\r\n\r\n// ================= STORAGE MANAGEMENT =================\r\nasync function loadStorageOverview() {\r\n  try {\r\n    const res = await fetch('/api/storage/overview');\r\n    const data = await res.json();\r\n\r\n    document.getElementById('dashTotalServerVal').textContent = formatBytes(data.totalServerSize);\r\n    document.getElementById('totalServerSize').textContent = formatBytes(data.totalServerSize);\r\n\r\n    const total = Math.max(data.totalServerSize, 1);\r\n    const pWorld = Math.max(1, Math.round((data.categories.world.size / total) * 100));\r\n    const pMods = Math.max(1, Math.round((data.categories.mods.size / total) * 100));\r\n    const pArch = Math.round((data.categories.archives.size / total) * 100);\r\n    const pLib = Math.round((data.categories.libraries.size / total) * 100);\r\n    const pLogs = Math.round((data.categories.logs.size / total) * 100);\r\n    const pOther = Math.max(0, 100 - (pWorld + pMods + pArch + pLib + pLogs));\r\n\r\n    document.getElementById('barWorld').style.width = `${pWorld}%`;\r\n    document.getElementById('barMods').style.width = `${pMods}%`;\r\n    document.getElementById('barArchives').style.width = `${pArch}%`;\r\n    document.getElementById('barLibraries').style.width = `${pLib}%`;\r\n    document.getElementById('barLogs').style.width = `${pLogs}%`;\r\n    document.getElementById('barOther').style.width = `${pOther}%`;\r\n\r\n    // Cleaner card values\r\n    document.getElementById('logCleanSize').textContent = `${formatBytes(data.categories.logs.oldLogsSize)} (${data.categories.logs.oldLogsCount} files)`;\r\n    document.getElementById('archiveZipSize').textContent = formatBytes(data.categories.archives.size);\r\n\r\n    const btnDelZip = document.getElementById('btnDeleteZip');\r\n    if (data.categories.archives.size === 0) {\r\n      btnDelZip.disabled = true;\r\n      btnDelZip.classList.add('opacity-40', 'cursor-not-allowed');\r\n      btnDelZip.textContent = 'Archive Already Deleted';\r\n    } else {\r\n      btnDelZip.disabled = false;\r\n      btnDelZip.classList.remove('opacity-40', 'cursor-not-allowed');\r\n      btnDelZip.innerHTML = `<i data-lucide=\"trash\" class=\"w-3.5 h-3.5\"></i> Delete Setup Zip (${formatBytes(data.categories.archives.size)})`;\r\n    }\r\n\r\n    // World breakdown\r\n    const wb = data.categories.world.breakdown;\r\n    document.getElementById('dimOverworld').textContent = formatBytes(wb.overworld);\r\n    document.getElementById('dimNether').textContent = formatBytes(wb.nether);\r\n    document.getElementById('dimEnd').textContent = formatBytes(wb.theEnd);\r\n    document.getElementById('dimPlayerdata').textContent = formatBytes(wb.playerdata);\r\n    document.getElementById('dimEntities').textContent = formatBytes(wb.entities);\r\n\r\n    // Update Storage Doughnut Chart\r\n    if (storageChart) {\r\n      const toMB = (bytes) => Math.round((bytes || 0) / (1024 * 1024));\r\n      storageChart.data.datasets[0].data = [\r\n        toMB(data.categories.world.size),\r\n        toMB(data.categories.mods.size),\r\n        toMB(data.categories.archives.size),\r\n        toMB(data.categories.libraries.size),\r\n        toMB(data.categories.logs.size),\r\n        toMB(data.categories.configs.size)\r\n      ];\r\n      storageChart.update();\r\n    }\r\n\r\n    lucide.createIcons();\r\n  } catch (e) {\r\n    console.error('Error loading storage overview:', e);\r\n  }\r\n}\r\n\r\nasync function quickCleanLogs() {\r\n  await cleanOldLogs();\r\n}\r\n\r\nasync function cleanOldLogs() {\r\n  try {\r\n    playSound('cmd');\r\n    showToast('Purging old compressed logs...', 'info');\r\n    const res = await fetch('/api/storage/clean-logs', { method: 'POST' });\r\n    const data = await res.json();\r\n    showToast(`Cleaned ${data.deletedCount} old logs, freed ${formatBytes(data.freedBytes)}!`, 'success');\r\n    loadStorageOverview();\r\n  } catch (e) {\r\n    showToast(`Failed to clean logs: ${e.message}`, 'error');\r\n  }\r\n}\r\n\r\nasync function cleanCache() {\r\n  try {\r\n    playSound('cmd');\r\n    showToast('Cleaning cache files and old crash logs...', 'info');\r\n    const res = await fetch('/api/storage/clean-cache', { method: 'POST' });\r\n    const data = await res.json();\r\n    showToast(`Cleaned ${data.deletedCount} temp items, freed ${formatBytes(data.freedBytes)}!`, 'success');\r\n    loadStorageOverview();\r\n  } catch (e) {\r\n    showToast(`Failed to clean cache: ${e.message}`, 'error');\r\n  }\r\n}\r\n\r\nasync function deleteSetupArchive() {\r\n  if (!confirm('Are you sure you want to delete the initial server pack ZIP? This will free ~782 MB of disk space. Only proceed if your server is already installed.')) {\r\n    return;\r\n  }\r\n  try {\r\n    playSound('cmd');\r\n    showToast('Deleting setup zip file...', 'info');\r\n    const res = await fetch('/api/storage/delete-file', {\r\n      method: 'POST',\r\n      headers: { 'Content-Type': 'application/json' },\r\n      body: JSON.stringify({ relativePath: 'CARPG Ultimate V7b Serv.zip' })\r\n    });\r\n    const data = await res.json();\r\n    if (data.error) throw new Error(data.error);\r\n    showToast(`Successfully deleted setup archive! Freed ${formatBytes(data.freedBytes)}!`, 'success');\r\n    loadStorageOverview();\r\n  } catch (e) {\r\n    showToast(`Error: ${e.message}`, 'error');\r\n  }\r\n}\r\n\r\nasync function triggerWorldBackup() {\r\n  try {\r\n    playSound('cmd');\r\n    showToast('Creating world backup (.zip)... This may take 30-60 seconds for large worlds.', 'info');\r\n    const res = await fetch('/api/storage/backup', { method: 'POST' });\r\n    const data = await res.json();\r\n    if (data.error) throw new Error(data.error);\r\n    playSound('alert');\r\n    showToast(`Backup created: ${data.fileName} (${formatBytes(data.size)})`, 'success');\r\n    loadBackups();\r\n    loadStorageOverview();\r\n  } catch (e) {\r\n    showToast(`Backup failed: ${e.message}`, 'error');\r\n  }\r\n}\r\n\r\nasync function loadBackups() {\r\n  try {\r\n    const res = await fetch('/api/storage/backups');\r\n    const backups = await res.json();\r\n    const tbody = document.getElementById('backupTableBody');\r\n\r\n    if (!backups || backups.length === 0) {\r\n      tbody.innerHTML = `<tr><td colspan=\"4\" class=\"py-6 text-center text-neutral-500\">No backups created yet. Click \"New Backup\" above to create one.</td></tr>`;\r\n      return;\r\n    }\r\n\r\n    tbody.innerHTML = backups.map(b => `\r\n      <tr class=\"hover:bg-[#121212] transition\">\r\n        <td class=\"py-2.5 px-4 font-mono font-medium text-white flex items-center gap-2\">\r\n          <i data-lucide=\"archive\" class=\"w-4 h-4 text-white\"></i> ${b.name}\r\n        </td>\r\n        <td class=\"py-2.5 px-4 font-mono text-neutral-400\">${formatBytes(b.size)}</td>\r\n        <td class=\"py-2.5 px-4 text-neutral-400 font-mono text-[11px]\">${new Date(b.mtime).toLocaleString()}</td>\r\n        <td class=\"py-2.5 px-4 text-right space-x-1.5\">\r\n          <button onclick=\"restoreBackupFile('${b.name}')\" class=\"px-2.5 py-1 rounded bg-white hover:bg-neutral-200 text-black font-semibold inline-flex items-center gap-1 transition\" title=\"Restore world from this backup\">\r\n            <i data-lucide=\"rotate-ccw\" class=\"w-3 h-3\"></i> Restore\r\n          </button>\r\n          <a href=\"/api/storage/download-backup/${encodeURIComponent(b.name)}\" class=\"px-2.5 py-1 rounded bg-[#141414] hover:bg-[#202020] text-neutral-200 border border-[#333] font-medium inline-flex items-center gap-1 transition\">\r\n            <i data-lucide=\"download\" class=\"w-3 h-3\"></i> Download\r\n          </a>\r\n          <button onclick=\"deleteBackupFile('${b.name}')\" class=\"px-2.5 py-1 rounded bg-[#141414] hover:bg-neutral-900 text-neutral-400 hover:text-white border border-[#262626] font-medium inline-flex items-center gap-1 transition\">\r\n            <i data-lucide=\"trash-2\" class=\"w-3 h-3\"></i> Delete\r\n          </button>\r\n        </td>\r\n      </tr>\r\n    `).join('');\r\n\r\n    lucide.createIcons();\r\n  } catch (e) {\r\n    console.error('Error loading backups:', e);\r\n  }\r\n}\r\n\r\nasync function restoreBackupFile(name) {\r\n  if (serverStatus !== 'offline') {\r\n    showToast('Please stop the server before restoring a backup!', 'warning');\r\n    return;\r\n  }\r\n  if (!confirm(`Restore world from \"${name}\"? Current world state will be safely archived beforehand.`)) {\r\n    return;\r\n  }\r\n\r\n  try {\r\n    playSound('cmd');\r\n    showToast(`Restoring backup \"${name}\"...`, 'info');\r\n    const res = await fetch('/api/storage/restore', {\r\n      method: 'POST',\r\n      headers: { 'Content-Type': 'application/json' },\r\n      body: JSON.stringify({ fileName: name })\r\n    });\r\n    const data = await res.json();\r\n    if (data.error) throw new Error(data.error);\r\n\r\n    playSound('alert');\r\n    showToast(`World successfully restored from ${name}! (${formatBytes(data.restoredSize)})`, 'success');\r\n    loadStorageOverview();\r\n  } catch (err) {\r\n    showToast(`Restore failed: ${err.message}`, 'error');\r\n  }\r\n}\r\n\r\nasync function deleteBackupFile(name) {\r\n  if (!confirm(`Delete backup \"${name}\"?`)) return;\r\n  try {\r\n    playSound('cmd');\r\n    const res = await fetch('/api/storage/delete-file', {\r\n      method: 'POST',\r\n      headers: { 'Content-Type': 'application/json' },\r\n      body: JSON.stringify({ relativePath: `backups/${name}` })\r\n    });\r\n    const data = await res.json();\r\n    showToast(`Deleted backup: ${name}`, 'success');\r\n    loadBackups();\r\n    loadStorageOverview();\r\n  } catch (e) {\r\n    showToast(`Delete failed: ${e.message}`, 'error');\r\n  }\r\n}\r\n\r\n// ================= FILE EXPLORER =================\r\nasync function loadFiles(relPath) {\r\n  currentFilePath = relPath;\r\n  try {\r\n    const res = await fetch(`/api/files?path=${encodeURIComponent(relPath)}`);\r\n    const data = await res.json();\r\n\r\n    const crumbs = relPath.split('/').filter(Boolean);\r\n    let breadcrumbHtml = `<button onclick=\"loadFiles('')\" class=\"hover:text-emerald-400\">root</button>`;\r\n    let accumulated = '';\r\n    crumbs.forEach(c => {\r\n      accumulated += (accumulated ? '/' : '') + c;\r\n      const target = accumulated;\r\n      breadcrumbHtml += ` <span class=\"text-slate-600\">/</span> <button onclick=\"loadFiles('${target}')\" class=\"hover:text-emerald-400\">${c}</button>`;\r\n    });\r\n    document.getElementById('filePathBreadcrumbs').innerHTML = breadcrumbHtml;\r\n\r\n    const tbody = document.getElementById('fileExplorerBody');\r\n    let rows = '';\r\n\r\n    if (relPath) {\r\n      const parent = crumbs.slice(0, -1).join('/');\r\n      rows += `\r\n        <tr class=\"hover:bg-[#121212] cursor-pointer transition\" onclick=\"loadFiles('${parent}')\">\r\n          <td class=\"py-2.5 px-4 font-mono font-medium text-white flex items-center gap-2\">\r\n            <i data-lucide=\"corner-left-up\" class=\"w-4 h-4 text-white\"></i> .. (Parent Directory)\r\n          </td>\r\n          <td class=\"py-2.5 px-4 text-neutral-500\">--</td>\r\n          <td class=\"py-2.5 px-4 text-neutral-500\">--</td>\r\n          <td class=\"py-2.5 px-4 text-right\"></td>\r\n        </tr>\r\n      `;\r\n    }\r\n\r\n    if (data.items.length === 0) {\r\n      rows += `<tr><td colspan=\"4\" class=\"py-6 text-center text-neutral-500\">Folder is empty</td></tr>`;\r\n    } else {\r\n      data.items.forEach(item => {\r\n        const itemRelPath = (relPath ? relPath + '/' : '') + item.name;\r\n        if (item.isDirectory) {\r\n          rows += `\r\n            <tr class=\"hover:bg-[#121212] cursor-pointer transition\" onclick=\"loadFiles('${itemRelPath}')\">\r\n              <td class=\"py-2.5 px-4 font-medium text-white flex items-center gap-2\">\r\n                <i data-lucide=\"folder\" class=\"w-4 h-4 text-white\"></i> ${item.name}\r\n              </td>\r\n              <td class=\"py-2.5 px-4 text-neutral-500\">--</td>\r\n              <td class=\"py-2.5 px-4 text-neutral-400 font-mono text-[11px]\">${new Date(item.mtime).toLocaleDateString()}</td>\r\n              <td class=\"py-2.5 px-4 text-right\">\r\n                <span class=\"text-neutral-500 text-xs\">Folder</span>\r\n              </td>\r\n            </tr>\r\n          `;\r\n        } else {\r\n          const isEditable = item.name.endsWith('.txt') || item.name.endsWith('.properties') || item.name.endsWith('.json') || item.name.endsWith('.toml') || item.name.endsWith('.cfg') || item.name.endsWith('.log') || item.name.endsWith('.sh') || item.name.endsWith('.ps1');\r\n          rows += `\r\n            <tr class=\"hover:bg-[#121212] transition\">\r\n              <td class=\"py-2.5 px-4 font-mono text-neutral-300 flex items-center gap-2\">\r\n                <i data-lucide=\"file-text\" class=\"w-4 h-4 text-neutral-400\"></i> ${item.name}\r\n              </td>\r\n              <td class=\"py-2.5 px-4 font-mono text-neutral-400\">${formatBytes(item.size)}</td>\r\n              <td class=\"py-2.5 px-4 text-neutral-400 font-mono text-[11px]\">${new Date(item.mtime).toLocaleDateString()}</td>\r\n              <td class=\"py-2.5 px-4 text-right\">\r\n                ${isEditable ? `\r\n                  <button onclick=\"openFileEditor('${itemRelPath}')\" class=\"px-2.5 py-1 rounded bg-[#141414] hover:bg-[#222] text-white border border-[#333] text-xs transition\">\r\n                    Edit\r\n                  </button>\r\n                ` : `<span class=\"text-neutral-600 text-xs\">Binary</span>`}\r\n              </td>\r\n            </tr>\r\n          `;\r\n        }\r\n      });\r\n    }\r\n\r\n    tbody.innerHTML = rows;\r\n    lucide.createIcons();\r\n  } catch (e) {\r\n    showToast(`Error loading files: ${e.message}`, 'error');\r\n  }\r\n}\r\n\r\nfunction refreshCurrentFolder() {\r\n  loadFiles(currentFilePath);\r\n}\r\n\r\n// In-Browser File Editor\r\nasync function openFileEditor(filePath) {\r\n  editingFilePath = filePath;\r\n  try {\r\n    playSound('cmd');\r\n    const res = await fetch(`/api/file-content?path=${encodeURIComponent(filePath)}`);\r\n    const data = await res.json();\r\n    if (data.error) throw new Error(data.error);\r\n\r\n    document.getElementById('editorFileName').textContent = filePath;\r\n    document.getElementById('editorContent').value = data.content;\r\n    document.getElementById('fileEditorModal').classList.remove('hidden');\r\n  } catch (e) {\r\n    showToast(`Cannot open file: ${e.message}`, 'error');\r\n  }\r\n}\r\n\r\nfunction closeFileEditor() {\r\n  document.getElementById('fileEditorModal').classList.add('hidden');\r\n  editingFilePath = '';\r\n}\r\n\r\nasync function saveFileEditor() {\r\n  if (!editingFilePath) return;\r\n  const content = document.getElementById('editorContent').value;\r\n  try {\r\n    playSound('cmd');\r\n    const res = await fetch('/api/file-content', {\r\n      method: 'POST',\r\n      headers: { 'Content-Type': 'application/json' },\r\n      body: JSON.stringify({ path: editingFilePath, content })\r\n    });\r\n    const data = await res.json();\r\n    if (data.error) throw new Error(data.error);\r\n    showToast(`Saved changes to ${editingFilePath}`, 'success');\r\n    closeFileEditor();\r\n  } catch (e) {\r\n    showToast(`Save failed: ${e.message}`, 'error');\r\n  }\r\n}\r\n\r\n// ================= SETTINGS & PROPERTIES =================\r\nasync function loadSettings() {\r\n  try {\r\n    const res = await fetch('/api/config');\r\n    const data = await res.json();\r\n\r\n    if (data.launch) {\r\n      document.getElementById('cfgMaxRam').value = data.launch.maxRam || '6G';\r\n      document.getElementById('cfgMinRam').value = data.launch.minRam || '4G';\r\n      document.getElementById('cfgJavaPath').value = data.launch.javaPath || 'java';\r\n      document.getElementById('cfgAutoRestart').checked = !!data.launch.autoRestart;\r\n    }\r\n\r\n    if (data.properties) {\r\n      document.getElementById('propPort').value = data.properties['server-port'] || '25402';\r\n      document.getElementById('propMaxPlayers').value = data.properties['max-players'] || '5';\r\n      document.getElementById('propMotd').value = data.properties['motd'] || 'Minecraft Server';\r\n      document.getElementById('propGamemode').value = data.properties['gamemode'] || 'survival';\r\n      document.getElementById('propDifficulty').value = data.properties['difficulty'] || 'easy';\r\n      document.getElementById('propOnlineMode').value = data.properties['online-mode'] || 'false';\r\n      document.getElementById('propPvp').value = data.properties['pvp'] || 'true';\r\n    }\r\n  } catch (e) {\r\n    console.error('Error loading settings:', e);\r\n  }\r\n}\r\n\r\nfunction setRam(ram) {\r\n  document.getElementById('cfgMaxRam').value = ram;\r\n}\r\n\r\nasync function saveLaunchSettings(e) {\r\n  e.preventDefault();\r\n  const maxRam = document.getElementById('cfgMaxRam').value.trim();\r\n  const minRam = document.getElementById('cfgMinRam').value.trim();\r\n  const javaPath = document.getElementById('cfgJavaPath').value.trim();\r\n  const autoRestart = document.getElementById('cfgAutoRestart').checked;\r\n\r\n  try {\r\n    playSound('cmd');\r\n    const res = await fetch('/api/config/launch', {\r\n      method: 'POST',\r\n      headers: { 'Content-Type': 'application/json' },\r\n      body: JSON.stringify({ maxRam, minRam, javaPath, autoRestart })\r\n    });\r\n    const data = await res.json();\r\n    if (data.error) throw new Error(data.error);\r\n    showToast('Launch settings & JVM arguments saved!', 'success');\r\n  } catch (e) {\r\n    showToast(`Error: ${e.message}`, 'error');\r\n  }\r\n}\r\n\r\nasync function savePropertiesSettings(e) {\r\n  e.preventDefault();\r\n  const port = document.getElementById('propPort').value.trim();\r\n  const maxPlayers = document.getElementById('propMaxPlayers').value.trim();\r\n  const motd = document.getElementById('propMotd').value.trim();\r\n  const gamemode = document.getElementById('propGamemode').value;\r\n  const difficulty = document.getElementById('propDifficulty').value;\r\n  const onlineMode = document.getElementById('propOnlineMode').value;\r\n  const pvp = document.getElementById('propPvp').value;\r\n\r\n  try {\r\n    playSound('cmd');\r\n    const res = await fetch('/api/config/properties', {\r\n      method: 'POST',\r\n      headers: { 'Content-Type': 'application/json' },\r\n      body: JSON.stringify({\r\n        'server-port': port,\r\n        'query.port': port,\r\n        'max-players': maxPlayers,\r\n        'motd': motd,\r\n        'gamemode': gamemode,\r\n        'difficulty': difficulty,\r\n        'online-mode': onlineMode,\r\n        'pvp': pvp\r\n      })\r\n    });\r\n    const data = await res.json();\r\n    if (data.error) throw new Error(data.error);\r\n    showToast('Server properties saved! (Restart server to apply)', 'success');\r\n  } catch (e) {\r\n    showToast(`Error: ${e.message}`, 'error');\r\n  }\r\n}\r\n\r\n// ================= LANGUAGE & LOCALIZATION (i18n) =================\r\nlet currentLang = localStorage.getItem('craftorbit_lang') || 'en';\r\n\r\nconst i18nDictionary = {\r\n  en: {\r\n    layout_pref_title: \"Dashboard Layout & Navigation Preference\",\r\n    layout_pref_desc: \"Choose your preferred dashboard navigation style. Your preference is automatically remembered across sessions.\",\r\n    layout_sidebar_title: \"Left Sidebar (Argonara / Pterodactyl)\",\r\n    layout_sidebar_desc: \"Full-height vertical sidebar on the left with General, Management, and Palette categories. Gives your workspace maximum horizontal breathing room.\",\r\n    layout_topbar_title: \"Top Horizontal Tabs\",\r\n    layout_topbar_desc: \"Compact horizontal tab strip across the top header. Best for compact displays or classic minimalist view.\",\r\n    lang_pref_title: \"Language & Localization\",\r\n    lang_pref_desc: \"Select your preferred interface display language. Changes take effect instantly across all panels.\",\r\n    toast_invite_copied: \"Copied full multiplayer invite message!\",\r\n    toast_lang_changed: \"Language changed to English (US)\",\r\n    invite_header: \"🎮 Join our Minecraft Server!\",\r\n    invite_server: \"🏷️ Server\",\r\n    invite_how_to: \"👉 How to Connect:\\n1. Open Minecraft -> Multiplayer / Servers\\n2. Direct Connection / Add Server\\n3. Enter the server address -> Connect & Play!\"\r\n  },\r\n  id: {\r\n    layout_pref_title: \"Tata Letak Dashboard & Pilihan Navigasi\",\r\n    layout_pref_desc: \"Pilih gaya navigasi dashboard sesuai kenyamanan Anda. Pilihan disimpan otomatis di browser.\",\r\n    layout_sidebar_title: \"Sidebar Kiri (Gaya Argonara / Pterodactyl)\",\r\n    layout_sidebar_desc: \"Menu vertikal lengkap di sisi kiri dengan kategori General, Management, dan Quick Palette. Area workspace lebih leluasa.\",\r\n    layout_topbar_title: \"Tab Horizontal Atas\",\r\n    layout_topbar_desc: \"Menu horizontal ringkas di bagian atas header. Cocok untuk layar kompak atau tampilan minimalis klasik.\",\r\n    lang_pref_title: \"Bahasa & Lokalisasi\",\r\n    lang_pref_desc: \"Pilih bahasa tampilan antarmuka. Perubahan langsung aktif seketika tanpa perlu restart.\",\r\n    toast_invite_copied: \"Berhasil menyalin pesan mabar lengkap!\",\r\n    toast_lang_changed: \"Bahasa diubah ke Bahasa Indonesia\",\r\n    invite_header: \"🎮 Ayo Mabar Minecraft!\",\r\n    invite_server: \"🏷️ Server\",\r\n    invite_how_to: \"👉 Cara Connect:\\n1. Buka Minecraft -> Multiplayer / Servers\\n2. Direct Connection / Add Server\\n3. Masukkan address sesuai koneksimu -> Join!\"\r\n  }\r\n};\r\n\r\nfunction initLanguage() {\r\n  setLanguage(currentLang, false);\r\n}\r\n\r\nfunction toggleLangDropdown(event) {\r\n  if (event) event.stopPropagation();\r\n  const menu = document.getElementById('langDropdown');\r\n  if (menu) menu.classList.toggle('hidden');\r\n}\r\n\r\nfunction setLanguage(lang, showNotification = true) {\r\n  currentLang = lang;\r\n  localStorage.setItem('craftorbit_lang', lang);\r\n\r\n  // Close dropdown\r\n  const menu = document.getElementById('langDropdown');\r\n  if (menu) menu.classList.add('hidden');\r\n\r\n  // Update badges\r\n  const headerBadge = document.getElementById('headerLangBadge');\r\n  const sidebarBadge = document.getElementById('sidebarLangCode');\r\n  if (headerBadge) headerBadge.textContent = lang.toUpperCase();\r\n  if (sidebarBadge) sidebarBadge.textContent = lang.toUpperCase();\r\n\r\n  // Update Dropdown Checks\r\n  const checkEn = document.getElementById('langCheck-en');\r\n  const checkId = document.getElementById('langCheck-id');\r\n  if (checkEn) {\r\n    checkEn.textContent = lang === 'en' ? '✓' : '';\r\n    checkEn.className = lang === 'en' ? 'text-emerald-400 font-bold text-[11px]' : 'text-neutral-600 text-[11px]';\r\n  }\r\n  if (checkId) {\r\n    checkId.textContent = lang === 'id' ? '✓' : '';\r\n    checkId.className = lang === 'id' ? 'text-emerald-400 font-bold text-[11px]' : 'text-neutral-600 text-[11px]';\r\n  }\r\n\r\n  // Update Settings Tab Cards\r\n  const cardEn = document.getElementById('langCardEn');\r\n  const cardId = document.getElementById('langCardId');\r\n  const checkSettingEn = document.getElementById('langSettingCheck-en');\r\n  const checkSettingId = document.getElementById('langSettingCheck-id');\r\n\r\n  if (cardEn && cardId) {\r\n    if (lang === 'en') {\r\n      cardEn.classList.add('border-emerald-500', 'bg-[#0f181f]');\r\n      cardEn.classList.remove('border-[#2e2e2e]', 'bg-black');\r\n      if (checkSettingEn) {\r\n        checkSettingEn.textContent = 'ACTIVE';\r\n        checkSettingEn.className = 'text-emerald-400 text-xs font-mono font-bold';\r\n      }\r\n      cardId.classList.remove('border-emerald-500', 'bg-[#0f181f]');\r\n      cardId.classList.add('border-[#2e2e2e]', 'bg-black');\r\n      if (checkSettingId) {\r\n        checkSettingId.textContent = 'SELECT';\r\n        checkSettingId.className = 'text-neutral-500 text-xs font-mono';\r\n      }\r\n    } else {\r\n      cardId.classList.add('border-emerald-500', 'bg-[#0f181f]');\r\n      cardId.classList.remove('border-[#2e2e2e]', 'bg-black');\r\n      if (checkSettingId) {\r\n        checkSettingId.textContent = 'ACTIVE';\r\n        checkSettingId.className = 'text-emerald-400 text-xs font-mono font-bold';\r\n      }\r\n      cardEn.classList.remove('border-emerald-500', 'bg-[#0f181f]');\r\n      cardEn.classList.add('border-[#2e2e2e]', 'bg-black');\r\n      if (checkSettingEn) {\r\n        checkSettingEn.textContent = 'SELECT';\r\n        checkSettingEn.className = 'text-neutral-500 text-xs font-mono';\r\n      }\r\n    }\r\n  }\r\n\r\n  // Update DOM elements with data-i18n\r\n  const dict = i18nDictionary[lang] || i18nDictionary['en'];\r\n  document.querySelectorAll('[data-i18n]').forEach(el => {\r\n    const key = el.getAttribute('data-i18n');\r\n    if (dict[key]) {\r\n      el.textContent = dict[key];\r\n    }\r\n  });\r\n\r\n  if (showNotification) {\r\n    showToast(dict.toast_lang_changed || 'Language updated', 'info');\r\n  }\r\n}\r\n\r\n// Global click outside listener to close dropdowns\r\nwindow.addEventListener('click', (e) => {\r\n  const langMenu = document.getElementById('langDropdown');\r\n  if (langMenu && !langMenu.contains(e.target) && !e.target.closest('button[onclick*=\"toggleLangDropdown\"]')) {\r\n    langMenu.classList.add('hidden');\r\n  }\r\n});\r\n\r\n// ================= LAYOUT MODE SWITCHER (SIDEBAR vs TOPBAR) =================\r\nlet currentLayoutMode = localStorage.getItem('craftorbit_layout_mode') || 'sidebar';\r\n\r\nfunction initLayoutMode() {\r\n  setLayoutMode(currentLayoutMode, false);\r\n}\r\n\r\nfunction toggleLayoutMode() {\r\n  const newMode = currentLayoutMode === 'sidebar' ? 'topbar' : 'sidebar';\r\n  setLayoutMode(newMode, true);\r\n}\r\n\r\nfunction setLayoutMode(mode, showNotification = true) {\r\n  currentLayoutMode = mode;\r\n  localStorage.setItem('craftorbit_layout_mode', mode);\r\n\r\n  const appShell = document.getElementById('appShell');\r\n  const headerLayoutLabel = document.getElementById('headerLayoutLabel');\r\n  const layoutModeLabel = document.getElementById('layoutModeLabel');\r\n  const cardSidebar = document.getElementById('layoutCardSidebar');\r\n  const cardTopbar = document.getElementById('layoutCardTopbar');\r\n  const checkSidebar = document.getElementById('layoutCheckSidebar');\r\n  const checkTopbar = document.getElementById('layoutCheckTopbar');\r\n\r\n  if (appShell) {\r\n    if (mode === 'sidebar') {\r\n      appShell.classList.add('mode-sidebar');\r\n      appShell.classList.remove('mode-topbar');\r\n    } else {\r\n      appShell.classList.add('mode-topbar');\r\n      appShell.classList.remove('mode-sidebar');\r\n    }\r\n  }\r\n\r\n  if (headerLayoutLabel) {\r\n    headerLayoutLabel.textContent = mode === 'sidebar' ? 'Sidebar Mode' : 'Top Bar Mode';\r\n  }\r\n  if (layoutModeLabel) {\r\n    layoutModeLabel.textContent = mode === 'sidebar' ? 'Sidebar' : 'Top Bar';\r\n  }\r\n\r\n  if (cardSidebar && cardTopbar) {\r\n    if (mode === 'sidebar') {\r\n      cardSidebar.classList.add('border-emerald-500', 'bg-[#0f181f]');\r\n      cardSidebar.classList.remove('border-[#2e2e2e]', 'bg-black');\r\n      if (checkSidebar) {\r\n        checkSidebar.textContent = 'ACTIVE';\r\n        checkSidebar.className = 'text-emerald-400 text-xs font-mono font-bold';\r\n      }\r\n      cardTopbar.classList.remove('border-emerald-500', 'bg-[#0f181f]');\r\n      cardTopbar.classList.add('border-[#2e2e2e]', 'bg-black');\r\n      if (checkTopbar) {\r\n        checkTopbar.textContent = 'SELECT';\r\n        checkTopbar.className = 'text-neutral-500 text-xs font-mono';\r\n      }\r\n    } else {\r\n      cardTopbar.classList.add('border-emerald-500', 'bg-[#0f181f]');\r\n      cardTopbar.classList.remove('border-[#2e2e2e]', 'bg-black');\r\n      if (checkTopbar) {\r\n        checkTopbar.textContent = 'ACTIVE';\r\n        checkTopbar.className = 'text-emerald-400 text-xs font-mono font-bold';\r\n      }\r\n      cardSidebar.classList.remove('border-emerald-500', 'bg-[#0f181f]');\r\n      cardSidebar.classList.add('border-[#2e2e2e]', 'bg-black');\r\n      if (checkSidebar) {\r\n        checkSidebar.textContent = 'SELECT';\r\n        checkSidebar.className = 'text-neutral-500 text-xs font-mono';\r\n      }\r\n    }\r\n  }\r\n\r\n  if (window.lucide) lucide.createIcons();\r\n\r\n  if (showNotification) {\r\n    showToast(mode === 'sidebar' ? 'Switched to Left Sidebar Navigation' : 'Switched to Top Navigation Bar', 'info');\r\n  }\r\n}\r\n\r\n// Initial Load\r\nwindow.addEventListener('DOMContentLoaded', () => {\r\n  initLanguage();\r\n  initLayoutMode();\r\n  initTelemetryCharts();\r\n  connectWebSocket();\r\n  loadInstances();\r\n  loadStorageOverview();\r\n  loadModsList();\r\n  lucide.createIcons();\r\n\r\n  const icon = document.getElementById('soundIcon');\r\n  if (icon) {\r\n    icon.setAttribute('data-lucide', audioEnabled ? 'volume-2' : 'volume-x');\r\n    lucide.createIcons();\r\n  }\r\n});\r\n\r\n// ================= MULTI-INSTANCE UNIVERSAL MANAGEMENT =================\r\nlet allInstances = [];\r\nlet activeInstanceData = null;\r\n\r\nasync function loadInstances() {\r\n  try {\r\n    const res = await fetch('/api/instances');\r\n    const data = await res.json();\r\n    allInstances = data.instances || [];\r\n    activeInstanceData = data.activeInstance;\r\n\r\n    // Update Header, Sidebar & Workspace Hero Card\r\n    const sideName = document.getElementById('sidebarInstanceName');\r\n    const sideBadge = document.getElementById('sidebarInstanceTypeBadge');\r\n    const heroName = document.getElementById('heroServerName');\r\n    const heroBadge = document.getElementById('heroEngineBadge');\r\n    const heroIp = document.getElementById('heroServerIpDisplay');\r\n\r\n    if (activeInstanceData && activeInstanceData.id !== 'none') {\r\n      document.getElementById('headerInstanceName').textContent = activeInstanceData.name;\r\n      const typeBadge = document.getElementById('headerInstanceTypeBadge');\r\n      typeBadge.textContent = activeInstanceData.detectedEngine || activeInstanceData.type.toUpperCase();\r\n      \r\n      if (sideName) sideName.textContent = activeInstanceData.name;\r\n      if (sideBadge) sideBadge.textContent = activeInstanceData.detectedEngine || activeInstanceData.type.toUpperCase();\r\n      if (heroName) heroName.textContent = activeInstanceData.name;\r\n      if (heroBadge) heroBadge.textContent = activeInstanceData.detectedEngine || activeInstanceData.type.toUpperCase();\r\n\r\n      const folderName = activeInstanceData.path.split(/[/\\\\]/).pop();\r\n      document.getElementById('headerServerFolder').textContent = folderName;\r\n      document.getElementById('headerServerFolder').title = activeInstanceData.path;\r\n\r\n      // Update port in header if known\r\n      const port = activeInstanceData.port || (activeInstanceData.type === 'bedrock' ? 19132 : 25402);\r\n      document.getElementById('headerServerIp').textContent = `localhost:${port}`;\r\n      if (heroIp) heroIp.textContent = `localhost:${port}`;\r\n    } else {\r\n      document.getElementById('headerInstanceName').textContent = 'No Server Selected';\r\n      document.getElementById('headerInstanceTypeBadge').textContent = 'START';\r\n      if (sideName) sideName.textContent = 'No Server Selected';\r\n      if (sideBadge) sideBadge.textContent = 'START';\r\n      if (heroName) heroName.textContent = 'No Server Selected';\r\n      if (heroBadge) heroBadge.textContent = 'STANDBY';\r\n      document.getElementById('headerServerFolder').textContent = 'Click Host World to begin';\r\n      document.getElementById('headerServerIp').textContent = 'localhost:25565';\r\n      if (heroIp) heroIp.textContent = 'localhost:25565';\r\n    }\r\n\r\n    // Render Dropdown List\r\n    const listEl = document.getElementById('instanceMenuList');\r\n    if (listEl) {\r\n      if (allInstances.length === 0) {\r\n        listEl.innerHTML = '<div class=\"p-3 text-center text-xs text-neutral-500\">No servers registered yet.<br>Click below to host a world!</div>';\r\n      } else {\r\n        listEl.innerHTML = allInstances.map(inst => `\r\n          <div onclick=\"switchInstance('${inst.id}')\" class=\"p-2 rounded-lg cursor-pointer transition flex items-center justify-between ${inst.isActive ? 'bg-[#1a1a1a] border border-[#333]' : 'hover:bg-[#141414] border border-transparent'}\">\r\n            <div class=\"min-w-0 flex-1 pr-2\">\r\n              <div class=\"flex items-center gap-1.5\">\r\n                <strong class=\"text-xs text-white truncate\">${inst.name}</strong>\r\n                ${inst.isActive ? '<span class=\"text-[9px] uppercase px-1 py-0.2 bg-white text-black font-bold rounded\">active</span>' : ''}\r\n              </div>\r\n              <div class=\"text-[10px] text-neutral-400 font-mono truncate mt-0.5\">${inst.detectedEngine || inst.type} &bull; ${inst.path}</div>\r\n            </div>\r\n            ${!inst.isActive && !inst.isRunning ? `\r\n              <button onclick=\"event.stopPropagation(); deleteInstance('${inst.id}', '${inst.name}')\" class=\"p-1 text-neutral-500 hover:text-white rounded transition\" title=\"Remove from list\">\r\n                <i data-lucide=\"trash-2\" class=\"w-3.5 h-3.5\"></i>\r\n              </button>\r\n            ` : ''}\r\n          </div>\r\n        `).join('');\r\n      }\r\n    }\r\n\r\n    lucide.createIcons();\r\n  } catch (e) {\r\n    console.error('Error loading instances:', e);\r\n  }\r\n}\r\n\r\nfunction toggleInstanceMenu(e) {\r\n  if (e) e.stopPropagation();\r\n  const menu = document.getElementById('instanceMenu');\r\n  if (menu) menu.classList.toggle('hidden');\r\n}\r\n\r\n// Click outside to close instance menu\r\ndocument.addEventListener('click', (e) => {\r\n  const menu = document.getElementById('instanceMenu');\r\n  if (menu && !menu.classList.contains('hidden') && !menu.contains(e.target) && !e.target.closest('button[onclick*=\"toggleInstanceMenu\"]')) {\r\n    menu.classList.add('hidden');\r\n  }\r\n});\r\n\r\nasync function switchInstance(id) {\r\n  try {\r\n    playSound('cmd');\r\n    showToast('Switching server instance...', 'info');\r\n    const res = await fetch('/api/instances/switch', {\r\n      method: 'POST',\r\n      headers: { 'Content-Type': 'application/json' },\r\n      body: JSON.stringify({ id })\r\n    });\r\n    const data = await res.json();\r\n    if (data.error) throw new Error(data.error);\r\n\r\n    const menu = document.getElementById('instanceMenu');\r\n    if (menu) menu.classList.add('hidden');\r\n\r\n    showToast(`Switched active server to: ${data.activeInstance.name}`, 'success');\r\n\r\n    // Reload all components for the new server\r\n    await loadInstances();\r\n    loadStorageOverview();\r\n    loadBackups();\r\n    loadModsList();\r\n    loadPlayersData();\r\n    loadFiles('');\r\n    loadSettings();\r\n  } catch (e) {\r\n    showToast(`Switch failed: ${e.message}`, 'error');\r\n  }\r\n}\r\n\r\nfunction openAddInstanceModal() {\r\n  const menu = document.getElementById('instanceMenu');\r\n  if (menu) menu.classList.add('hidden');\r\n  document.getElementById('addInstanceModal').classList.remove('hidden');\r\n}\r\n\r\nfunction closeAddInstanceModal() {\r\n  document.getElementById('addInstanceModal').classList.add('hidden');\r\n  document.getElementById('detectResultText').textContent = 'Enter folder path to auto-detect engine type.';\r\n}\r\n\r\nasync function detectInstPath() {\r\n  const inputPath = document.getElementById('addInstPath').value.trim();\r\n  if (!inputPath) {\r\n    showToast('Please enter a directory path first', 'warning');\r\n    return;\r\n  }\r\n  try {\r\n    const res = await fetch('/api/instances/detect', {\r\n      method: 'POST',\r\n      headers: { 'Content-Type': 'application/json' },\r\n      body: JSON.stringify({ path: inputPath })\r\n    });\r\n    const data = await res.json();\r\n    if (data.error) throw new Error(data.error);\r\n\r\n    document.getElementById('addInstName').value = data.suggestedName;\r\n    document.getElementById('addInstType').value = data.type;\r\n    document.getElementById('detectResultText').innerHTML = `<span class=\"text-white font-semibold\">Detected: ${data.engineName} (Port ${data.port})</span>`;\r\n    showToast(`Detected: ${data.engineName}`, 'success');\r\n  } catch (e) {\r\n    document.getElementById('detectResultText').textContent = `Detection failed: ${e.message}`;\r\n    showToast(e.message, 'error');\r\n  }\r\n}\r\n\r\nasync function submitAddInstance(e) {\r\n  e.preventDefault();\r\n  const folderPath = document.getElementById('addInstPath').value.trim();\r\n  const name = document.getElementById('addInstName').value.trim();\r\n  const type = document.getElementById('addInstType').value;\r\n  const maxRam = document.getElementById('addInstMaxRam').value.trim() || '4G';\r\n\r\n  try {\r\n    playSound('cmd');\r\n    const res = await fetch('/api/instances/add', {\r\n      method: 'POST',\r\n      headers: { 'Content-Type': 'application/json' },\r\n      body: JSON.stringify({ path: folderPath, name, type, maxRam })\r\n    });\r\n    const data = await res.json();\r\n    if (data.error) throw new Error(data.error);\r\n\r\n    showToast(`Added server: ${data.instance.name}`, 'success');\r\n    closeAddInstanceModal();\r\n    await loadInstances();\r\n\r\n    if (confirm(`Server \"${data.instance.name}\" registered! Switch to it now?`)) {\r\n      switchInstance(data.instance.id);\r\n    }\r\n  } catch (err) {\r\n    showToast(`Failed to add server: ${err.message}`, 'error');\r\n  }\r\n}\r\n\r\nasync function deleteInstance(id, name) {\r\n  if (!confirm(`Remove server profile \"${name}\" from dashboard? (No files on disk will be deleted).`)) return;\r\n  try {\r\n    playSound('cmd');\r\n    const res = await fetch('/api/instances/delete', {\r\n      method: 'POST',\r\n      headers: { 'Content-Type': 'application/json' },\r\n      body: JSON.stringify({ id })\r\n    });\r\n    const data = await res.json();\r\n    if (data.error) throw new Error(data.error);\r\n\r\n    showToast(`Removed server profile: ${name}`, 'info');\r\n    loadInstances();\r\n  } catch (e) {\r\n    showToast(`Failed to remove: ${e.message}`, 'error');\r\n  }\r\n}\r\n\r\n// ================= AUTO-HOST WORLD (EGG DEPLOYER) =================\r\nlet currentInspectedData = null;\r\nlet currentSelectedEgg = 'paper';\r\nlet currentAutoEggMode = 'existing'; // 'existing' | 'fresh'\r\n\r\nconst defaultFreshEggs = [\r\n  {\r\n    id: 'forge',\r\n    name: 'Forge',\r\n    tag: 'Classic Modded',\r\n    desc: 'Minecraft Forge engine for 1.12 - 1.20 modpacks.'\r\n  },\r\n  {\r\n    id: 'neoforge',\r\n    name: 'NeoForge',\r\n    tag: 'Modern Modded',\r\n    desc: 'Official NeoForge engine for 1.20.4+ and 26.x modpacks.'\r\n  },\r\n  {\r\n    id: 'fabric',\r\n    name: 'Fabric',\r\n    tag: 'Fast Modded',\r\n    desc: 'Lightweight modern modded server with auto-installed Fabric-API.'\r\n  },\r\n  {\r\n    id: 'paper',\r\n    name: 'Paper',\r\n    tag: 'Fast & Plugins',\r\n    desc: 'High-performance Java server with Bukkit/Spigot plugins.'\r\n  },\r\n  {\r\n    id: 'vanilla',\r\n    name: 'Vanilla',\r\n    tag: 'Official Mojang',\r\n    desc: 'Clean official Minecraft server without mods.'\r\n  }\r\n];\r\n\r\nfunction switchAutoEggMode(mode) {\r\n  currentAutoEggMode = mode;\r\n  const tabExisting = document.getElementById('tabAutoEggExisting');\r\n  const tabFresh = document.getElementById('tabAutoEggFresh');\r\n  const existingContainer = document.getElementById('autoEggExistingContainer');\r\n  const freshContainer = document.getElementById('autoEggFreshContainer');\r\n  const engineSection = document.getElementById('autoEggEngineSection');\r\n  const configSection = document.getElementById('autoEggConfigSection');\r\n  const btn = document.getElementById('btnAutoEggDeploy');\r\n\r\n  if (mode === 'existing') {\r\n    tabExisting.className = 'px-3.5 py-2 text-xs font-semibold rounded-t-lg bg-white text-black transition flex items-center gap-1.5';\r\n    tabFresh.className = 'px-3.5 py-2 text-xs font-semibold rounded-t-lg bg-transparent text-neutral-400 hover:text-white transition flex items-center gap-1.5';\r\n    existingContainer.classList.remove('hidden');\r\n    freshContainer.classList.add('hidden');\r\n\r\n    if (!currentInspectedData) {\r\n      engineSection.classList.add('hidden');\r\n      configSection.classList.add('hidden');\r\n      btn.disabled = true;\r\n      btn.classList.add('opacity-40', 'cursor-not-allowed');\r\n    } else {\r\n      engineSection.classList.remove('hidden');\r\n      configSection.classList.remove('hidden');\r\n      btn.disabled = false;\r\n      btn.classList.remove('opacity-40', 'cursor-not-allowed');\r\n    }\r\n    btn.innerHTML = `<i data-lucide=\"zap\" class=\"w-3.5 h-3.5 fill-current\"></i> Deploy & Host World`;\r\n  } else {\r\n    tabFresh.className = 'px-3.5 py-2 text-xs font-semibold rounded-t-lg bg-white text-black transition flex items-center gap-1.5';\r\n    tabExisting.className = 'px-3.5 py-2 text-xs font-semibold rounded-t-lg bg-transparent text-neutral-400 hover:text-white transition flex items-center gap-1.5';\r\n    existingContainer.classList.add('hidden');\r\n    freshContainer.classList.remove('hidden');\r\n    engineSection.classList.remove('hidden');\r\n    configSection.classList.remove('hidden');\r\n\r\n    // Render default eggs\r\n    renderEggCards(defaultFreshEggs);\r\n\r\n    // Setup fresh server defaults\r\n    const selVer = getFreshSelectedVersion();\r\n    const nameInput = document.getElementById('autoEggServerName');\r\n    if (nameInput && (!nameInput.value || nameInput.value.includes('Server'))) {\r\n      nameInput.value = `Server-${selVer}`;\r\n    }\r\n\r\n    btn.disabled = false;\r\n    btn.classList.remove('opacity-40', 'cursor-not-allowed');\r\n    btn.innerHTML = `<i data-lucide=\"sparkles\" class=\"w-3.5 h-3.5 fill-current\"></i> Create & Generate Server`;\r\n  }\r\n  lucide.createIcons();\r\n}\r\n\r\nfunction onFreshVersionSelect(e) {\r\n  const val = e.target.value;\r\n  const customBox = document.getElementById('autoEggCustomVersionBox');\r\n  if (val === 'custom') {\r\n    customBox.classList.remove('hidden');\r\n  } else {\r\n    customBox.classList.add('hidden');\r\n  }\r\n  const selVer = getFreshSelectedVersion();\r\n  const nameInput = document.getElementById('autoEggServerName');\r\n  if (nameInput) {\r\n    nameInput.value = `Server-${selVer}`;\r\n  }\r\n}\r\n\r\nfunction getFreshSelectedVersion() {\r\n  const sel = document.getElementById('autoEggFreshVersionSelect')?.value || '26.2';\r\n  if (sel === 'custom') {\r\n    return document.getElementById('autoEggCustomVersionInput')?.value.trim() || '26.2';\r\n  }\r\n  return sel;\r\n}\r\n\r\nfunction updateGeyserVisibility() {\r\n  const geyserBox = document.getElementById('autoEggGeyserToggleContainer');\r\n  if (geyserBox) {\r\n    if (currentSelectedEgg === 'paper') {\r\n      geyserBox.classList.remove('hidden');\r\n      geyserBox.classList.add('flex');\r\n    } else {\r\n      geyserBox.classList.add('hidden');\r\n      geyserBox.classList.remove('flex');\r\n    }\r\n  }\r\n}\r\n\r\nfunction renderEggCards(eggs) {\r\n  const container = document.getElementById('autoEggOptionsContainer');\r\n  if (!container) return;\r\n  container.innerHTML = eggs.map(egg => `\r\n    <div onclick=\"selectEgg('${egg.id}')\" id=\"eggCard-${egg.id}\" class=\"egg-card p-3 rounded-xl cursor-pointer border transition ${egg.id === currentSelectedEgg ? 'bg-white text-black border-white' : 'bg-black text-neutral-300 border-[#262626] hover:border-neutral-500'}\">\r\n      <div class=\"flex items-center justify-between\">\r\n        <strong class=\"text-xs ${egg.id === currentSelectedEgg ? 'text-black' : 'text-white'}\">${egg.name}</strong>\r\n        <span class=\"text-[9px] font-mono px-1.5 py-0.2 rounded ${egg.id === currentSelectedEgg ? 'bg-black text-white' : 'bg-[#181818] border border-[#333] text-neutral-400'}\">${egg.tag}</span>\r\n      </div>\r\n      <p class=\"text-[11px] mt-1 ${egg.id === currentSelectedEgg ? 'text-neutral-700' : 'text-neutral-400'} leading-snug\">${egg.desc}</p>\r\n    </div>\r\n  `).join('');\r\n  updateGeyserVisibility();\r\n}\r\n\r\nasync function openAutoEggModal() {\r\n  const menu = document.getElementById('instanceMenu');\r\n  if (menu) menu.classList.add('hidden');\r\n  document.getElementById('autoEggModal').classList.remove('hidden');\r\n  switchAutoEggMode(currentAutoEggMode || 'existing');\r\n  await refreshScannedWorlds();\r\n}\r\n\r\nfunction closeAutoEggModal() {\r\n  document.getElementById('autoEggModal').classList.add('hidden');\r\n  document.getElementById('autoEggSpecsCard').classList.add('hidden');\r\n  document.getElementById('autoEggEngineSection').classList.add('hidden');\r\n  document.getElementById('autoEggConfigSection').classList.add('hidden');\r\n  document.getElementById('autoEggProgressBox').classList.add('hidden');\r\n  const btn = document.getElementById('btnAutoEggDeploy');\r\n  btn.disabled = true;\r\n  btn.classList.add('opacity-40', 'cursor-not-allowed');\r\n}\r\n\r\nasync function refreshScannedWorlds() {\r\n  try {\r\n    const select = document.getElementById('autoEggScannedSelect');\r\n    select.innerHTML = '<option value=\"\">Scanning local singleplayer saves...</option>';\r\n    const res = await fetch('/api/provision/scan-worlds');\r\n    const data = await res.json();\r\n    const worlds = data.worlds || [];\r\n\r\n    if (worlds.length === 0) {\r\n      select.innerHTML = '<option value=\"\">No singleplayer worlds found automatically (paste path below)</option>';\r\n      return;\r\n    }\r\n\r\n    select.innerHTML = '<option value=\"\">-- Choose from your Singleplayer / Modpack Worlds --</option>' +\r\n      worlds.map(w => `<option value=\"${w.path}\">[${w.source}] ${w.name}</option>`).join('');\r\n  } catch (e) {\r\n    console.error('Error scanning worlds:', e);\r\n  }\r\n}\r\n\r\nfunction onSelectScannedWorld(e) {\r\n  const selectedPath = e.target.value;\r\n  if (selectedPath) {\r\n    document.getElementById('autoEggWorldPath').value = selectedPath;\r\n    inspectSelectedWorld();\r\n  }\r\n}\r\n\r\nfunction onManualWorldPathInput() {\r\n  const pathVal = document.getElementById('autoEggWorldPath').value.trim();\r\n  if (pathVal.length > 5 && (pathVal.includes('saves') || pathVal.includes('world') || pathVal.includes('\\\\'))) {\r\n    inspectSelectedWorld();\r\n  }\r\n}\r\n\r\nasync function inspectSelectedWorld() {\r\n  const worldPath = document.getElementById('autoEggWorldPath').value.trim();\r\n  if (!worldPath) {\r\n    showToast('Enter or select a world directory path first', 'warning');\r\n    return;\r\n  }\r\n\r\n  try {\r\n    showToast('Inspecting world version and structure...', 'info');\r\n    const res = await fetch('/api/provision/inspect', {\r\n      method: 'POST',\r\n      headers: { 'Content-Type': 'application/json' },\r\n      body: JSON.stringify({ worldPath })\r\n    });\r\n    const data = await res.json();\r\n    if (data.error) throw new Error(data.error);\r\n\r\n    currentInspectedData = data;\r\n    currentSelectedEgg = data.recommendedEgg || 'paper';\r\n\r\n    // Show Specs Card\r\n    document.getElementById('autoEggDetectedName').textContent = data.levelName || 'Minecraft World';\r\n    document.getElementById('autoEggDetectedVersion').textContent = data.mcVersion;\r\n    document.getElementById('autoEggDetectedType').textContent = data.isModded \r\n      ? `Modded (${data.detectedModloader.toUpperCase()}) - ${data.modCount} mods found` \r\n      : 'Vanilla / Clean Map';\r\n    document.getElementById('autoEggSpecsCard').classList.remove('hidden');\r\n\r\n    // Render Egg Template Cards\r\n    renderEggCards(data.availableEggs);\r\n    document.getElementById('autoEggEngineSection').classList.remove('hidden');\r\n\r\n    // Default configuration inputs\r\n    document.getElementById('autoEggServerName').value = `${data.levelName}-Server`;\r\n    document.getElementById('autoEggMaxRam').value = data.isModded ? '6G' : '4G';\r\n    document.getElementById('autoEggConfigSection').classList.remove('hidden');\r\n\r\n    // Enable Deploy Button\r\n    const btn = document.getElementById('btnAutoEggDeploy');\r\n    btn.disabled = false;\r\n    btn.classList.remove('opacity-40', 'cursor-not-allowed');\r\n\r\n    playSound('cmd');\r\n    showToast(`Detected Minecraft ${data.mcVersion}! Recommended Egg: ${currentSelectedEgg.toUpperCase()}`, 'success');\r\n  } catch (e) {\r\n    showToast(`Inspection error: ${e.message}`, 'error');\r\n  }\r\n}\r\n\r\nfunction selectEgg(eggId) {\r\n  currentSelectedEgg = eggId;\r\n  updateGeyserVisibility();\r\n  const cards = document.querySelectorAll('.egg-card');\r\n  cards.forEach(card => {\r\n    const isSelected = card.id === `eggCard-${eggId}`;\r\n    if (isSelected) {\r\n      card.className = 'egg-card p-3 rounded-xl cursor-pointer border transition bg-white text-black border-white';\r\n      card.querySelector('strong').className = 'text-xs text-black';\r\n      card.querySelector('p').className = 'text-[11px] mt-1 text-neutral-700 leading-snug';\r\n    } else {\r\n      card.className = 'egg-card p-3 rounded-xl cursor-pointer border transition bg-black text-neutral-300 border-[#262626] hover:border-neutral-500';\r\n      card.querySelector('strong').className = 'text-xs text-white';\r\n      card.querySelector('p').className = 'text-[11px] mt-1 text-neutral-400 leading-snug';\r\n    }\r\n  });\r\n}\r\n\r\nfunction updateProvisionProgress(data) {\r\n  const box = document.getElementById('autoEggProgressBox');\r\n  const text = document.getElementById('autoEggProgressText');\r\n  const percentText = document.getElementById('autoEggProgressPercent');\r\n  const bar = document.getElementById('autoEggProgressBar');\r\n\r\n  if (box && text) {\r\n    box.classList.remove('hidden');\r\n    text.textContent = data.text || 'Preparing dependencies...';\r\n    if (data.percent >= 0) {\r\n      if (percentText) percentText.textContent = `${data.percent}%`;\r\n      if (bar) bar.style.width = `${data.percent}%`;\r\n    }\r\n  }\r\n}\r\n\r\nasync function deployAutoEggServer() {\r\n  const isFresh = currentAutoEggMode === 'fresh';\r\n  let mcVersion = '';\r\n  let worldPath = '';\r\n  let serverName = '';\r\n  let seed = '';\r\n\r\n  if (isFresh) {\r\n    mcVersion = getFreshSelectedVersion();\r\n    worldPath = '';\r\n    seed = document.getElementById('autoEggFreshSeed')?.value.trim() || '';\r\n    serverName = document.getElementById('autoEggServerName')?.value.trim() || `Server-${mcVersion}`;\r\n  } else {\r\n    if (!currentInspectedData) return;\r\n    mcVersion = currentInspectedData.mcVersion;\r\n    worldPath = document.getElementById('autoEggWorldPath').value.trim();\r\n    serverName = document.getElementById('autoEggServerName')?.value.trim() || `${currentInspectedData.levelName}-Server`;\r\n  }\r\n\r\n  const port = parseInt(document.getElementById('autoEggPort').value, 10) || 25565;\r\n  const maxRam = document.getElementById('autoEggMaxRam').value.trim() || '4G';\r\n\r\n  const btn = document.getElementById('btnAutoEggDeploy');\r\n  btn.disabled = true;\r\n  btn.classList.add('opacity-40', 'cursor-not-allowed');\r\n\r\n  const progressBox = document.getElementById('autoEggProgressBox');\r\n  const progressText = document.getElementById('autoEggProgressText');\r\n  const progressPercent = document.getElementById('autoEggProgressPercent');\r\n  const progressBar = document.getElementById('autoEggProgressBar');\r\n\r\n  if (progressBox) progressBox.classList.remove('hidden');\r\n  if (progressText) progressText.textContent = `Connecting to ${currentSelectedEgg.toUpperCase()} (${mcVersion}) repository...`;\r\n  if (progressPercent) progressPercent.textContent = '0%';\r\n  if (progressBar) progressBar.style.width = '5%';\r\n\r\n  try {\r\n    playSound('cmd');\r\n    const enableGeyser = currentSelectedEgg === 'paper' && document.getElementById('autoEggEnableGeyser')?.checked !== false;\r\n    const res = await fetch('/api/provision/deploy', {\r\n      method: 'POST',\r\n      headers: { 'Content-Type': 'application/json' },\r\n      body: JSON.stringify({\r\n        worldPath,\r\n        serverName,\r\n        egg: currentSelectedEgg,\r\n        mcVersion,\r\n        port,\r\n        maxRam,\r\n        enableGeyser,\r\n        seed\r\n      })\r\n    });\r\n\r\n    const data = await res.json();\r\n    if (data.error) throw new Error(data.error);\r\n\r\n    playSound('alert');\r\n    showToast(`Server \"${data.instance.name}\" (${mcVersion}) created! Click START to play.`, 'success');\r\n    closeAutoEggModal();\r\n\r\n    // Reload components with new server active\r\n    await loadInstances();\r\n    loadStorageOverview();\r\n    loadBackups();\r\n    loadModsList();\r\n    loadPlayersData();\r\n    loadFiles('');\r\n    loadSettings();\r\n  } catch (err) {\r\n    progressText.textContent = `Deployment failed: ${err.message}`;\r\n    btn.disabled = false;\r\n    btn.classList.remove('opacity-40', 'cursor-not-allowed');\r\n    showToast(`Deploy error: ${err.message}`, 'error');\r\n  }\r\n}\r\n\r\n// ================= PLAYIT.GG GLOBAL HOSTING =================\r\nlet playitState = {\r\n  status: 'offline',\r\n  claimUrl: null,\r\n  tunnelsCount: 0,\r\n  publicAddress: '',\r\n  running: false\r\n};\r\n\r\nasync function loadPlayitStatus() {\r\n  try {\r\n    const res = await fetch('/api/playit/status');\r\n    const data = await res.json();\r\n    updatePlayitUI(data);\r\n    checkGeyserStatus();\r\n\r\n    if (data.logs && data.logs.length > 0) {\r\n      const screen = document.getElementById('playitLogsScreen');\r\n      if (screen) {\r\n        screen.innerHTML = '';\r\n        data.logs.forEach(l => renderPlayitLog(l.text || l));\r\n      }\r\n    }\r\n  } catch (e) {\r\n    console.error('Error loading playit status:', e);\r\n  }\r\n}\r\n\r\nasync function checkGeyserStatus() {\r\n  const geyserStatusEl = document.getElementById('playitGeyserStatus');\r\n  const installRow = document.getElementById('playitGeyserInstallRow');\r\n  if (!geyserStatusEl) return;\r\n\r\n  try {\r\n    const res = await fetch('/api/plugins/geyser-status');\r\n    const data = await res.json();\r\n\r\n    if (data.installed) {\r\n      geyserStatusEl.textContent = '✓ Installed (Cross-play Ready)';\r\n      geyserStatusEl.className = 'text-white font-bold text-[11px]';\r\n      if (installRow) installRow.classList.add('hidden');\r\n    } else if (data.isCompatible) {\r\n      geyserStatusEl.textContent = 'Not Installed';\r\n      geyserStatusEl.className = 'text-neutral-400 font-mono text-[10px]';\r\n      if (installRow) installRow.classList.remove('hidden');\r\n    } else {\r\n      geyserStatusEl.textContent = 'Engine Native / N/A';\r\n      geyserStatusEl.className = 'text-neutral-500 font-mono text-[10px]';\r\n      if (installRow) installRow.classList.add('hidden');\r\n    }\r\n  } catch (e) {}\r\n}\r\n\r\nasync function installGeyserToActiveServer() {\r\n  try {\r\n    playSound('cmd');\r\n    showToast('Installing Geyser & Floodgate cross-play plugins...', 'info');\r\n    const res = await fetch('/api/plugins/install-geyser', { method: 'POST' });\r\n    const data = await res.json();\r\n    if (data.error) throw new Error(data.error);\r\n\r\n    playSound('alert');\r\n    showToast('Geyser & Floodgate installed! Restart server to activate Bedrock cross-play.', 'success');\r\n    checkGeyserStatus();\r\n    loadModsList();\r\n  } catch (err) {\r\n    showToast(`Failed to install Geyser: ${err.message}`, 'error');\r\n  }\r\n}\r\n\r\nfunction updatePlayitUI(data) {\r\n  playitState = { ...playitState, ...data };\r\n\r\n  // Header Pill & Sidebar Dot\r\n  const dot = document.getElementById('playitStatusDot');\r\n  const sideDot = document.getElementById('sidebarPlayitDot');\r\n  const headerStatus = document.getElementById('playitHeaderStatus');\r\n  if (dot && headerStatus) {\r\n    if (playitState.status === 'running') {\r\n      dot.className = 'w-2 h-2 rounded-full bg-emerald-400 pulse-active';\r\n      if (sideDot) sideDot.className = 'w-2 h-2 rounded-full bg-emerald-400 pulse-active';\r\n      headerStatus.textContent = playitState.publicAddress ? `Global: ${playitState.publicAddress}` : 'Tunnel: Online';\r\n    } else if (playitState.status === 'claiming') {\r\n      dot.className = 'w-2 h-2 rounded-full bg-amber-400 animate-ping';\r\n      if (sideDot) sideDot.className = 'w-2 h-2 rounded-full bg-amber-400 animate-ping';\r\n      headerStatus.textContent = 'Link Account';\r\n    } else if (playitState.status === 'starting') {\r\n      dot.className = 'w-2 h-2 rounded-full bg-amber-400 animate-ping';\r\n      if (sideDot) sideDot.className = 'w-2 h-2 rounded-full bg-amber-400 animate-ping';\r\n      headerStatus.textContent = 'Tunnel: Starting';\r\n    } else {\r\n      dot.className = 'w-2 h-2 rounded-full bg-neutral-600';\r\n      if (sideDot) sideDot.className = 'w-2 h-2 rounded-full bg-neutral-600';\r\n      headerStatus.textContent = 'Tunnel: Off';\r\n    }\r\n  }\r\n\r\n  // Playit Tab Elements\r\n  const pill = document.getElementById('playitStatusPill');\r\n  const toggleBtn = document.getElementById('btnPlayitToggle');\r\n  const claimBanner = document.getElementById('playitClaimBanner');\r\n  const claimLink = document.getElementById('btnPlayitClaimLink');\r\n  const tunnelsCount = document.getElementById('playitTunnelsCount');\r\n  const javaAddrInput = document.getElementById('playitJavaAddressInput');\r\n  const bedrockAddrInput = document.getElementById('playitBedrockAddressInput');\r\n  const bedrockPortInput = document.getElementById('playitBedrockPortInput');\r\n  const javaLocalPort = document.getElementById('playitJavaLocalPort');\r\n  const bedrockLocalPort = document.getElementById('playitBedrockLocalPort');\r\n\r\n  if (pill) pill.textContent = playitState.status.toUpperCase();\r\n  if (tunnelsCount) tunnelsCount.textContent = playitState.tunnelsCount || '0';\r\n\r\n  // Update active profile name indicator in Tunnel Tab\r\n  const profileNameEl = document.getElementById('playitActiveProfileName');\r\n  if (profileNameEl && activeInstanceData) {\r\n    profileNameEl.textContent = activeInstanceData.name;\r\n  }\r\n\r\n  const javaAddr = playitState.javaAddress || playitState.publicAddress || '';\r\n  if (javaAddrInput && document.activeElement !== javaAddrInput) {\r\n    javaAddrInput.value = javaAddr;\r\n  }\r\n  if (bedrockAddrInput && document.activeElement !== bedrockAddrInput) {\r\n    bedrockAddrInput.value = playitState.bedrockAddress || '';\r\n  }\r\n  if (bedrockPortInput && document.activeElement !== bedrockPortInput) {\r\n    bedrockPortInput.value = playitState.bedrockPort || '19132';\r\n  }\r\n\r\n  // Update local target port based on active server\r\n  const p = activeInstanceData?.port || 25565;\r\n  if (javaLocalPort) javaLocalPort.textContent = `Local Target: 127.0.0.1:${p}`;\r\n  if (bedrockLocalPort) bedrockLocalPort.textContent = `Local Target: 127.0.0.1:19132`;\r\n\r\n  // Toggle button\r\n  if (toggleBtn) {\r\n    if (playitState.running) {\r\n      toggleBtn.className = 'px-4 py-1.5 rounded-lg bg-[#141414] hover:bg-[#202020] text-neutral-200 border border-[#333] font-medium text-xs flex items-center gap-1.5 transition';\r\n      toggleBtn.innerHTML = `<i data-lucide=\"square\" class=\"w-3.5 h-3.5 fill-current\"></i> Stop Tunnel`;\r\n    } else {\r\n      toggleBtn.className = 'px-4 py-1.5 rounded-lg bg-white hover:bg-neutral-200 text-black font-semibold text-xs flex items-center gap-1.5 transition';\r\n      toggleBtn.innerHTML = `<i data-lucide=\"play\" class=\"w-3.5 h-3.5 fill-current\"></i> Start Tunnel`;\r\n    }\r\n  }\r\n\r\n  // Claim banner\r\n  if (claimBanner && claimLink) {\r\n    if (playitState.status === 'claiming' && playitState.claimUrl) {\r\n      claimBanner.classList.remove('hidden');\r\n      claimLink.href = playitState.claimUrl;\r\n    } else {\r\n      claimBanner.classList.add('hidden');\r\n    }\r\n  }\r\n\r\n  updateShareInviteUI();\r\n  lucide.createIcons();\r\n}\r\n\r\nfunction renderPlayitLog(line) {\r\n  const screen = document.getElementById('playitLogsScreen');\r\n  if (!screen) return;\r\n  const div = document.createElement('div');\r\n  div.className = 'text-neutral-300 truncate';\r\n  div.textContent = line;\r\n  screen.appendChild(div);\r\n  if (screen.children.length > 200) screen.removeChild(screen.firstChild);\r\n  screen.scrollTop = screen.scrollHeight;\r\n}\r\n\r\nasync function togglePlayitTunnel() {\r\n  try {\r\n    playSound('cmd');\r\n    if (playitState.running) {\r\n      showToast('Stopping playit tunnel...', 'info');\r\n      await fetch('/api/playit/stop', { method: 'POST' });\r\n    } else {\r\n      showToast('Starting playit tunnel agent...', 'info');\r\n      await fetch('/api/playit/start', { method: 'POST' });\r\n    }\r\n    loadPlayitStatus();\r\n  } catch (e) {\r\n    showToast(`Error: ${e.message}`, 'error');\r\n  }\r\n}\r\n\r\nasync function resetPlayitAgent() {\r\n  if (!confirm('Re-link playit.gg account? This will reset the agent key and create a new claim URL.')) return;\r\n  try {\r\n    playSound('cmd');\r\n    showToast('Resetting agent & generating new claim link...', 'info');\r\n    const res = await fetch('/api/playit/reset', { method: 'POST' });\r\n    const data = await res.json();\r\n    loadPlayitStatus();\r\n    if (data.claimUrl) {\r\n      window.open(data.claimUrl, '_blank');\r\n    }\r\n  } catch (e) {\r\n    showToast(`Reset error: ${e.message}`, 'error');\r\n  }\r\n}\r\n\r\nasync function savePlayitAddresses() {\r\n  const javaAddress = document.getElementById('playitJavaAddressInput')?.value.trim() || '';\r\n  const bedrockAddress = document.getElementById('playitBedrockAddressInput')?.value.trim() || '';\r\n  const bedrockPort = document.getElementById('playitBedrockPortInput')?.value.trim() || '19132';\r\n  const instanceId = activeInstanceData?.id;\r\n\r\n  try {\r\n    playSound('cmd');\r\n    const res = await fetch('/api/playit/address', {\r\n      method: 'POST',\r\n      headers: { 'Content-Type': 'application/json' },\r\n      body: JSON.stringify({ javaAddress, bedrockAddress, bedrockPort, instanceId })\r\n    });\r\n    const data = await res.json();\r\n    if (activeInstanceData) {\r\n      activeInstanceData.tunnel = { javaAddress, bedrockAddress, bedrockPort };\r\n    }\r\n    showToast(`Tunnel saved for \"${data.instanceName || activeInstanceData?.name}\"!`, 'success');\r\n    loadPlayitStatus();\r\n    loadInstances();\r\n  } catch (e) {\r\n    showToast(`Error: ${e.message}`, 'error');\r\n  }\r\n}\r\n\r\nfunction copySpecificAddress(type) {\r\n  const port = activeInstanceData?.port || 25565;\r\n  const isTunnelActive = Boolean(playitState && playitState.running);\r\n  let textToCopy = '';\r\n\r\n  if (type === 'global' || type === 'java') {\r\n    textToCopy = (isTunnelActive && playitState.javaAddress) ? playitState.javaAddress : `localhost:${port}`;\r\n  } else if (type === 'lan') {\r\n    textToCopy = `${cachedLocalIp}:${port}`;\r\n  } else if (type === 'bedrock') {\r\n    const bPort = playitState.bedrockPort || '19132';\r\n    textToCopy = (isTunnelActive && playitState.bedrockAddress)\r\n      ? `${playitState.bedrockAddress}:${bPort}`\r\n      : `${cachedLocalIp}:19132`;\r\n  }\r\n\r\n  navigator.clipboard.writeText(textToCopy).then(() => {\r\n    playSound('cmd');\r\n    showToast(`Copied ${type.toUpperCase()} Address: ${textToCopy}`, 'success');\r\n  });\r\n}\r\n\r\nfunction refreshPlayitStatus() {\r\n  loadPlayitStatus();\r\n  showToast('Refreshed playit status', 'info');\r\n}\r\n\r\n// ================= SYSTEM SHUTDOWN =================\r\nasync function shutdownDashboard() {\r\n  if (!confirm('Are you sure you want to shut down the CraftOrbit Web Dashboard? This will gracefully save and stop any running Minecraft server, stop the tunnel, and close the command prompt.')) {\r\n    return;\r\n  }\r\n\r\n  try {\r\n    playSound('stop');\r\n    showToast('Shutting down CraftOrbit & stopping server...', 'warning');\r\n    await fetch('/api/system/shutdown', { method: 'POST' });\r\n\r\n    // Display clean offline screen\r\n    document.body.innerHTML = `\r\n      <div class=\"min-h-screen bg-black text-white flex flex-col items-center justify-center p-6 text-center\">\r\n        <div class=\"w-16 h-16 rounded-2xl bg-[#111] border border-[#333] flex items-center justify-center mb-5\">\r\n          <i data-lucide=\"power\" class=\"w-8 h-8 text-neutral-400\"></i>\r\n        </div>\r\n        <h1 class=\"text-xl font-bold text-white tracking-tight\">CraftOrbit Offline</h1>\r\n        <p class=\"text-sm text-neutral-400 mt-2 max-w-md\">The web dashboard, servers, and background process have been safely terminated.</p>\r\n        <div class=\"mt-6 p-4 rounded-xl bg-[#0a0a0a] border border-[#222] text-xs font-mono text-neutral-500\">\r\n          Command prompt process closed. You may now close this browser tab.\r\n        </div>\r\n      </div>\r\n    `;\r\n    lucide.createIcons();\r\n  } catch (e) {\r\n    showToast(`Shutdown failed: ${e.message}`, 'error');\r\n  }\r\n}\r\n\r\n// ================= FRIEND SHARE & QUICK ACTIONS =================\r\nfunction updateShareInviteUI() {\r\n  const shareBanner = document.getElementById('shareInviteBanner');\r\n  const globalAddrEl = document.getElementById('shareGlobalAddressText');\r\n  const lanAddrEl = document.getElementById('shareLanAddressText');\r\n  const bedrockAddrEl = document.getElementById('shareBedrockAddressText');\r\n  const scopeBadge = document.getElementById('shareInviteScopeBadge');\r\n  const tunnelHint = document.getElementById('shareInviteTunnelHint');\r\n  const isDummy = !activeInstanceData || activeInstanceData.id === 'none';\r\n\r\n  if (!shareBanner) return;\r\n\r\n  if (serverStatus !== 'online' || isDummy) {\r\n    shareBanner.classList.add('hidden');\r\n    return;\r\n  }\r\n\r\n  shareBanner.classList.remove('hidden');\r\n  const port = activeInstanceData?.port || 25565;\r\n  const isTunnelActive = Boolean(playitState && playitState.running);\r\n  const javaAddr = playitState?.javaAddress || playitState?.publicAddress || '';\r\n  const bedrockAddr = playitState?.bedrockAddress || '';\r\n  const bedrockPort = playitState?.bedrockPort || '19132';\r\n\r\n  if (globalAddrEl) {\r\n    globalAddrEl.textContent = (isTunnelActive && javaAddr) ? javaAddr : 'Not Configured (playit off)';\r\n  }\r\n\r\n  if (lanAddrEl) {\r\n    lanAddrEl.textContent = `${cachedLocalIp}:${port}`;\r\n  }\r\n\r\n  if (bedrockAddrEl) {\r\n    if (isTunnelActive && bedrockAddr) {\r\n      bedrockAddrEl.textContent = `${bedrockAddr}:${bedrockPort}`;\r\n    } else {\r\n      bedrockAddrEl.textContent = `${cachedLocalIp}:19132`;\r\n    }\r\n  }\r\n\r\n  // Update Scope Badge & Hint\r\n  if (isTunnelActive && javaAddr) {\r\n    if (scopeBadge) {\r\n      scopeBadge.textContent = 'ONLINE WORLDWIDE (playit.gg)';\r\n      scopeBadge.className = 'text-[10px] font-mono px-2 py-0.5 rounded bg-black text-white uppercase font-bold tracking-wider';\r\n    }\r\n    if (tunnelHint) {\r\n      tunnelHint.innerHTML = '🌍 <span class=\"text-neutral-700\">Outside players connect via <strong>Internet (playit.gg)</strong>. Same Wi-Fi players connect via <strong>Home Wi-Fi (LAN)</strong>.</span>';\r\n    }\r\n  } else {\r\n    if (scopeBadge) {\r\n      scopeBadge.textContent = 'LOCAL / LAN ONLY';\r\n      scopeBadge.className = 'text-[10px] font-mono px-2 py-0.5 rounded bg-neutral-200 text-black border border-neutral-300 uppercase font-semibold';\r\n    }\r\n    if (tunnelHint) {\r\n      tunnelHint.innerHTML = '<span class=\"text-neutral-600\">LAN only. <a href=\"#\" onclick=\"switchTab(\\'playit\\'); return false;\" class=\"underline text-black font-semibold\">Turn on Global Tunnel</a> to play with friends worldwide!</span>';\r\n    }\r\n  }\r\n}\r\n\r\nfunction copyShareInvite() {\r\n  const isDummy = !activeInstanceData || activeInstanceData.id === 'none';\r\n  if (isDummy) return;\r\n\r\n  const port = activeInstanceData?.port || 25565;\r\n  const isTunnelActive = Boolean(playitState && playitState.running);\r\n  const javaAddr = playitState?.javaAddress || playitState?.publicAddress || '';\r\n  const bedrockAddr = playitState?.bedrockAddress || '';\r\n  const bedrockPort = playitState?.bedrockPort || '19132';\r\n  const serverName = activeInstanceData?.name || 'Minecraft Server';\r\n  const engine = activeInstanceData?.detectedEngine || 'Minecraft';\r\n\r\n  const globalSec = (isTunnelActive && javaAddr) ? `🌐 Internet (playit.gg):\\n👉 PC: ${javaAddr}\\n👉 Mobile Bedrock: ${bedrockAddr}:${bedrockPort}\\n\\n` : '';\r\n  const lanSec = `🏠 Same Wi-Fi (LAN):\\n👉 PC: ${cachedLocalIp}:${port}\\n👉 Mobile Bedrock: ${cachedLocalIp}:19132\\n\\n`;\r\n\r\n  const dict = (i18nDictionary && i18nDictionary[currentLang]) ? i18nDictionary[currentLang] : i18nDictionary['en'];\r\n  const inviteHeader = dict.invite_header || '🎮 Join our Minecraft Server!';\r\n  const inviteServerLabel = dict.invite_server || '🏷️ Server';\r\n  const inviteHowTo = dict.invite_how_to || '👉 How to Connect:\\n1. Open Minecraft -> Multiplayer / Servers\\n2. Direct Connection / Add Server\\n3. Enter the server address -> Connect & Play!';\r\n\r\n  const inviteText = `${inviteHeader}\\n${inviteServerLabel}: ${serverName} (${engine})\\n\\n${globalSec}${lanSec}${inviteHowTo}`;\r\n\r\n  navigator.clipboard.writeText(inviteText).then(() => {\r\n    playSound('cmd');\r\n    showToast(dict.toast_invite_copied || 'Copied multiplayer invite message!', 'success');\r\n  });\r\n}\r\n\r\nasync function broadcastServerAnnouncement(e) {\r\n  if (e) e.preventDefault();\r\n  const input = document.getElementById('serverBroadcastInput');\r\n  const msg = input?.value.trim();\r\n  if (!msg) return;\r\n\r\n  if (serverStatus !== 'online') {\r\n    showToast('Server must be online to send broadcast announcements!', 'warning');\r\n    return;\r\n  }\r\n\r\n  try {\r\n    playSound('cmd');\r\n    const res = await fetch('/api/players/action', {\r\n      method: 'POST',\r\n      headers: { 'Content-Type': 'application/json' },\r\n      body: JSON.stringify({ action: 'broadcast', reason: msg })\r\n    });\r\n    const data = await res.json();\r\n    if (data.error) throw new Error(data.error);\r\n    showToast(`Broadcast sent: \"${msg}\"`, 'success');\r\n    input.value = '';\r\n  } catch (err) {\r\n    showToast(`Broadcast failed: ${err.message}`, 'error');\r\n  }\r\n}\r\n\r\nasync function sendQuickAction(action) {\r\n  if (serverStatus !== 'online') {\r\n    showToast('Server must be online to execute world shortcuts!', 'warning');\r\n    return;\r\n  }\r\n  try {\r\n    playSound('cmd');\r\n    const res = await fetch('/api/server/quick-action', {\r\n      method: 'POST',\r\n      headers: { 'Content-Type': 'application/json' },\r\n      body: JSON.stringify({ action })\r\n    });\r\n    const data = await res.json();\r\n    if (data.error) throw new Error(data.error);\r\n    showToast(`Executed shortcut: /${data.command}`, 'success');\r\n  } catch (e) {\r\n    showToast(`Shortcut error: ${e.message}`, 'error');\r\n  }\r\n}\r\n\r\nasync function handleModFileSelect(e) {\r\n  const file = e.target.files?.[0];\r\n  if (!file) return;\r\n\r\n  if (!file.name.endsWith('.jar')) {\r\n    showToast('Only .jar files can be installed into the mods folder!', 'warning');\r\n    return;\r\n  }\r\n\r\n  try {\r\n    playSound('cmd');\r\n    showToast(`Uploading ${file.name}...`, 'info');\r\n    const arrayBuf = await file.arrayBuffer();\r\n\r\n    const res = await fetch(`/api/mods/upload?name=${encodeURIComponent(file.name)}`, {\r\n      method: 'POST',\r\n      headers: { 'Content-Type': 'application/octet-stream' },\r\n      body: arrayBuf\r\n    });\r\n\r\n    const data = await res.json();\r\n    if (data.error) throw new Error(data.error);\r\n\r\n    playSound('alert');\r\n    showToast(`Installed mod: ${data.fileName}!`, 'success');\r\n    loadModsList();\r\n  } catch (err) {\r\n    showToast(`Upload failed: ${err.message}`, 'error');\r\n  } finally {\r\n    e.target.value = '';\r\n  }\r\n}\r\n\r\n// ================= COMMAND PALETTE (Ctrl+K) =================\r\nconst paletteActions = [\r\n  { id: 'start', title: 'Start Minecraft Server', cat: 'Server Controls', icon: 'play', run: () => startServer() },\r\n  { id: 'stop', title: 'Stop Minecraft Server (Graceful Save)', cat: 'Server Controls', icon: 'square', run: () => stopServer() },\r\n  { id: 'restart', title: 'Restart Server', cat: 'Server Controls', icon: 'rotate-cw', run: () => restartServer() },\r\n  { id: 'kill', title: 'Force Kill Process', cat: 'Server Controls', icon: 'zap-off', run: () => killServer() },\r\n  { id: 'host-world', title: 'Host World (Auto-Egg Deployer)', cat: 'Instance', icon: 'sparkles', run: () => openAutoEggModal() },\r\n  { id: 'add-folder', title: 'Add Existing Server Folder', cat: 'Instance', icon: 'folder-plus', run: () => openAddInstanceModal() },\r\n  { id: 'tunnel', title: 'Toggle playit.gg Global Tunnel', cat: 'Network', icon: 'globe', run: () => togglePlayitTunnel() },\r\n  { id: 'day', title: 'Set World Time: Day', cat: 'World Shortcut', icon: 'sun', run: () => sendQuickAction('day') },\r\n  { id: 'night', title: 'Set World Time: Night', cat: 'World Shortcut', icon: 'moon', run: () => sendQuickAction('night') },\r\n  { id: 'clear-weather', title: 'Clear Weather', cat: 'World Shortcut', icon: 'cloud-sun', run: () => sendQuickAction('weather_clear') },\r\n  { id: 'clearlag', title: 'Clear Ground Clutter (Fix Lag)', cat: 'World Shortcut', icon: 'trash', run: () => sendQuickAction('clearlag') },\r\n  { id: 'save', title: 'Save World Chunks to Disk', cat: 'World Shortcut', icon: 'save', run: () => sendQuickAction('save') },\r\n  { id: 'backup', title: 'Create World Backup (.zip)', cat: 'Storage', icon: 'archive', run: () => triggerWorldBackup() },\r\n  { id: 'purge-logs', title: 'Clear Old Compressed Logs', cat: 'Storage', icon: 'trash-2', run: () => cleanOldLogs() },\r\n  { id: 'clean-cache', title: 'Clean Cache & Crash Reports', cat: 'Storage', icon: 'refresh-cw', run: () => cleanCache() },\r\n  { id: 'diagnose', title: 'Run AI Server Diagnosis', cat: 'AI Copilot', icon: 'stethoscope', run: () => runQuickDiagnosis() },\r\n  { id: 'import-pack', title: 'Import Modpack (.zip)', cat: 'Mods', icon: 'archive', run: () => openImportModpackModal() },\r\n  { id: 'mod-store', title: 'Browse Mod Store (Modrinth)', cat: 'Mods', icon: 'store', run: () => { switchTab('mods'); switchModSubtab('store'); } },\r\n  { id: 'toggle-layout', title: 'Toggle Layout (Sidebar / Topbar)', cat: 'Interface', icon: 'layout', run: () => toggleLayoutMode() },\r\n  { id: 'nav-dashboard', title: 'Go to Overview Dashboard', cat: 'Navigation', icon: 'layout-dashboard', run: () => switchTab('dashboard') },\r\n  { id: 'nav-console', title: 'Go to Live Console', cat: 'Navigation', icon: 'terminal', run: () => switchTab('console') },\r\n  { id: 'nav-files', title: 'Go to File Manager', cat: 'Navigation', icon: 'folder', run: () => switchTab('files') },\r\n  { id: 'nav-mods', title: 'Go to Mod Manager', cat: 'Navigation', icon: 'package', run: () => switchTab('mods') },\r\n  { id: 'nav-storage', title: 'Go to Backups & Storage', cat: 'Navigation', icon: 'database', run: () => switchTab('storage') },\r\n  { id: 'nav-settings', title: 'Go to Server Settings', cat: 'Navigation', icon: 'sliders', run: () => switchTab('settings') },\r\n  { id: 'shutdown', title: 'Shutdown Dashboard & Exit', cat: 'System', icon: 'power', run: () => shutdownDashboard() }\r\n];\r\n\r\nfunction openImportModpackModal() {\r\n  document.getElementById('importModpackModal')?.classList.remove('hidden');\r\n}\r\n\r\nfunction closeImportModpackModal() {\r\n  document.getElementById('importModpackModal')?.classList.add('hidden');\r\n  document.getElementById('importModpackProgress')?.classList.add('hidden');\r\n}\r\n\r\nasync function submitImportModpack(e) {\r\n  e.preventDefault();\r\n  const zipPath = document.getElementById('importModpackPath')?.value.trim();\r\n  if (!zipPath) return;\r\n\r\n  const progress = document.getElementById('importModpackProgress');\r\n  const btn = document.getElementById('btnSubmitImportModpack');\r\n  if (progress) progress.classList.remove('hidden');\r\n  if (btn) {\r\n    btn.disabled = true;\r\n    btn.classList.add('opacity-40');\r\n  }\r\n\r\n  try {\r\n    playSound('cmd');\r\n    showToast('Unpacking modpack archive into server...', 'info');\r\n    const res = await fetch('/api/modpack/import-zip', {\r\n      method: 'POST',\r\n      headers: { 'Content-Type': 'application/json' },\r\n      body: JSON.stringify({ zipPath })\r\n    });\r\n    const data = await res.json();\r\n    if (data.error) throw new Error(data.error);\r\n\r\n    playSound('alert');\r\n    showToast(`Modpack imported successfully! ${data.modCount} mods loaded.`, 'success');\r\n    closeImportModpackModal();\r\n    loadModsList();\r\n  } catch (err) {\r\n    showToast(`Import failed: ${err.message}`, 'error');\r\n  } finally {\r\n    if (progress) progress.classList.add('hidden');\r\n    if (btn) {\r\n      btn.disabled = false;\r\n      btn.classList.remove('opacity-40');\r\n    }\r\n  }\r\n}\r\n\r\nfunction openCommandPalette() {\r\n  const modal = document.getElementById('commandPaletteModal');\r\n  if (!modal) return;\r\n  modal.classList.remove('hidden');\r\n  const input = document.getElementById('paletteSearchInput');\r\n  if (input) {\r\n    input.value = '';\r\n    input.focus();\r\n  }\r\n  filterPaletteItems();\r\n}\r\n\r\nfunction closeCommandPalette() {\r\n  const modal = document.getElementById('commandPaletteModal');\r\n  if (modal) modal.classList.add('hidden');\r\n}\r\n\r\nfunction onCommandPaletteBackdrop(e) {\r\n  closeCommandPalette();\r\n}\r\n\r\nfunction filterPaletteItems() {\r\n  const q = document.getElementById('paletteSearchInput')?.value.toLowerCase() || '';\r\n  const container = document.getElementById('paletteItemsList');\r\n  if (!container) return;\r\n\r\n  const filtered = paletteActions.filter(a => a.title.toLowerCase().includes(q) || a.cat.toLowerCase().includes(q) || a.id.includes(q));\r\n\r\n  if (filtered.length === 0) {\r\n    container.innerHTML = '<div class=\"p-4 text-center text-neutral-500 font-mono text-xs\">No matching actions found</div>';\r\n    return;\r\n  }\r\n\r\n  container.innerHTML = filtered.map(a => `\r\n    <div onclick=\"runPaletteAction('${a.id}')\" class=\"p-2.5 rounded-lg cursor-pointer flex items-center justify-between hover:bg-[#181818] border border-transparent hover:border-[#333] transition group\">\r\n      <div class=\"flex items-center gap-2.5\">\r\n        <div class=\"w-6 h-6 rounded bg-black border border-[#222] text-white flex items-center justify-center shrink-0\">\r\n          <i data-lucide=\"${a.icon}\" class=\"w-3.5 h-3.5\"></i>\r\n        </div>\r\n        <span class=\"font-medium text-white group-hover:underline\">${a.title}</span>\r\n      </div>\r\n      <span class=\"text-[10px] font-mono text-neutral-500\">${a.cat}</span>\r\n    </div>\r\n  `).join('');\r\n\r\n  lucide.createIcons();\r\n}\r\n\r\nfunction runPaletteAction(id) {\r\n  closeCommandPalette();\r\n  const action = paletteActions.find(a => a.id === id);\r\n  if (action && typeof action.run === 'function') {\r\n    action.run();\r\n  }\r\n}\r\n\r\n// Global Keyboard Shortcuts\r\ndocument.addEventListener('keydown', (e) => {\r\n  const isInput = ['INPUT', 'TEXTAREA', 'SELECT'].includes(document.activeElement?.tagName);\r\n\r\n  if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'k') {\r\n    e.preventDefault();\r\n    openCommandPalette();\r\n  } else if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'b') {\r\n    e.preventDefault();\r\n    toggleLayoutMode();\r\n  } else if (e.altKey && !isNaN(e.key) && Number(e.key) >= 1 && Number(e.key) <= 9) {\r\n    e.preventDefault();\r\n    const tabList = ['dashboard', 'console', 'settings', 'ai', 'files', 'mods', 'storage', 'playit', 'players'];\r\n    const targetTab = tabList[Number(e.key) - 1];\r\n    if (targetTab) switchTab(targetTab);\r\n  } else if (e.key === '/' && !isInput && !e.ctrlKey && !e.metaKey && !e.altKey) {\r\n    e.preventDefault();\r\n    if (currentTab === 'dashboard') {\r\n      const input = document.getElementById('dashCommandInput');\r\n      if (input) { input.focus(); input.select(); }\r\n    } else {\r\n      switchTab('console');\r\n      setTimeout(() => {\r\n        const input = document.getElementById('fullConsoleInput');\r\n        if (input) { input.focus(); input.select(); }\r\n      }, 50);\r\n    }\r\n  } else if (e.key === 'Escape') {\r\n    closeCommandPalette();\r\n    closeAutoEggModal();\r\n    closeAddInstanceModal();\r\n    closeImportModpackModal();\r\n    closeFileEditor();\r\n  }\r\n});\r\n",
  "favicon.svg": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 64 64\" width=\"100%\" height=\"100%\" fill=\"none\">\r\n  <rect width=\"64\" height=\"64\" rx=\"14\" fill=\"#080b11\"/>\r\n  <!-- Back Orbit -->\r\n  <ellipse cx=\"32\" cy=\"32\" rx=\"26\" ry=\"11\" stroke=\"#38bdf8\" stroke-width=\"2\" opacity=\"0.3\" transform=\"rotate(-28 32 32)\"/>\r\n  \r\n  <!-- Isometric Cube -->\r\n  <!-- Top -->\r\n  <polygon points=\"32,15 44,22 32,29 20,22\" fill=\"#ffffff\"/>\r\n  <!-- Left -->\r\n  <polygon points=\"20,22 32,29 32,45 20,38\" fill=\"#94a3b8\"/>\r\n  <!-- Right -->\r\n  <polygon points=\"32,29 44,22 44,38 32,45\" fill=\"#475569\"/>\r\n  <!-- Center dividing line -->\r\n  <line x1=\"32\" y1=\"29\" x2=\"32\" y2=\"45\" stroke=\"#38bdf8\" stroke-width=\"1.5\"/>\r\n\r\n  <!-- Front Orbit -->\r\n  <path d=\"M 55 32 A 26 11 0 0 1 9 32\" stroke=\"#38bdf8\" stroke-width=\"2.5\" stroke-linecap=\"round\" transform=\"rotate(-28 32 32)\"/>\r\n  <!-- Satellite -->\r\n  <circle cx=\"48\" cy=\"38\" r=\"2.5\" fill=\"#ffffff\"/>\r\n</svg>\r\n",
  "icon.svg": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 512 512\" width=\"100%\" height=\"100%\" fill=\"none\">\r\n  <defs>\r\n    <!-- Card Squircle Background -->\r\n    <linearGradient id=\"iconBg\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\r\n      <stop offset=\"0%\" stop-color=\"#0e131d\"/>\r\n      <stop offset=\"50%\" stop-color=\"#080b11\"/>\r\n      <stop offset=\"100%\" stop-color=\"#030406\"/>\r\n    </linearGradient>\r\n\r\n    <linearGradient id=\"iconBorder\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\r\n      <stop offset=\"0%\" stop-color=\"#334155\" stop-opacity=\"0.8\"/>\r\n      <stop offset=\"50%\" stop-color=\"#1e293b\" stop-opacity=\"0.4\"/>\r\n      <stop offset=\"100%\" stop-color=\"#0f172a\" stop-opacity=\"0.8\"/>\r\n    </linearGradient>\r\n\r\n    <!-- Cube Gradients -->\r\n    <linearGradient id=\"topFace\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\r\n      <stop offset=\"0%\" stop-color=\"#ffffff\"/>\r\n      <stop offset=\"100%\" stop-color=\"#e2e8f0\"/>\r\n    </linearGradient>\r\n\r\n    <linearGradient id=\"leftFace\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\r\n      <stop offset=\"0%\" stop-color=\"#94a3b8\"/>\r\n      <stop offset=\"100%\" stop-color=\"#64748b\"/>\r\n    </linearGradient>\r\n\r\n    <linearGradient id=\"rightFace\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\r\n      <stop offset=\"0%\" stop-color=\"#475569\"/>\r\n      <stop offset=\"100%\" stop-color=\"#1e293b\"/>\r\n    </linearGradient>\r\n\r\n    <!-- Orbit Gradients -->\r\n    <linearGradient id=\"orbitGlowPrimary\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\r\n      <stop offset=\"0%\" stop-color=\"#38bdf8\" stop-opacity=\"0.2\"/>\r\n      <stop offset=\"35%\" stop-color=\"#ffffff\" stop-opacity=\"1\"/>\r\n      <stop offset=\"65%\" stop-color=\"#38bdf8\" stop-opacity=\"0.95\"/>\r\n      <stop offset=\"100%\" stop-color=\"#818cf8\" stop-opacity=\"0.1\"/>\r\n    </linearGradient>\r\n\r\n    <linearGradient id=\"orbitGlowSecondary\" x1=\"100%\" y1=\"0%\" x2=\"0%\" y2=\"100%\">\r\n      <stop offset=\"0%\" stop-color=\"#a855f7\" stop-opacity=\"0.1\"/>\r\n      <stop offset=\"50%\" stop-color=\"#38bdf8\" stop-opacity=\"0.85\"/>\r\n      <stop offset=\"100%\" stop-color=\"#34d399\" stop-opacity=\"0.1\"/>\r\n    </linearGradient>\r\n\r\n    <!-- Core Glow Filters -->\r\n    <filter id=\"glow\" x=\"-20%\" y=\"-20%\" width=\"140%\" height=\"140%\">\r\n      <feGaussianBlur stdDeviation=\"5\" result=\"blur\"/>\r\n      <feComposite in=\"SourceGraphic\" in2=\"blur\" operator=\"over\"/>\r\n    </filter>\r\n\r\n    <filter id=\"halo\" x=\"-30%\" y=\"-30%\" width=\"160%\" height=\"160%\">\r\n      <feGaussianBlur stdDeviation=\"24\" result=\"blur\"/>\r\n    </filter>\r\n  </defs>\r\n\r\n  <!-- Squircle Base Frame -->\r\n  <rect x=\"16\" y=\"16\" width=\"480\" height=\"480\" rx=\"112\" fill=\"url(#iconBg)\" stroke=\"url(#iconBorder)\" stroke-width=\"3\"/>\r\n\r\n  <!-- Ambient Backdrop Halo -->\r\n  <circle cx=\"256\" cy=\"256\" r=\"130\" fill=\"#38bdf8\" opacity=\"0.12\" filter=\"url(#halo)\"/>\r\n\r\n  <!-- BACK ORBITS (Rendered Behind Cube) -->\r\n  <g transform=\"rotate(-26 256 256)\">\r\n    <!-- Primary Back Orbit Arc -->\r\n    <path d=\"M 76 256 A 180 62 0 0 1 436 256\" stroke=\"url(#orbitGlowPrimary)\" stroke-width=\"4\" stroke-linecap=\"round\" opacity=\"0.35\" stroke-dasharray=\"8 6\"/>\r\n  </g>\r\n\r\n  <g transform=\"rotate(34 256 256)\">\r\n    <!-- Secondary Back Orbit Arc -->\r\n    <path d=\"M 106 256 A 150 50 0 0 1 406 256\" stroke=\"url(#orbitGlowSecondary)\" stroke-width=\"3\" stroke-linecap=\"round\" opacity=\"0.3\"/>\r\n  </g>\r\n\r\n  <!-- THE MINECRAFT CORE CUBE -->\r\n  <g id=\"cube\">\r\n    <!-- Top Face -->\r\n    <polygon points=\"256,154 342,204 256,254 170,204\" fill=\"url(#topFace)\"/>\r\n    \r\n    <!-- Top Face Grid / Voxel Accent -->\r\n    <polygon points=\"256,154 299,179 256,204 213,179\" fill=\"#ffffff\" opacity=\"0.4\"/>\r\n    <polygon points=\"256,204 299,229 256,254 213,229\" fill=\"#cbd5e1\" opacity=\"0.25\"/>\r\n\r\n    <!-- Left Face -->\r\n    <polygon points=\"170,204 256,254 256,354 170,304\" fill=\"url(#leftFace)\"/>\r\n    \r\n    <!-- Left Face Voxel Inset -->\r\n    <polygon points=\"170,204 213,229 213,329 170,304\" fill=\"#64748b\" opacity=\"0.4\"/>\r\n    \r\n    <!-- Right Face -->\r\n    <polygon points=\"256,254 342,204 342,304 256,354\" fill=\"url(#rightFace)\"/>\r\n\r\n    <!-- Right Face Voxel Inset -->\r\n    <polygon points=\"299,229 342,204 342,304 299,329\" fill=\"#0f172a\" opacity=\"0.4\"/>\r\n\r\n    <!-- Cube Bevel Edge Lines -->\r\n    <line x1=\"256\" y1=\"154\" x2=\"256\" y2=\"254\" stroke=\"#ffffff\" stroke-width=\"2\" opacity=\"0.7\"/>\r\n    <line x1=\"170\" y1=\"204\" x2=\"256\" y2=\"254\" stroke=\"#ffffff\" stroke-width=\"1.5\" opacity=\"0.4\"/>\r\n    <line x1=\"342\" y1=\"204\" x2=\"256\" y2=\"254\" stroke=\"#ffffff\" stroke-width=\"1.5\" opacity=\"0.4\"/>\r\n    <line x1=\"256\" y1=\"254\" x2=\"256\" y2=\"354\" stroke=\"#38bdf8\" stroke-width=\"2.5\" opacity=\"0.9\"/>\r\n  </g>\r\n\r\n  <!-- FRONT ORBITS (Rendered in Front of Cube for 3D Depth) -->\r\n  <g transform=\"rotate(-26 256 256)\">\r\n    <!-- Primary Front Orbit Arc (Sweeps across the cube) -->\r\n    <path d=\"M 436 256 A 180 62 0 0 1 76 256\" stroke=\"url(#orbitGlowPrimary)\" stroke-width=\"4.5\" stroke-linecap=\"round\" filter=\"url(#glow)\"/>\r\n\r\n    <!-- Satellite Node on Primary Orbit -->\r\n    <circle cx=\"376\" cy=\"296\" r=\"8\" fill=\"#ffffff\" filter=\"url(#glow)\"/>\r\n    <circle cx=\"376\" cy=\"296\" r=\"14\" stroke=\"#38bdf8\" stroke-width=\"2\" opacity=\"0.7\"/>\r\n    <circle cx=\"376\" cy=\"296\" r=\"4\" fill=\"#38bdf8\"/>\r\n  </g>\r\n\r\n  <g transform=\"rotate(34 256 256)\">\r\n    <!-- Secondary Front Orbit Arc -->\r\n    <path d=\"M 406 256 A 150 50 0 0 1 106 256\" stroke=\"url(#orbitGlowSecondary)\" stroke-width=\"3\" stroke-linecap=\"round\" opacity=\"0.85\"/>\r\n    \r\n    <!-- Secondary Satellite Node -->\r\n    <circle cx=\"138\" cy=\"274\" r=\"5\" fill=\"#ffffff\"/>\r\n    <circle cx=\"138\" cy=\"274\" r=\"9\" stroke=\"#a855f7\" stroke-width=\"1.5\" opacity=\"0.6\"/>\r\n  </g>\r\n\r\n  <!-- Sparkle Particle Accents -->\r\n  <circle cx=\"210\" cy=\"116\" r=\"2.5\" fill=\"#ffffff\" opacity=\"0.85\"/>\r\n  <circle cx=\"340\" cy=\"136\" r=\"3\" fill=\"#38bdf8\" opacity=\"0.7\"/>\r\n  <circle cx=\"120\" cy=\"380\" r=\"2.5\" fill=\"#38bdf8\" opacity=\"0.6\"/>\r\n  <circle cx=\"390\" cy=\"380\" r=\"2\" fill=\"#ffffff\" opacity=\"0.7\"/>\r\n</svg>\r\n",
  "index.html": "<!DOCTYPE html>\r\n<html lang=\"en\" class=\"dark\">\r\n<head>\r\n  <meta charset=\"UTF-8\">\r\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n  <title>CraftOrbit | Minecraft Server Manager</title>\r\n  <!-- Favicon -->\r\n  <link rel=\"icon\" type=\"image/svg+xml\" href=\"favicon.svg\">\r\n  <link rel=\"apple-touch-icon\" href=\"icon.svg\">\r\n  <!-- Tailwind CSS CDN -->\r\n  <script src=\"https://cdn.tailwindcss.com\"></script>\r\n  <script>\r\n    tailwind.config = {\r\n      darkMode: 'class',\r\n      theme: {\r\n        extend: {\r\n          colors: {\r\n            brand: {\r\n              black: '#000000',\r\n              card: '#0a0a0a',\r\n              cardHover: '#121212',\r\n              border: '#222222',\r\n              borderLight: '#333333'\r\n            }\r\n          }\r\n        }\r\n      }\r\n    }\r\n  </script>\r\n  <!-- Lucide Icons -->\r\n  <script src=\"https://unpkg.com/lucide@latest\"></script>\r\n  <!-- Chart.js -->\r\n  <script src=\"https://cdn.jsdelivr.net/npm/chart.js\"></script>\r\n  <link rel=\"stylesheet\" href=\"styles.css\">\r\n</head>\r\n<body class=\"bg-black text-white min-h-screen flex flex-col font-sans antialiased selection:bg-white selection:text-black\">\r\n\r\n  <!-- Toast Notification Container -->\r\n  <div id=\"toastContainer\" class=\"fixed top-5 right-5 z-50 flex flex-col gap-2 pointer-events-none\"></div>\r\n\r\n  <!-- Root App Shell (Supports Sidebar Mode vs Topbar Mode) -->\r\n  <div id=\"appShell\" class=\"mode-sidebar flex flex-col md:flex-row flex-1 w-full min-h-screen\">\r\n\r\n    <!-- Left Sidebar Navigation (Argonara / Pterodactyl Style) -->\r\n    <aside id=\"leftSidebar\" class=\"hidden md:flex w-64 border-r border-[#1a2130] bg-[#07090e] shrink-0 flex-col justify-between p-4 min-h-screen sticky top-0 h-screen z-30\">\r\n      <!-- Top Branding & Server Picker -->\r\n      <div class=\"space-y-4\">\r\n        <div class=\"flex items-center justify-between pb-3 border-b border-[#18202d]\">\r\n          <div class=\"flex items-center gap-2.5\">\r\n            <img src=\"logo.svg\" alt=\"CraftOrbit\" class=\"w-8 h-8 object-contain drop-shadow-[0_0_12px_rgba(56,189,248,0.4)]\">\r\n            <div>\r\n              <span class=\"font-bold text-sm text-white tracking-tight\">CraftOrbit</span>\r\n              <span class=\"block text-[10px] font-mono text-neutral-400\">Server Panel</span>\r\n            </div>\r\n          </div>\r\n          <!-- Quick Layout Toggle Icon Button -->\r\n          <button onclick=\"toggleLayoutMode()\" class=\"p-1.5 rounded-lg bg-[#0e121a] hover:bg-[#1a2230] border border-[#222c3d] text-neutral-400 hover:text-white transition\" title=\"Switch to Top Navigation Bar\">\r\n            <i data-lucide=\"columns-2\" class=\"w-4 h-4\"></i>\r\n          </button>\r\n        </div>\r\n\r\n        <!-- Active Server Pill Dropdown Button -->\r\n        <button onclick=\"toggleInstanceMenu(event)\" class=\"w-full text-left p-2.5 rounded-xl bg-[#0c1017] hover:bg-[#141a24] border border-[#1e2637] transition group flex items-center justify-between\">\r\n          <div class=\"truncate pr-2\">\r\n            <div class=\"text-[9px] font-mono text-neutral-400 uppercase tracking-wider\">ACTIVE SERVER</div>\r\n            <div id=\"sidebarInstanceName\" class=\"text-xs font-bold text-white truncate\">Loading Server...</div>\r\n          </div>\r\n          <span id=\"sidebarInstanceTypeBadge\" class=\"text-[10px] font-mono px-1.5 py-0.5 rounded bg-neutral-900 border border-[#2d3748] text-neutral-300 shrink-0\">--</span>\r\n        </button>\r\n\r\n        <!-- Navigation Groups -->\r\n        <nav class=\"space-y-4 font-mono text-xs overflow-y-auto max-h-[calc(100vh-270px)] pr-1 no-scrollbar\">\r\n          <!-- Group: GENERAL -->\r\n          <div class=\"space-y-1\">\r\n            <div class=\"px-2.5 py-1 text-[10px] font-bold text-neutral-400 uppercase tracking-wider flex items-center gap-1.5\">\r\n              <span>GENERAL</span>\r\n            </div>\r\n            <button onclick=\"switchTab('dashboard')\" id=\"side-tab-dashboard\" class=\"sidebar-tab-btn active w-full text-left px-3 py-2 rounded-xl flex items-center gap-2.5 transition\">\r\n              <i data-lucide=\"layout-dashboard\" class=\"w-4 h-4\"></i>\r\n              <span>Workspace</span>\r\n            </button>\r\n            <button onclick=\"switchTab('console')\" id=\"side-tab-console\" class=\"sidebar-tab-btn w-full text-left px-3 py-2 rounded-xl flex items-center gap-2.5 transition\">\r\n              <i data-lucide=\"terminal\" class=\"w-4 h-4\"></i>\r\n              <span>Console</span>\r\n            </button>\r\n            <button onclick=\"switchTab('settings')\" id=\"side-tab-settings\" class=\"sidebar-tab-btn w-full text-left px-3 py-2 rounded-xl flex items-center gap-2.5 transition\">\r\n              <i data-lucide=\"sliders\" class=\"w-4 h-4\"></i>\r\n              <span>Settings</span>\r\n            </button>\r\n            <button onclick=\"switchTab('ai')\" id=\"side-tab-ai\" class=\"sidebar-tab-btn w-full text-left px-3 py-2 rounded-xl flex items-center gap-2.5 transition\">\r\n              <i data-lucide=\"sparkles\" class=\"w-4 h-4 text-purple-400\"></i>\r\n              <span>AI Server Sage</span>\r\n            </button>\r\n          </div>\r\n\r\n          <!-- Group: MANAGEMENT -->\r\n          <div class=\"space-y-1\">\r\n            <div class=\"px-2.5 py-1 text-[10px] font-bold text-neutral-400 uppercase tracking-wider flex items-center gap-1.5\">\r\n              <span>MANAGEMENT</span>\r\n            </div>\r\n            <button onclick=\"switchTab('files')\" id=\"side-tab-files\" class=\"sidebar-tab-btn w-full text-left px-3 py-2 rounded-xl flex items-center gap-2.5 transition\">\r\n              <i data-lucide=\"folder\" class=\"w-4 h-4\"></i>\r\n              <span>File Manager</span>\r\n            </button>\r\n            <button onclick=\"switchTab('mods')\" id=\"side-tab-mods\" class=\"sidebar-tab-btn w-full text-left px-3 py-2 rounded-xl flex items-center justify-between transition\">\r\n              <div class=\"flex items-center gap-2.5\">\r\n                <i data-lucide=\"puzzle\" class=\"w-4 h-4\"></i>\r\n                <span>Mod Manager</span>\r\n              </div>\r\n              <span id=\"sidebarBadgeModCount\" class=\"text-[10px] px-1.5 py-0.5 rounded bg-[#161c28] border border-[#273244] text-neutral-400\">0</span>\r\n            </button>\r\n            <button onclick=\"switchTab('storage')\" id=\"side-tab-storage\" class=\"sidebar-tab-btn w-full text-left px-3 py-2 rounded-xl flex items-center gap-2.5 transition\">\r\n              <i data-lucide=\"hard-drive\" class=\"w-4 h-4\"></i>\r\n              <span>Backups &amp; Storage</span>\r\n            </button>\r\n            <button onclick=\"switchTab('playit')\" id=\"side-tab-playit\" class=\"sidebar-tab-btn w-full text-left px-3 py-2 rounded-xl flex items-center justify-between transition\">\r\n              <div class=\"flex items-center gap-2.5\">\r\n                <i data-lucide=\"globe\" class=\"w-4 h-4\"></i>\r\n                <span>Global Network</span>\r\n              </div>\r\n              <span class=\"w-2 h-2 rounded-full bg-neutral-600\" id=\"sidebarPlayitDot\"></span>\r\n            </button>\r\n            <button onclick=\"switchTab('players')\" id=\"side-tab-players\" class=\"sidebar-tab-btn w-full text-left px-3 py-2 rounded-xl flex items-center gap-2.5 transition\">\r\n              <i data-lucide=\"users\" class=\"w-4 h-4\"></i>\r\n              <span>Players &amp; Roster</span>\r\n            </button>\r\n            <button onclick=\"openAutoEggModal()\" class=\"w-full text-left px-3 py-2 rounded-xl flex items-center gap-2.5 text-neutral-400 hover:text-white hover:bg-white/5 transition\">\r\n              <i data-lucide=\"folder-down\" class=\"w-4 h-4 text-emerald-400\"></i>\r\n              <span>Host New World</span>\r\n            </button>\r\n          </div>\r\n        </nav>\r\n      </div>\r\n\r\n      <!-- Sidebar Footer -->\r\n      <div class=\"pt-3 border-t border-[#18202d] space-y-2\">\r\n        <button onclick=\"openCommandPalette()\" class=\"w-full px-3 py-2 rounded-xl bg-[#0b0e14] hover:bg-[#141a24] border border-[#1e2738] text-xs font-mono text-neutral-400 hover:text-white flex items-center justify-between transition\">\r\n          <div class=\"flex items-center gap-2\">\r\n            <i data-lucide=\"command\" class=\"w-3.5 h-3.5\"></i>\r\n            <span>Palette</span>\r\n          </div>\r\n          <kbd class=\"px-1.5 py-0.5 rounded bg-black border border-[#2d3748] text-[9px]\">Ctrl K</kbd>\r\n        </button>\r\n\r\n        <div class=\"flex items-center justify-between text-xs font-mono text-neutral-400 pt-1\">\r\n          <button onclick=\"toggleAudio()\" class=\"p-2 rounded-lg hover:bg-white/5 hover:text-white transition\" title=\"Toggle UI Audio\">\r\n            <i data-lucide=\"volume-2\" class=\"w-4 h-4\"></i>\r\n          </button>\r\n          <button onclick=\"toggleLayoutMode()\" class=\"px-2.5 py-1.5 rounded-lg bg-[#0f141e] hover:bg-[#18202c] border border-[#222c3d] text-[11px] text-neutral-300 hover:text-white transition flex items-center gap-1.5\" title=\"Switch to Top Navigation Bar\">\r\n            <i data-lucide=\"columns-2\" class=\"w-3.5 h-3.5\"></i>\r\n            <span id=\"layoutModeLabel\">Sidebar</span>\r\n          </button>\r\n          <button onclick=\"shutdownDashboard()\" class=\"p-2 rounded-lg hover:bg-red-500/10 hover:text-red-400 transition\" title=\"Shutdown Server Dashboard\">\r\n            <i data-lucide=\"power\" class=\"w-4 h-4\"></i>\r\n          </button>\r\n        </div>\r\n      </div>\r\n    </aside>\r\n\r\n    <!-- Main Viewport Area (Contains Header & Main Views) -->\r\n    <div id=\"mainViewWrapper\" class=\"flex-1 flex flex-col min-w-0\">\r\n\r\n  <!-- Top Navigation Bar -->\r\n  <header class=\"bg-black/95 backdrop-blur border-b border-[#222222] sticky top-0 z-40 px-6 py-2.5\">\r\n    <div class=\"max-w-7xl mx-auto flex flex-wrap items-center justify-between gap-4\">\r\n      <!-- Brand & Server Instance Switcher (Shown in Topbar mode) -->\r\n      <div id=\"headerBrandSwitcher\" class=\"flex items-center gap-3\">\r\n        <a href=\"/\" class=\"flex items-center gap-2.5 group\">\r\n          <img src=\"logo.svg\" alt=\"CraftOrbit\" class=\"w-9 h-9 object-contain drop-shadow-[0_0_12px_rgba(56,189,248,0.4)] transition group-hover:scale-105\">\r\n        </a>\r\n        <div class=\"relative\">\r\n          <div class=\"flex items-center gap-2\">\r\n            <!-- Clickable Server Instance Dropdown Button -->\r\n            <button onclick=\"toggleInstanceMenu(event)\" class=\"flex items-center gap-2 px-2.5 py-1 rounded-lg bg-[#0e0e0e] hover:bg-[#181818] border border-[#2e2e2e] transition group\">\r\n              <span id=\"headerInstanceName\" class=\"font-bold text-sm text-white tracking-tight\">Loading Server...</span>\r\n              <span id=\"headerInstanceTypeBadge\" class=\"text-[10px] font-mono px-1.5 py-0.2 rounded bg-neutral-900 border border-[#333] text-neutral-300\">--</span>\r\n              <i data-lucide=\"chevron-down\" class=\"w-3.5 h-3.5 text-neutral-400 group-hover:text-white transition\"></i>\r\n            </button>\r\n          </div>\r\n          <p class=\"text-xs text-neutral-400 flex items-center gap-1.5 mt-0.5\">\r\n            <span id=\"headerServerFolder\" class=\"truncate max-w-[180px] font-mono text-[11px] text-neutral-500\">...</span>\r\n            <span class=\"text-neutral-600\">•</span>\r\n            <span class=\"cursor-pointer hover:text-white flex items-center gap-1 transition\" onclick=\"copyServerIp()\" title=\"Click to copy IP\">\r\n              <span id=\"headerServerIp\" class=\"font-mono text-[11px]\">localhost:25402</span>\r\n              <i data-lucide=\"copy\" class=\"w-3 h-3\"></i>\r\n            </span>\r\n          </p>\r\n\r\n          <!-- Dropdown Menu -->\r\n          <div id=\"instanceMenu\" class=\"hidden absolute top-full left-0 mt-2 w-80 bg-[#0a0a0a] border border-[#2e2e2e] rounded-xl shadow-2xl p-2 z-50\">\r\n            <div class=\"px-2 py-1.5 text-[11px] font-semibold text-neutral-400 uppercase tracking-wider flex justify-between items-center\">\r\n              <span>Configured Servers</span>\r\n              <span class=\"text-[10px] lowercase text-neutral-500 font-normal\">click to swap</span>\r\n            </div>\r\n            <div id=\"instanceMenuList\" class=\"space-y-1 max-h-60 overflow-y-auto my-1\">\r\n              <!-- Loaded dynamically -->\r\n            </div>\r\n            <div class=\"pt-2 border-t border-[#222] mt-1 space-y-1.5\">\r\n              <button onclick=\"openAutoEggModal()\" class=\"w-full py-1.5 px-2 rounded-lg bg-white hover:bg-neutral-200 text-black text-xs font-semibold flex items-center justify-center gap-1.5 transition\">\r\n                <i data-lucide=\"sparkles\" class=\"w-3.5 h-3.5\"></i> Host World (Auto-Egg)\r\n              </button>\r\n              <button onclick=\"openAddInstanceModal()\" class=\"w-full py-1.5 px-2 rounded-lg bg-[#141414] hover:bg-[#202020] text-neutral-300 border border-[#333] text-xs font-medium flex items-center justify-center gap-1.5 transition\">\r\n                <i data-lucide=\"folder-plus\" class=\"w-3.5 h-3.5\"></i> Add Existing Server Folder\r\n              </button>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- Breadcrumb Bar (Shown in Sidebar mode) -->\r\n      <div id=\"headerBreadcrumb\" class=\"hidden items-center gap-2 font-mono text-xs text-neutral-400\">\r\n        <span class=\"text-neutral-500 flex items-center gap-1.5\"><i data-lucide=\"layout-dashboard\" class=\"w-4 h-4 text-white\"></i> CraftOrbit</span>\r\n        <span class=\"text-neutral-600\">/</span>\r\n        <span id=\"breadcrumbActiveTitle\" class=\"text-white font-semibold\">Workspace Overview</span>\r\n      </div>\r\n\r\n      <!-- Live Status Pill & Quick Controls -->\r\n      <div class=\"flex items-center gap-2.5\">\r\n        <!-- Layout Switcher Button -->\r\n        <button onclick=\"toggleLayoutMode()\" id=\"headerLayoutBtn\" class=\"flex items-center gap-1.5 px-2.5 py-1.5 rounded-lg bg-[#0e0e0e] border border-[#222] hover:border-[#444] text-xs font-mono text-neutral-300 hover:text-white transition\" title=\"Toggle Navigation Layout (Left Sidebar / Top Bar)\">\r\n          <i data-lucide=\"columns-2\" class=\"w-3.5 h-3.5\"></i>\r\n          <span id=\"headerLayoutLabel\" class=\"hidden lg:inline text-[11px]\">Sidebar Mode</span>\r\n        </button>\r\n\r\n        <!-- Quick Command Palette Button -->\r\n        <button onclick=\"openCommandPalette()\" id=\"headerCmdPalette\" class=\"hidden md:flex items-center gap-1.5 px-2.5 py-1.5 rounded-lg bg-[#0e0e0e] border border-[#222] hover:border-[#444] text-xs font-mono text-neutral-400 hover:text-white transition\" title=\"Open Command Palette (Ctrl+K)\">\r\n          <i data-lucide=\"command\" class=\"w-3.5 h-3.5\"></i>\r\n          <span class=\"text-[11px]\">Command Palette</span>\r\n          <kbd class=\"px-1 py-0.2 rounded bg-black border border-[#333] text-[9px]\">Ctrl K</kbd>\r\n        </button>\r\n\r\n        <!-- Audio Mute/Unmute toggle -->\r\n        <button id=\"btnSoundToggle\" onclick=\"toggleAudio()\" class=\"p-2 rounded-lg bg-[#0a0a0a] border border-[#222] hover:border-[#444] text-neutral-400 hover:text-white transition\" title=\"Toggle UI Sound Effects\">\r\n          <i data-lucide=\"volume-2\" id=\"soundIcon\" class=\"w-4 h-4\"></i>\r\n        </button>\r\n\r\n        <!-- Language Selector Dropdown -->\r\n        <div class=\"relative\">\r\n          <button onclick=\"toggleLangDropdown(event)\" class=\"flex items-center gap-1.5 px-2.5 py-1.5 rounded-lg bg-[#0e0e0e] hover:bg-[#181818] border border-[#222] hover:border-[#444] text-xs font-mono text-neutral-300 hover:text-white transition\" title=\"Change Display Language\">\r\n            <i data-lucide=\"languages\" class=\"w-3.5 h-3.5 text-neutral-400\"></i>\r\n            <span id=\"headerLangBadge\" class=\"font-bold text-[11px]\">EN</span>\r\n            <i data-lucide=\"chevron-down\" class=\"w-3 h-3 text-neutral-400\"></i>\r\n          </button>\r\n          <div id=\"langDropdown\" class=\"hidden absolute right-0 top-full mt-2 w-48 bg-[#0a0d14] border border-[#222c3d] rounded-xl shadow-2xl p-1.5 z-50 font-mono text-xs\">\r\n            <div class=\"px-2.5 py-1 text-[10px] text-neutral-400 font-bold uppercase tracking-wider\">Select Language</div>\r\n            <button onclick=\"setLanguage('en')\" class=\"w-full text-left px-2.5 py-1.5 rounded-lg hover:bg-white/10 text-white flex items-center justify-between transition\">\r\n              <span class=\"flex items-center gap-2\"><span>🇺🇸</span> English (US)</span>\r\n              <span id=\"langCheck-en\" class=\"text-emerald-400 font-bold text-[11px]\">✓</span>\r\n            </button>\r\n            <button onclick=\"setLanguage('id')\" class=\"w-full text-left px-2.5 py-1.5 rounded-lg hover:bg-white/10 text-neutral-300 hover:text-white flex items-center justify-between transition\">\r\n              <span class=\"flex items-center gap-2\"><span>🇮🇩</span> Bahasa Indonesia</span>\r\n              <span id=\"langCheck-id\" class=\"text-neutral-600 font-bold text-[11px]\"></span>\r\n            </button>\r\n          </div>\r\n        </div>\r\n\r\n        <div id=\"statusBadge\" class=\"flex items-center gap-2 px-3 py-1.5 rounded-full bg-[#0a0a0a] border border-[#262626] text-xs font-mono text-neutral-400 transition-all\">\r\n          <span id=\"statusDot\" class=\"w-2 h-2 rounded-full bg-neutral-600\"></span>\r\n          <span id=\"statusText\">CHECKING...</span>\r\n        </div>\r\n\r\n        <!-- Global Tunnel Pill -->\r\n        <div onclick=\"switchTab('playit')\" class=\"cursor-pointer flex items-center gap-1.5 px-3 py-1.5 rounded-full bg-[#0a0a0a] border border-[#262626] hover:border-neutral-500 text-xs font-mono transition\" title=\"playit.gg Global Hosting Tunnel\">\r\n          <span class=\"w-2 h-2 rounded-full bg-neutral-600\" id=\"playitStatusDot\"></span>\r\n          <span id=\"playitHeaderStatus\">Tunnel: Off</span>\r\n        </div>\r\n\r\n        <div class=\"h-6 w-px bg-[#222]\"></div>\r\n\r\n        <!-- Auto-Host World Button -->\r\n        <button onclick=\"openAutoEggModal()\" class=\"px-3.5 py-1.5 rounded-lg bg-[#141414] hover:bg-[#202020] text-white border border-[#333] font-semibold text-xs flex items-center gap-1.5 transition\" title=\"Auto-deploy a server from any singleplayer world or folder\">\r\n          <i data-lucide=\"sparkles\" class=\"w-3.5 h-3.5\"></i> Host World\r\n        </button>\r\n\r\n        <!-- Quick Start/Stop Buttons (Shown in Topbar mode) -->\r\n        <div id=\"headerPowerActions\" class=\"flex items-center gap-2\">\r\n          <button id=\"btnStart\" onclick=\"startServer()\" class=\"px-4 py-1.5 rounded-lg bg-white hover:bg-neutral-200 text-black font-semibold text-xs flex items-center gap-1.5 transition\">\r\n            <i data-lucide=\"play\" class=\"w-3.5 h-3.5 fill-current\"></i> Start\r\n          </button>\r\n          <button id=\"btnStop\" onclick=\"stopServer()\" class=\"px-4 py-1.5 rounded-lg bg-[#141414] hover:bg-[#222] text-neutral-200 border border-[#333] font-medium text-xs flex items-center gap-1.5 transition opacity-50 cursor-not-allowed\" disabled>\r\n            <i data-lucide=\"square\" class=\"w-3.5 h-3.5 fill-current\"></i> Stop\r\n          </button>\r\n          <button id=\"btnRestart\" onclick=\"restartServer()\" class=\"p-1.5 rounded-lg bg-[#0a0a0a] hover:bg-[#161616] text-neutral-300 border border-[#222] font-medium text-xs transition\" title=\"Restart Server\">\r\n            <i data-lucide=\"rotate-cw\" class=\"w-4 h-4\"></i>\r\n          </button>\r\n          <button id=\"btnKill\" onclick=\"killServer()\" class=\"p-1.5 rounded-lg bg-[#0a0a0a] hover:bg-neutral-900 text-neutral-400 hover:text-white border border-[#262626] font-medium text-xs transition\" title=\"Force Kill Process\">\r\n            <i data-lucide=\"zap-off\" class=\"w-4 h-4\"></i>\r\n          </button>\r\n        </div>\r\n\r\n        <div class=\"h-5 w-px bg-[#222]\"></div>\r\n\r\n        <!-- Shutdown Entire Dashboard Button -->\r\n        <button id=\"btnShutdownDashboard\" onclick=\"shutdownDashboard()\" class=\"p-1.5 rounded-lg bg-[#0a0a0a] hover:bg-white hover:text-black text-neutral-400 border border-[#262626] font-medium text-xs transition group\" title=\"Shutdown Web Dashboard & Stop Servers\">\r\n          <i data-lucide=\"power\" class=\"w-4 h-4\"></i>\r\n        </button>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- Navigation Tabs (Hidden in Sidebar Mode, Visible in Topbar Mode) -->\r\n    <div id=\"topNavTabs\" class=\"max-w-7xl mx-auto mt-2 flex items-center gap-1 border-t border-[#1a1a1a] pt-2 overflow-x-auto text-xs font-medium no-scrollbar\">\r\n      <button onclick=\"switchTab('dashboard')\" id=\"tab-dashboard\" class=\"tab-btn active px-3 py-1.5 rounded-lg flex items-center gap-1.5\">\r\n        <i data-lucide=\"layout-dashboard\" class=\"w-4 h-4\"></i> Dashboard\r\n      </button>\r\n      <button onclick=\"switchTab('ai')\" id=\"tab-ai\" class=\"tab-btn px-3 py-1.5 rounded-lg flex items-center gap-1.5\">\r\n        <i data-lucide=\"sparkles\" class=\"w-4 h-4\"></i> AI Copilot\r\n      </button>\r\n      <button onclick=\"switchTab('mods')\" id=\"tab-mods\" class=\"tab-btn px-3 py-1.5 rounded-lg flex items-center gap-1.5\">\r\n        <i data-lucide=\"puzzle\" class=\"w-4 h-4\"></i> Mod Manager\r\n        <span id=\"badgeModCount\" class=\"px-1.5 py-0.2 rounded bg-[#161616] border border-[#262626] font-mono text-[10px] text-neutral-400\">281</span>\r\n      </button>\r\n      <button onclick=\"switchTab('players')\" id=\"tab-players\" class=\"tab-btn px-3 py-1.5 rounded-lg flex items-center gap-1.5\">\r\n        <i data-lucide=\"users\" class=\"w-4 h-4\"></i> Players & Roster\r\n      </button>\r\n      <button onclick=\"switchTab('storage')\" id=\"tab-storage\" class=\"tab-btn px-3 py-1.5 rounded-lg flex items-center gap-1.5\">\r\n        <i data-lucide=\"hard-drive\" class=\"w-4 h-4\"></i> Storage & Backups\r\n      </button>\r\n      <button onclick=\"switchTab('playit')\" id=\"tab-playit\" class=\"tab-btn px-3 py-1.5 rounded-lg flex items-center gap-1.5\">\r\n        <i data-lucide=\"globe\" class=\"w-4 h-4\"></i> Global Tunnel\r\n      </button>\r\n      <button onclick=\"switchTab('console')\" id=\"tab-console\" class=\"tab-btn px-3 py-1.5 rounded-lg flex items-center gap-1.5\">\r\n        <i data-lucide=\"terminal\" class=\"w-4 h-4\"></i> Live Console\r\n      </button>\r\n      <button onclick=\"switchTab('files')\" id=\"tab-files\" class=\"tab-btn px-3 py-1.5 rounded-lg flex items-center gap-1.5\">\r\n        <i data-lucide=\"folder\" class=\"w-4 h-4\"></i> File Explorer\r\n      </button>\r\n      <button onclick=\"switchTab('settings')\" id=\"tab-settings\" class=\"tab-btn px-3 py-1.5 rounded-lg flex items-center gap-1.5\">\r\n        <i data-lucide=\"sliders\" class=\"w-4 h-4\"></i> Settings\r\n      </button>\r\n    </div>\r\n  </header>\r\n\r\n  <!-- Main Content Container -->\r\n  <main class=\"max-w-7xl mx-auto w-full p-6 flex-1 flex flex-col gap-6\">\r\n\r\n    <!-- ================= TAB 1: DASHBOARD ================= -->\r\n    <section id=\"view-dashboard\" class=\"flex flex-col gap-6\">\r\n      <!-- Welcome Onboarding Card (for fresh setup or when no server is selected) -->\r\n      <div id=\"welcomeHeroCard\" class=\"hidden p-6 rounded-2xl bg-[#0a0a0a] border border-white/40 space-y-4\">\r\n        <div class=\"flex items-center gap-3\">\r\n          <div class=\"w-10 h-10 rounded-xl bg-white text-black flex items-center justify-center font-bold\">\r\n            <i data-lucide=\"sparkles\" class=\"w-5 h-5\"></i>\r\n          </div>\r\n          <div>\r\n            <h2 class=\"text-base font-bold text-white\">Welcome to CraftOrbit!</h2>\r\n            <p class=\"text-xs text-neutral-400\">Get your server online in seconds. Choose how you want to start:</p>\r\n          </div>\r\n        </div>\r\n\r\n        <div class=\"grid grid-cols-1 md:grid-cols-2 gap-4 pt-1\">\r\n          <div onclick=\"openAutoEggModal()\" class=\"p-4 rounded-xl bg-black border border-[#2e2e2e] hover:border-white cursor-pointer transition flex flex-col justify-between group\">\r\n            <div>\r\n              <div class=\"flex items-center gap-2 text-white font-bold text-sm\">\r\n                <i data-lucide=\"folder-down\" class=\"w-4 h-4 text-white\"></i>\r\n                <span>Host Singleplayer World (Auto-Egg)</span>\r\n              </div>\r\n              <p class=\"text-xs text-neutral-400 mt-2 leading-relaxed\">Select any singleplayer world. We automatically detect the version, download Paper/Fabric jars, and set everything up.</p>\r\n            </div>\r\n            <div class=\"mt-4 pt-2 border-t border-[#1a1a1a] flex items-center justify-between text-xs font-semibold text-white group-hover:underline\">\r\n              <span>Launch Setup Wizard &rarr;</span>\r\n              <span class=\"text-[10px] font-mono px-2 py-0.5 rounded bg-white text-black\">Recommended</span>\r\n            </div>\r\n          </div>\r\n\r\n          <div onclick=\"openAddInstanceModal()\" class=\"p-4 rounded-xl bg-black border border-[#2e2e2e] hover:border-white cursor-pointer transition flex flex-col justify-between group\">\r\n            <div>\r\n              <div class=\"flex items-center gap-2 text-white font-bold text-sm\">\r\n                <i data-lucide=\"folder\" class=\"w-4 h-4 text-white\"></i>\r\n                <span>Add Existing Server Folder</span>\r\n              </div>\r\n              <p class=\"text-xs text-neutral-400 mt-2 leading-relaxed\">Already have a server directory (e.g. Cisco CARPG, Bedrock, Paper)? Enter the folder path to manage it.</p>\r\n            </div>\r\n            <div class=\"mt-4 pt-2 border-t border-[#1a1a1a] flex items-center justify-between text-xs font-semibold text-white group-hover:underline\">\r\n              <span>Browse Folder &rarr;</span>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- Server Hero Workspace Card (Pterodactyl / Argonara Style) -->\r\n      <div id=\"serverHeroCard\" class=\"p-5 sm:p-6 rounded-2xl glass-panel relative overflow-hidden flex flex-col lg:flex-row items-start lg:items-center justify-between gap-6 shadow-2xl\">\r\n        <!-- Left: Voxel Artwork + Details -->\r\n        <div class=\"flex items-center gap-4 min-w-0\">\r\n          <div class=\"w-16 h-16 sm:w-20 sm:h-20 rounded-2xl bg-[#0e131d] border border-white/10 flex items-center justify-center p-2.5 shadow-lg shrink-0\">\r\n            <img src=\"logo.svg\" alt=\"CraftOrbit Server\" class=\"w-full h-full object-contain drop-shadow-[0_0_15px_rgba(56,189,248,0.5)]\">\r\n          </div>\r\n          <div class=\"min-w-0 space-y-1.5\">\r\n            <div class=\"flex items-center gap-2 flex-wrap\">\r\n              <h1 id=\"heroServerName\" class=\"text-lg sm:text-xl font-black text-white tracking-tight truncate\">Survival Server</h1>\r\n              <span id=\"heroEngineBadge\" class=\"px-2 py-0.5 rounded bg-blue-500/10 border border-blue-500/20 text-blue-400 font-mono text-[10px] font-bold uppercase\">PAPER</span>\r\n              <span id=\"heroStatusBadge\" class=\"px-2 py-0.5 rounded bg-neutral-900 border border-neutral-800 text-neutral-400 font-mono text-[10px] flex items-center gap-1.5\">\r\n                <span class=\"w-2 h-2 rounded-full bg-neutral-600\" id=\"heroStatusDot\"></span>\r\n                <span id=\"heroStatusText\">OFFLINE</span>\r\n              </span>\r\n            </div>\r\n            <!-- Copyable IP Address Pill -->\r\n            <div class=\"flex items-center gap-2\">\r\n              <div onclick=\"copyServerIp()\" class=\"inline-flex items-center gap-2 px-3 py-1 rounded-lg bg-[#07090e] border border-[#1e2738] hover:border-white/30 text-xs font-mono text-neutral-300 hover:text-white cursor-pointer transition group\" title=\"Click to copy IP address\">\r\n                <span class=\"text-neutral-500\">IP:</span>\r\n                <span id=\"heroServerIpDisplay\" class=\"font-semibold text-white\">localhost:25402</span>\r\n                <i data-lucide=\"copy\" class=\"w-3.5 h-3.5 text-neutral-500 group-hover:text-white transition\"></i>\r\n              </div>\r\n            </div>\r\n          </div>\r\n        </div>\r\n\r\n        <!-- Middle: Metric Progress Bars (CPU, RAM, DISK) -->\r\n        <div class=\"grid grid-cols-1 sm:grid-cols-3 gap-3 w-full lg:w-auto lg:min-w-[480px] xl:min-w-[520px] font-mono text-xs\">\r\n          <!-- CPU Metric -->\r\n          <div class=\"space-y-1.5 p-3 rounded-xl bg-[#07090e]/90 border border-[#1e2738] shadow-inner overflow-hidden flex flex-col justify-between\">\r\n            <div class=\"flex items-center justify-between text-[11px] gap-2\">\r\n              <span class=\"text-neutral-400 flex items-center gap-1.5\"><i data-lucide=\"cpu\" class=\"w-3.5 h-3.5 text-emerald-400\"></i> CPU</span>\r\n              <span id=\"heroCpuPercent\" class=\"font-bold text-white tracking-tight\">0%</span>\r\n            </div>\r\n            <div class=\"w-full h-1.5 rounded-full bg-[#161c28] overflow-hidden\">\r\n              <div id=\"heroCpuBar\" class=\"h-full bg-emerald-500 rounded-full transition-all duration-300\" style=\"width: 0%\"></div>\r\n            </div>\r\n            <div class=\"flex justify-between text-[9px] text-neutral-500 font-mono\">\r\n              <span>Host Load</span>\r\n              <span>100% Max</span>\r\n            </div>\r\n          </div>\r\n\r\n          <!-- RAM Metric -->\r\n          <div class=\"space-y-1.5 p-3 rounded-xl bg-[#07090e]/90 border border-[#1e2738] shadow-inner overflow-hidden flex flex-col justify-between\">\r\n            <div class=\"flex items-center justify-between text-[11px] gap-2\">\r\n              <span class=\"text-neutral-400 flex items-center gap-1.5\"><i data-lucide=\"activity\" class=\"w-3.5 h-3.5 text-blue-400\"></i> RAM</span>\r\n              <span id=\"heroRamUsage\" class=\"font-bold text-white tracking-tight\">0 MB</span>\r\n            </div>\r\n            <div class=\"w-full h-1.5 rounded-full bg-[#161c28] overflow-hidden\">\r\n              <div id=\"heroRamBar\" class=\"h-full bg-blue-500 rounded-full transition-all duration-300\" style=\"width: 0%\"></div>\r\n            </div>\r\n            <div class=\"flex justify-between text-[9px] text-neutral-500 font-mono\">\r\n              <span>Allocated</span>\r\n              <span id=\"heroRamMaxLabel\">6 GB Max</span>\r\n            </div>\r\n          </div>\r\n\r\n          <!-- DISK Metric -->\r\n          <div class=\"space-y-1.5 p-3 rounded-xl bg-[#07090e]/90 border border-[#1e2738] shadow-inner overflow-hidden flex flex-col justify-between\">\r\n            <div class=\"flex items-center justify-between text-[11px] gap-2\">\r\n              <span class=\"text-neutral-400 flex items-center gap-1.5\"><i data-lucide=\"hard-drive\" class=\"w-3.5 h-3.5 text-purple-400\"></i> DISK</span>\r\n              <span id=\"heroDiskUsage\" class=\"font-bold text-white tracking-tight\">-- GB</span>\r\n            </div>\r\n            <div class=\"w-full h-1.5 rounded-full bg-[#161c28] overflow-hidden\">\r\n              <div id=\"heroDiskBar\" class=\"h-full bg-purple-500 rounded-full transition-all duration-300\" style=\"width: 25%\"></div>\r\n            </div>\r\n            <div class=\"flex justify-between text-[9px] text-neutral-500 font-mono\">\r\n              <span class=\"text-neutral-400 font-semibold\">Available</span>\r\n              <span id=\"heroDiskTotalLabel\">Host Drive (C:)</span>\r\n            </div>\r\n          </div>\r\n        </div>\r\n\r\n        <!-- Right: Primary Action Buttons -->\r\n        <div class=\"flex items-center gap-2.5 w-full lg:w-auto shrink-0 justify-end\">\r\n          <button onclick=\"startServer()\" id=\"heroBtnStart\" class=\"px-5 py-2.5 rounded-xl bg-white hover:bg-neutral-200 text-black font-bold text-xs flex items-center gap-2 shadow-lg transition btn-glow\">\r\n            <i data-lucide=\"play\" class=\"w-4 h-4 fill-current\"></i>\r\n            <span>START</span>\r\n          </button>\r\n          <button onclick=\"restartServer()\" id=\"heroBtnRestart\" class=\"px-4 py-2.5 rounded-xl bg-[#141924] hover:bg-[#1d2535] text-neutral-200 border border-[#2a364a] font-semibold text-xs flex items-center gap-2 transition\">\r\n            <i data-lucide=\"rotate-cw\" class=\"w-4 h-4\"></i>\r\n            <span>RESTART</span>\r\n          </button>\r\n          <button onclick=\"stopServer()\" id=\"heroBtnStop\" class=\"px-4 py-2.5 rounded-xl bg-red-500/10 hover:bg-red-500/20 text-red-400 border border-red-500/20 font-semibold text-xs flex items-center gap-2 transition opacity-50 cursor-not-allowed\" disabled>\r\n            <i data-lucide=\"square\" class=\"w-4 h-4 fill-current\"></i>\r\n            <span>STOP</span>\r\n          </button>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- Share Invite Banner (Shown when server is online) -->\r\n      <div id=\"shareInviteBanner\" class=\"hidden p-5 rounded-2xl bg-white text-black flex flex-col md:flex-row items-start md:items-center justify-between gap-4 shadow-2xl\">\r\n        <div class=\"space-y-2 flex-1\">\r\n          <div class=\"flex items-center gap-2 font-bold text-sm\">\r\n            <span class=\"w-2.5 h-2.5 rounded-full bg-black pulse-active\"></span>\r\n            <span>Server is Online & Ready for Players!</span>\r\n            <span id=\"shareInviteScopeBadge\" class=\"text-[10px] font-mono px-2 py-0.5 rounded bg-black text-white uppercase font-bold tracking-wider\">Localhost / LAN</span>\r\n          </div>\r\n          \r\n          <!-- Multi-Address Badges: Internet (playit) / Home Wi-Fi (LAN) / Mobile (Bedrock) -->\r\n          <div class=\"grid grid-cols-1 sm:grid-cols-3 gap-2 pt-1\">\r\n            <div class=\"bg-neutral-100 p-2.5 rounded-xl border border-neutral-300 flex flex-col justify-between\">\r\n              <div class=\"flex items-center justify-between text-[10px] font-bold text-neutral-600 uppercase\">\r\n                <span>🌐 Internet (playit.gg)</span>\r\n                <button onclick=\"copySpecificAddress('global')\" class=\"underline hover:text-black font-semibold\">Copy</button>\r\n              </div>\r\n              <div class=\"font-mono text-xs font-bold text-black truncate mt-1 select-all\" id=\"shareGlobalAddressText\">Not Configured</div>\r\n            </div>\r\n\r\n            <div class=\"bg-neutral-100 p-2.5 rounded-xl border border-neutral-300 flex flex-col justify-between\">\r\n              <div class=\"flex items-center justify-between text-[10px] font-bold text-neutral-600 uppercase\">\r\n                <span>🏠 Home Wi-Fi (LAN)</span>\r\n                <button onclick=\"copySpecificAddress('lan')\" class=\"underline hover:text-black font-semibold\">Copy</button>\r\n              </div>\r\n              <div class=\"font-mono text-xs font-bold text-black truncate mt-1 select-all\" id=\"shareLanAddressText\">127.0.0.1:25565</div>\r\n            </div>\r\n\r\n            <div class=\"bg-neutral-100 p-2.5 rounded-xl border border-neutral-300 flex flex-col justify-between\" id=\"shareBedrockCard\">\r\n              <div class=\"flex items-center justify-between text-[10px] font-bold text-neutral-600 uppercase\">\r\n                <span>📱 Mobile (Bedrock)</span>\r\n                <button onclick=\"copySpecificAddress('bedrock')\" class=\"underline hover:text-black font-semibold\">Copy</button>\r\n              </div>\r\n              <div class=\"font-mono text-xs font-bold text-black truncate mt-1 select-all\" id=\"shareBedrockAddressText\">127.0.0.1:19132</div>\r\n            </div>\r\n          </div>\r\n\r\n          <div id=\"shareInviteTunnelHint\" class=\"text-[11px] font-sans text-neutral-600\"></div>\r\n        </div>\r\n\r\n        <div class=\"flex items-center gap-2 shrink-0\">\r\n          <button onclick=\"copyShareInvite()\" class=\"px-4 py-2.5 rounded-xl bg-black text-white text-xs font-bold flex items-center gap-1.5 transition hover:bg-neutral-800 shadow\">\r\n            <i data-lucide=\"copy\" class=\"w-3.5 h-3.5\"></i> Copy Invite Message\r\n          </button>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- Quick World In-Game Controls Toolbar -->\r\n      <div id=\"quickActionsToolbar\" class=\"flex flex-wrap items-center justify-between gap-3 p-3 rounded-xl bg-[#0a0a0a] border border-[#222]\">\r\n        <div class=\"flex items-center gap-2 text-xs font-semibold text-white\">\r\n          <i data-lucide=\"wand-2\" class=\"w-4 h-4\"></i>\r\n          <span>World Shortcuts:</span>\r\n        </div>\r\n        <div class=\"flex flex-wrap items-center gap-2 text-xs\">\r\n          <button onclick=\"sendQuickAction('day')\" class=\"px-3 py-1.5 rounded-lg bg-black hover:bg-[#181818] border border-[#2e2e2e] text-white flex items-center gap-1.5 transition\">\r\n            ☀️ Set Day\r\n          </button>\r\n          <button onclick=\"sendQuickAction('night')\" class=\"px-3 py-1.5 rounded-lg bg-black hover:bg-[#181818] border border-[#2e2e2e] text-white flex items-center gap-1.5 transition\">\r\n            🌙 Set Night\r\n          </button>\r\n          <button onclick=\"sendQuickAction('weather_clear')\" class=\"px-3 py-1.5 rounded-lg bg-black hover:bg-[#181818] border border-[#2e2e2e] text-white flex items-center gap-1.5 transition\">\r\n            🌤️ Clear Weather\r\n          </button>\r\n          <button onclick=\"sendQuickAction('clearlag')\" class=\"px-3 py-1.5 rounded-lg bg-black hover:bg-[#181818] border border-[#2e2e2e] text-white flex items-center gap-1.5 transition\" title=\"Delete loose ground items to fix lag\">\r\n            🧹 Clear Clutter\r\n          </button>\r\n          <button onclick=\"sendQuickAction('save')\" class=\"px-3 py-1.5 rounded-lg bg-white hover:bg-neutral-200 text-black font-semibold flex items-center gap-1.5 transition\">\r\n            💾 Save Chunks\r\n          </button>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- Hardware Telemetry Meters (Visible in Topbar mode, hidden in Sidebar mode to avoid duplication) -->\r\n      <div id=\"hardwareMetersRow\" class=\"grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4\">\r\n        <!-- Server RAM -->\r\n        <div class=\"bg-[#0a0a0a] border border-[#222] rounded-xl p-4 flex flex-col justify-between\">\r\n          <div class=\"flex items-center justify-between text-neutral-400 text-xs\">\r\n            <span class=\"flex items-center gap-1.5 font-semibold text-white\">\r\n              <i data-lucide=\"cpu\" class=\"w-4 h-4 text-white\"></i> Server Memory\r\n            </span>\r\n            <span id=\"ramPercentText\" class=\"font-mono text-white font-bold\">0%</span>\r\n          </div>\r\n          <div class=\"my-3\">\r\n            <div class=\"text-2xl font-bold font-mono text-white\" id=\"serverRamUsage\">0 MB</div>\r\n            <div class=\"text-xs text-neutral-400\" id=\"serverRamMax\">Allocated: -Xmx6G</div>\r\n          </div>\r\n          <div class=\"w-full bg-[#181818] rounded-full h-1.5 overflow-hidden\">\r\n            <div id=\"ramBar\" class=\"bg-white h-full rounded-full transition-all duration-500\" style=\"width: 0%\"></div>\r\n          </div>\r\n        </div>\r\n\r\n        <!-- System CPU -->\r\n        <div class=\"bg-[#0a0a0a] border border-[#222] rounded-xl p-4 flex flex-col justify-between\">\r\n          <div class=\"flex items-center justify-between text-neutral-400 text-xs\">\r\n            <span class=\"flex items-center gap-1.5 font-semibold text-white\">\r\n              <i data-lucide=\"activity\" class=\"w-4 h-4 text-white\"></i> System CPU\r\n            </span>\r\n            <span id=\"cpuPercentText\" class=\"font-mono text-white font-bold\">0%</span>\r\n          </div>\r\n          <div class=\"my-3\">\r\n            <div class=\"text-2xl font-bold font-mono text-white\" id=\"cpuUsageVal\">0%</div>\r\n            <div class=\"text-xs text-neutral-400\" id=\"cpuCoresVal\">Host System Load</div>\r\n          </div>\r\n          <div class=\"w-full bg-[#181818] rounded-full h-1.5 overflow-hidden\">\r\n            <div id=\"cpuBar\" class=\"bg-neutral-400 h-full rounded-full transition-all duration-500\" style=\"width: 0%\"></div>\r\n          </div>\r\n        </div>\r\n\r\n        <!-- Drive Storage -->\r\n        <div class=\"bg-[#0a0a0a] border border-[#222] rounded-xl p-4 flex flex-col justify-between cursor-pointer hover:border-[#444] transition\" onclick=\"switchTab('storage')\">\r\n          <div class=\"flex items-center justify-between text-neutral-400 text-xs\">\r\n            <span class=\"flex items-center gap-1.5 font-semibold text-white\">\r\n              <i data-lucide=\"database\" class=\"w-4 h-4 text-white\"></i> Drive Storage (C:)\r\n            </span>\r\n            <span id=\"diskPercentText\" class=\"font-mono text-white font-bold\">0%</span>\r\n          </div>\r\n          <div class=\"my-3\">\r\n            <div class=\"text-2xl font-bold font-mono text-white\" id=\"diskFreeVal\">-- GB Available</div>\r\n            <div class=\"text-xs text-neutral-400\" id=\"diskTotalVal\">Total: -- GB</div>\r\n          </div>\r\n          <div class=\"w-full bg-[#181818] rounded-full h-1.5 overflow-hidden\">\r\n            <div id=\"diskBar\" class=\"bg-neutral-300 h-full rounded-full transition-all duration-500\" style=\"width: 0%\"></div>\r\n          </div>\r\n        </div>\r\n\r\n        <!-- Online Players & Uptime -->\r\n        <div class=\"bg-[#0a0a0a] border border-[#222] rounded-xl p-4 flex flex-col justify-between cursor-pointer hover:border-[#444] transition\" onclick=\"switchTab('players')\">\r\n          <div class=\"flex items-center justify-between text-neutral-400 text-xs\">\r\n            <span class=\"flex items-center gap-1.5 font-semibold text-white\">\r\n              <i data-lucide=\"users\" class=\"w-4 h-4 text-white\"></i> Players & Latency\r\n            </span>\r\n            <span id=\"slpPingBadge\" class=\"font-mono text-neutral-400 text-[10px]\">Ping: -- ms</span>\r\n          </div>\r\n          <div class=\"my-3\">\r\n            <div class=\"text-2xl font-bold font-mono text-white\" id=\"onlinePlayersCount\">0 <span class=\"text-xs font-normal text-neutral-400\">/ 5 max</span></div>\r\n            <div class=\"text-xs text-neutral-400 truncate\" id=\"onlinePlayersList\">No players connected</div>\r\n          </div>\r\n          <div class=\"flex items-center justify-between text-[11px] text-neutral-400\">\r\n            <span id=\"uptimeBadge\" class=\"font-mono text-[10px]\">Uptime: --</span>\r\n            <span class=\"text-white hover:underline\">Manage Roster &rarr;</span>\r\n          </div>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- Realtime Performance Graph & Diagnostic Card -->\r\n      <div class=\"grid grid-cols-1 lg:grid-cols-3 gap-6\">\r\n        <!-- Live Performance Graph -->\r\n        <div class=\"lg:col-span-2 bg-[#0a0a0a] border border-[#222] rounded-xl p-5 flex flex-col\">\r\n          <div class=\"flex items-center justify-between mb-4\">\r\n            <div>\r\n              <h2 class=\"font-semibold text-sm text-white flex items-center gap-2\">\r\n                <i data-lucide=\"line-chart\" class=\"w-4 h-4 text-white\"></i> Telemetry Monitor\r\n              </h2>\r\n              <p class=\"text-[11px] text-neutral-400 mt-0.5\">Live RAM (MB) and Host CPU (%) telemetry</p>\r\n            </div>\r\n            <div class=\"flex items-center gap-3 text-xs font-mono\">\r\n              <span class=\"flex items-center gap-1.5 text-white\"><span class=\"w-2 h-2 rounded-full bg-white\"></span> RAM (MB)</span>\r\n              <span class=\"flex items-center gap-1.5 text-neutral-400\"><span class=\"w-2 h-2 rounded-full bg-neutral-400\"></span> CPU (%)</span>\r\n            </div>\r\n          </div>\r\n          <div class=\"relative w-full h-56\">\r\n            <canvas id=\"perfChartCanvas\"></canvas>\r\n          </div>\r\n        </div>\r\n\r\n        <!-- Quick AI Diagnostic Card -->\r\n        <div class=\"bg-[#0a0a0a] border border-[#222] rounded-xl p-5 flex flex-col justify-between\">\r\n          <div>\r\n            <div class=\"flex items-center justify-between mb-3\">\r\n              <div class=\"flex items-center gap-2\">\r\n                <div class=\"w-8 h-8 rounded-lg bg-neutral-900 border border-[#333] text-white flex items-center justify-center\">\r\n                  <i data-lucide=\"bot\" class=\"w-4 h-4\"></i>\r\n                </div>\r\n                <div>\r\n                  <h3 class=\"font-bold text-sm text-white\">AI Server Doctor</h3>\r\n                  <span class=\"text-[10px] text-neutral-400 font-mono\">9Router Connected</span>\r\n                </div>\r\n              </div>\r\n              <button onclick=\"switchTab('ai')\" class=\"text-xs text-neutral-300 hover:text-white flex items-center gap-1\">\r\n                Open &rarr;\r\n              </button>\r\n            </div>\r\n            <p class=\"text-xs text-neutral-400 leading-relaxed mt-2\">\r\n              Instant analysis for crash reports, lag spikes, and modpack conflict diagnosis.\r\n            </p>\r\n            <div id=\"quickAiStatus\" class=\"my-3 p-3 bg-black rounded-lg border border-[#222] text-xs font-mono text-neutral-400\">\r\n              Ready to diagnose server state.\r\n            </div>\r\n          </div>\r\n          <div class=\"space-y-2 mt-2\">\r\n            <button onclick=\"runQuickDiagnosis()\" class=\"w-full py-2 rounded-lg bg-white hover:bg-neutral-200 text-black text-xs font-semibold flex items-center justify-center gap-1.5 transition\">\r\n              <i data-lucide=\"stethoscope\" class=\"w-3.5 h-3.5\"></i> Diagnose Server Now\r\n            </button>\r\n            <button onclick=\"quickCleanLogs()\" class=\"w-full py-2 rounded-lg bg-[#141414] hover:bg-[#1e1e1e] text-neutral-300 border border-[#262626] text-xs font-medium flex items-center justify-center gap-1.5 transition\">\r\n              <i data-lucide=\"trash-2\" class=\"w-3.5 h-3.5 text-neutral-400\"></i> Clear Old Logs\r\n            </button>\r\n          </div>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- Quick Storage & Mini Terminal -->\r\n      <div class=\"grid grid-cols-1 lg:grid-cols-3 gap-6\">\r\n        <!-- Storage Breakdown Doughnut -->\r\n        <div class=\"bg-[#0a0a0a] border border-[#222] rounded-xl p-5 flex flex-col justify-between\">\r\n          <div>\r\n            <div class=\"flex items-center justify-between mb-3\">\r\n              <h2 class=\"font-semibold text-sm text-white flex items-center gap-2\">\r\n                <i data-lucide=\"pie-chart\" class=\"w-4 h-4 text-white\"></i> Storage Distribution\r\n              </h2>\r\n              <button onclick=\"switchTab('storage')\" class=\"text-xs text-neutral-400 hover:text-white\">\r\n                Details &rarr;\r\n              </button>\r\n            </div>\r\n            <div class=\"relative w-full h-44 flex items-center justify-center\">\r\n              <canvas id=\"storageDoughnutCanvas\"></canvas>\r\n            </div>\r\n          </div>\r\n          <div class=\"mt-4 pt-3 border-t border-[#222] flex items-center justify-between text-xs\">\r\n            <span class=\"text-neutral-400\">Total Server: <strong id=\"dashTotalServerVal\" class=\"text-white font-mono\">--</strong></span>\r\n            <button onclick=\"triggerWorldBackup()\" class=\"px-3 py-1 rounded bg-[#141414] hover:bg-[#202020] text-white border border-[#333] flex items-center gap-1 transition\">\r\n              <i data-lucide=\"archive\" class=\"w-3 h-3\"></i> Backup\r\n            </button>\r\n          </div>\r\n        </div>\r\n\r\n        <!-- Mini Live Console Window -->\r\n        <div class=\"lg:col-span-2 bg-[#0a0a0a] border border-[#222] rounded-xl p-5 flex flex-col\">\r\n          <div class=\"flex items-center justify-between mb-3\">\r\n            <h2 class=\"font-semibold text-sm text-white flex items-center gap-2\">\r\n              <i data-lucide=\"terminal\" class=\"w-4 h-4 text-white\"></i> Live Console Stream\r\n            </h2>\r\n            <button onclick=\"switchTab('console')\" class=\"text-xs text-neutral-400 hover:text-white flex items-center gap-1\">\r\n              Full Terminal <i data-lucide=\"chevron-right\" class=\"w-3.5 h-3.5\"></i>\r\n            </button>\r\n          </div>\r\n\r\n          <!-- Mini Terminal Output -->\r\n          <div id=\"dashMiniConsole\" class=\"bg-black border border-[#222] rounded-lg p-3 font-mono text-[11px] text-neutral-300 h-44 overflow-y-auto space-y-1\">\r\n            <div class=\"text-neutral-500 italic\">[Dashboard] Connecting to server console...</div>\r\n          </div>\r\n\r\n          <!-- Quick command sender -->\r\n          <form onsubmit=\"handleQuickCommand(event)\" class=\"mt-3 flex gap-2\">\r\n            <input type=\"text\" id=\"dashCommandInput\" placeholder=\"Enter console command (e.g. /list, /save-all, /time set day)...\" class=\"flex-1 bg-black border border-[#262626] rounded-lg px-3 py-1.5 text-xs font-mono text-white focus:outline-none focus:border-white\">\r\n            <button type=\"submit\" class=\"px-4 py-1.5 bg-white hover:bg-neutral-200 text-black rounded-lg text-xs font-semibold flex items-center gap-1 transition\">\r\n              Send <i data-lucide=\"send\" class=\"w-3 h-3\"></i>\r\n            </button>\r\n          </form>\r\n        </div>\r\n      </div>\r\n    </section>\r\n\r\n    <!-- ================= TAB 2: AI COPILOT & DOCTOR ================= -->\r\n    <section id=\"view-ai\" class=\"hidden flex flex-col gap-5 flex-1\">\r\n      <div class=\"bg-[#0a0a0a] border border-[#222] rounded-xl p-6 flex flex-col flex-1\">\r\n        <!-- AI Header -->\r\n        <div class=\"flex flex-wrap items-center justify-between gap-4 pb-4 border-b border-[#222]\">\r\n          <div class=\"flex items-center gap-3\">\r\n            <div class=\"w-10 h-10 rounded-lg bg-white text-black flex items-center justify-center font-bold\">\r\n              <i data-lucide=\"bot\" class=\"w-5 h-5\"></i>\r\n            </div>\r\n            <div>\r\n              <h2 class=\"text-base font-bold text-white flex items-center gap-2\">\r\n                CraftOrbit AI Copilot\r\n                <span class=\"text-[10px] font-mono px-2 py-0.2 rounded bg-neutral-900 text-neutral-300 border border-[#333]\">9Router</span>\r\n              </h2>\r\n              <p class=\"text-xs text-neutral-400\">Autonomous Server Assistant for Cisco's Fantasy Medieval CARPG 1.19.2</p>\r\n            </div>\r\n          </div>\r\n\r\n          <div class=\"flex items-center gap-2\">\r\n            <button onclick=\"runQuickDiagnosis()\" class=\"px-3 py-1.5 rounded-lg bg-white hover:bg-neutral-200 text-black text-xs font-semibold flex items-center gap-1.5 transition\">\r\n              <i data-lucide=\"stethoscope\" class=\"w-3.5 h-3.5\"></i> Diagnose Logs & Crashes\r\n            </button>\r\n            <button onclick=\"clearAiChat()\" class=\"px-3 py-1.5 rounded-lg bg-[#141414] hover:bg-[#202020] text-neutral-300 border border-[#333] text-xs transition\">\r\n              Clear Chat\r\n            </button>\r\n          </div>\r\n        </div>\r\n\r\n        <!-- Quick Prompt Chips -->\r\n        <div class=\"flex flex-wrap items-center gap-2 py-3 border-b border-[#1c1c1c] text-xs\">\r\n          <span class=\"text-neutral-500 text-[11px]\">Quick Prompts:</span>\r\n          <button onclick=\"sendAiPreset('Diagnose any errors, lag warnings or mod conflicts in recent server logs.')\" class=\"px-2.5 py-1 rounded-full bg-[#111] hover:bg-[#222] border border-[#2a2a2a] hover:border-white text-neutral-300 text-[11px] transition\">\r\n            Diagnose recent logs\r\n          </button>\r\n          <button onclick=\"sendAiPreset('What are the best Forge JVM arguments and settings to run CARPG 1.19.2 with 6GB RAM smoothly?')\" class=\"px-2.5 py-1 rounded-full bg-[#111] hover:bg-[#222] border border-[#2a2a2a] hover:border-white text-neutral-300 text-[11px] transition\">\r\n            Optimize for 6GB RAM\r\n          </button>\r\n          <button onclick=\"sendAiPreset('Give me the exact console commands to clear entities, check tps, and optimize performance.')\" class=\"px-2.5 py-1 rounded-full bg-[#111] hover:bg-[#222] border border-[#2a2a2a] hover:border-white text-neutral-300 text-[11px] transition\">\r\n            Clear lag & TPS commands\r\n          </button>\r\n          <button onclick=\"sendAiPreset('How do I safely delete region files to reset chunks or shrink the world size?')\" class=\"px-2.5 py-1 rounded-full bg-[#111] hover:bg-[#222] border border-[#2a2a2a] hover:border-white text-neutral-300 text-[11px] transition\">\r\n            Safe world cleanup guide\r\n          </button>\r\n        </div>\r\n\r\n        <!-- AI Chat Messages Window -->\r\n        <div id=\"aiChatWindow\" class=\"flex-1 overflow-y-auto p-4 space-y-4 min-h-[400px] max-h-[580px] bg-black border border-[#222] rounded-xl mt-3\">\r\n          <div class=\"flex gap-3 items-start\">\r\n            <div class=\"w-8 h-8 rounded-lg bg-white text-black flex items-center justify-center shrink-0 mt-0.5\">\r\n              <i data-lucide=\"bot\" class=\"w-4 h-4\"></i>\r\n            </div>\r\n            <div class=\"bg-[#0e0e0e] border border-[#222] rounded-xl p-4 text-xs leading-relaxed max-w-3xl text-neutral-200 space-y-2\">\r\n              <p class=\"font-semibold text-white\">CraftOrbit AI Copilot Active</p>\r\n              <p>Connected to 9Router. Ready to assist with CARPG Forge 1.19.2, mod issues, performance tuning, and console commands.</p>\r\n            </div>\r\n          </div>\r\n        </div>\r\n\r\n        <!-- AI Chat Input -->\r\n        <form onsubmit=\"handleAiSubmit(event)\" class=\"mt-4 flex gap-2\">\r\n          <input type=\"text\" id=\"aiUserInput\" placeholder=\"Ask AI Copilot...\" class=\"flex-1 bg-black border border-[#262626] rounded-xl px-4 py-2.5 text-xs text-white focus:outline-none focus:border-white\">\r\n          <button type=\"submit\" id=\"btnAiSend\" class=\"px-5 py-2.5 bg-white hover:bg-neutral-200 text-black font-semibold rounded-xl text-xs flex items-center gap-1.5 transition\">\r\n            Send <i data-lucide=\"send\" class=\"w-3.5 h-3.5\"></i>\r\n          </button>\r\n        </form>\r\n      </div>\r\n    </section>\r\n\r\n    <!-- ================= TAB 3: MOD MANAGER ================= -->\r\n    <section id=\"view-mods\" class=\"hidden flex flex-col gap-5\">\r\n      <div class=\"bg-[#0a0a0a] border border-[#222] rounded-xl p-6\">\r\n        <!-- Subtabs: Installed Mods vs Modrinth App Store -->\r\n        <div class=\"flex items-center gap-2 border-b border-[#222] pb-3 mb-4\">\r\n          <button id=\"subtab-installed\" onclick=\"switchModSubtab('installed')\" class=\"px-3 py-1.5 rounded-lg text-xs font-semibold bg-white text-black transition flex items-center gap-1.5\">\r\n            <i data-lucide=\"folder\" class=\"w-3.5 h-3.5\"></i> Installed Mods / Plugins (<span id=\"modSubtabCount\">0</span>)\r\n          </button>\r\n          <button id=\"subtab-store\" onclick=\"switchModSubtab('store')\" class=\"px-3 py-1.5 rounded-lg text-xs font-semibold bg-[#141414] hover:bg-[#202020] text-neutral-300 border border-[#333] transition flex items-center gap-1.5\">\r\n            <i data-lucide=\"store\" class=\"w-3.5 h-3.5\"></i> Modrinth App Store (1-Click Install)\r\n          </button>\r\n        </div>\r\n\r\n        <!-- VIEW 1: INSTALLED MODS -->\r\n        <div id=\"modSubviewInstalled\">\r\n          <div class=\"flex flex-col md:flex-row md:items-center justify-between gap-4 pb-4 border-b border-[#222]\">\r\n            <div>\r\n              <h2 class=\"text-base font-bold text-white flex items-center gap-2\">\r\n                <i data-lucide=\"puzzle\" class=\"w-5 h-5 text-white\"></i> Local Mods & Plugins\r\n              </h2>\r\n              <p class=\"text-xs text-neutral-400 mt-0.5\">Toggle mods on or off without deleting jar files</p>\r\n            </div>\r\n            <div class=\"flex flex-wrap items-center gap-2\">\r\n              <input type=\"file\" id=\"modFileInput\" accept=\".jar\" class=\"hidden\" onchange=\"handleModFileSelect(event)\">\r\n              <button onclick=\"document.getElementById('modFileInput').click()\" class=\"px-3 py-1.5 rounded-lg bg-[#141414] hover:bg-[#202020] text-neutral-200 border border-[#333] font-medium text-xs flex items-center gap-1.5 transition\">\r\n                <i data-lucide=\"upload\" class=\"w-3.5 h-3.5\"></i> Add .jar\r\n              </button>\r\n              <button onclick=\"openImportModpackModal()\" class=\"px-3 py-1.5 rounded-lg bg-white hover:bg-neutral-200 text-black font-semibold text-xs flex items-center gap-1.5 transition\">\r\n                <i data-lucide=\"archive\" class=\"w-3.5 h-3.5\"></i> Import Modpack (.zip)\r\n              </button>\r\n              <div class=\"relative\">\r\n                <i data-lucide=\"search\" class=\"w-3.5 h-3.5 absolute left-3 top-2.5 text-neutral-500\"></i>\r\n                <input type=\"text\" id=\"modSearchInput\" oninput=\"filterModsList()\" placeholder=\"Filter installed mods...\" class=\"bg-black border border-[#262626] rounded-lg pl-8 pr-3 py-1.5 text-xs text-white focus:outline-none focus:border-white w-48\">\r\n              </div>\r\n              <button onclick=\"loadModsList()\" class=\"p-1.5 rounded-lg bg-[#141414] hover:bg-[#202020] text-neutral-300 border border-[#333] text-xs transition\" title=\"Refresh list\">\r\n                <i data-lucide=\"refresh-cw\" class=\"w-3.5 h-3.5\"></i>\r\n              </button>\r\n            </div>\r\n          </div>\r\n\r\n          <!-- Mods Metric Pills -->\r\n          <div class=\"grid grid-cols-2 sm:grid-cols-4 gap-3 my-4 text-xs font-mono\">\r\n            <div class=\"bg-black border border-[#222] rounded-lg p-3 text-center\">\r\n              <span class=\"text-neutral-400 block text-[11px]\">Total Mods</span>\r\n              <strong class=\"text-lg text-white\" id=\"modStatTotal\">--</strong>\r\n            </div>\r\n            <div class=\"bg-black border border-[#222] rounded-lg p-3 text-center\">\r\n              <span class=\"text-neutral-400 block text-[11px]\">Enabled</span>\r\n              <strong class=\"text-lg text-white\" id=\"modStatEnabled\">--</strong>\r\n            </div>\r\n            <div class=\"bg-black border border-[#222] rounded-lg p-3 text-center\">\r\n              <span class=\"text-neutral-400 block text-[11px]\">Disabled</span>\r\n              <strong class=\"text-lg text-neutral-500\" id=\"modStatDisabled\">0</strong>\r\n            </div>\r\n            <div class=\"bg-black border border-[#222] rounded-lg p-3 text-center\">\r\n              <span class=\"text-neutral-400 block text-[11px]\">Folder Size</span>\r\n              <strong class=\"text-lg text-neutral-300\" id=\"modStatSize\">-- MB</strong>\r\n            </div>\r\n          </div>\r\n\r\n          <!-- Mods Table -->\r\n          <div class=\"overflow-x-auto max-h-[550px]\">\r\n            <table class=\"w-full text-left text-xs\">\r\n              <thead class=\"bg-black text-neutral-400 uppercase font-semibold border-b border-[#222] sticky top-0 z-10\">\r\n                <tr>\r\n                  <th class=\"py-2.5 px-4\">Status</th>\r\n                  <th class=\"py-2.5 px-4\">Mod Name</th>\r\n                  <th class=\"py-2.5 px-4\">File Size</th>\r\n                  <th class=\"py-2.5 px-4 text-right\">Action</th>\r\n                </tr>\r\n              </thead>\r\n              <tbody id=\"modsTableBody\" class=\"divide-y divide-[#1e1e1e] text-neutral-300\">\r\n                <tr>\r\n                  <td colspan=\"4\" class=\"py-6 text-center text-neutral-500\">Loading mods list...</td>\r\n                </tr>\r\n              </tbody>\r\n            </table>\r\n          </div>\r\n        </div>\r\n\r\n        <!-- VIEW 2: MODRINTH APP STORE -->\r\n        <div id=\"modSubviewStore\" class=\"hidden space-y-4\">\r\n          <div class=\"flex flex-col md:flex-row md:items-center justify-between gap-3 pb-3 border-b border-[#222]\">\r\n            <div>\r\n              <h3 class=\"text-sm font-bold text-white flex items-center gap-1.5\">\r\n                <i data-lucide=\"download-cloud\" class=\"w-4 h-4\"></i> Browse & Install from Modrinth\r\n              </h3>\r\n              <p class=\"text-xs text-neutral-400\">Discover mods & modpacks (Forge, Fabric, NeoForge) matching this server's version.</p>\r\n            </div>\r\n            <form onsubmit=\"searchModrinthStore(event)\" class=\"flex gap-2\">\r\n              <select id=\"modStoreCatalogType\" onchange=\"searchModrinthStore()\" class=\"bg-black border border-[#262626] rounded-lg px-2.5 py-1.5 text-xs text-white focus:outline-none focus:border-white\">\r\n                <option value=\"mod\">Mods (.jar)</option>\r\n                <option value=\"modpack\">Modpacks</option>\r\n              </select>\r\n              <input type=\"text\" id=\"modStoreQuery\" placeholder=\"Search (e.g. JEI, Cobblemon, Better MC)...\" class=\"bg-black border border-[#262626] rounded-lg px-3 py-1.5 text-xs text-white focus:outline-none focus:border-white w-56\">\r\n              <button type=\"submit\" class=\"px-3.5 py-1.5 bg-white hover:bg-neutral-200 text-black font-semibold rounded-lg text-xs transition\">\r\n                Search\r\n              </button>\r\n            </form>\r\n          </div>\r\n\r\n          <!-- Quick Search Tag Chips -->\r\n          <div class=\"flex flex-wrap items-center gap-1.5 text-xs\">\r\n            <span class=\"text-neutral-500 text-[11px]\">Popular:</span>\r\n            <button onclick=\"quickStoreSearch('cobblemon', 'modpack')\" class=\"px-2.5 py-1 rounded bg-[#111] hover:bg-white hover:text-black border border-[#333] text-neutral-300 text-[11px] transition\">⚔️ Cobblemon Pack</button>\r\n            <button onclick=\"quickStoreSearch('better mc', 'modpack')\" class=\"px-2.5 py-1 rounded bg-[#111] hover:bg-white hover:text-black border border-[#333] text-neutral-300 text-[11px] transition\">🏰 Better MC Pack</button>\r\n            <button onclick=\"quickStoreSearch('performance', 'mod')\" class=\"px-2.5 py-1 rounded bg-[#111] hover:bg-[#222] border border-[#333] text-neutral-300 text-[11px] transition\">⚡ Optimization</button>\r\n            <button onclick=\"quickStoreSearch('jei', 'mod')\" class=\"px-2.5 py-1 rounded bg-[#111] hover:bg-[#222] border border-[#333] text-neutral-300 text-[11px] transition\">📖 JEI Recipes</button>\r\n            <button onclick=\"quickStoreSearch('voice chat', 'mod')\" class=\"px-2.5 py-1 rounded bg-[#111] hover:bg-[#222] border border-[#333] text-neutral-300 text-[11px] transition\">🎙️ Voice Chat</button>\r\n            <button onclick=\"quickStoreSearch('waystones', 'mod')\" class=\"px-2.5 py-1 rounded bg-[#111] hover:bg-[#222] border border-[#333] text-neutral-300 text-[11px] transition\">🗿 Waystones</button>\r\n          </div>\r\n\r\n          <!-- Store Grid -->\r\n          <div id=\"modStoreResultsGrid\" class=\"grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-3 pt-2\">\r\n            <div class=\"col-span-full py-12 text-center text-neutral-500 text-xs font-mono\">\r\n              Loading popular mods from Modrinth...\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </section>\r\n\r\n    <!-- ================= TAB 4: PLAYERS & ROSTER ================= -->\r\n    <section id=\"view-players\" class=\"hidden flex flex-col gap-5\">\r\n      <div class=\"bg-[#0a0a0a] border border-[#222] rounded-xl p-6\">\r\n        <div class=\"flex flex-col md:flex-row md:items-center justify-between gap-4 pb-4 border-b border-[#222]\">\r\n          <div>\r\n            <h2 class=\"text-base font-bold text-white flex items-center gap-2\">\r\n              <i data-lucide=\"users\" class=\"w-5 h-5 text-white\"></i> Player Roster\r\n            </h2>\r\n            <p class=\"text-xs text-neutral-400 mt-0.5\">Manage operator permissions, whitelist, and players</p>\r\n          </div>\r\n          <div class=\"flex items-center gap-2\">\r\n            <form onsubmit=\"handleQuickPlayerAction(event)\" class=\"flex gap-2\">\r\n              <input type=\"text\" id=\"quickPlayerNameInput\" placeholder=\"Player name...\" class=\"bg-black border border-[#262626] rounded-lg px-3 py-1.5 text-xs text-white focus:outline-none focus:border-white\">\r\n              <select id=\"quickPlayerActionSelect\" class=\"bg-black border border-[#262626] rounded-lg px-2.5 py-1.5 text-xs text-white focus:outline-none focus:border-white\">\r\n                <option value=\"op\">Grant OP</option>\r\n                <option value=\"whitelist_add\">Add Whitelist</option>\r\n                <option value=\"kick\">Kick</option>\r\n                <option value=\"ban\">Ban</option>\r\n              </select>\r\n              <button type=\"submit\" class=\"px-3.5 py-1.5 bg-white hover:bg-neutral-200 text-black font-semibold rounded-lg text-xs transition\">\r\n                Apply\r\n              </button>\r\n            </form>\r\n            <button onclick=\"loadPlayersData()\" class=\"p-2 rounded-lg bg-[#141414] hover:bg-[#202020] text-neutral-300 border border-[#333] transition\" title=\"Refresh Players\">\r\n              <i data-lucide=\"refresh-cw\" class=\"w-3.5 h-3.5\"></i>\r\n            </button>\r\n          </div>\r\n        </div>\r\n\r\n        <!-- In-Game Broadcast Announcement Bar -->\r\n        <div class=\"my-3 p-3 bg-black border border-[#222] rounded-xl flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3\">\r\n          <div class=\"flex items-center gap-2 text-white text-xs font-semibold shrink-0\">\r\n            <i data-lucide=\"megaphone\" class=\"w-4 h-4\"></i>\r\n            <span>Broadcast In-Game:</span>\r\n          </div>\r\n          <form onsubmit=\"broadcastServerAnnouncement(event)\" class=\"flex-1 flex gap-2\">\r\n            <input type=\"text\" id=\"serverBroadcastInput\" placeholder=\"Send an announcement message to all in-game players...\" class=\"flex-1 bg-[#111] border border-[#262626] rounded-lg px-3 py-1.5 text-xs text-white focus:outline-none focus:border-white\">\r\n            <button type=\"submit\" class=\"px-4 py-1.5 bg-white hover:bg-neutral-200 text-black font-semibold rounded-lg text-xs transition flex items-center gap-1\">\r\n              <i data-lucide=\"send\" class=\"w-3 h-3\"></i> Send\r\n            </button>\r\n          </form>\r\n        </div>\r\n\r\n        <!-- Player Cards Grid -->\r\n        <div id=\"playerCardsGrid\" class=\"grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4 mt-3\">\r\n          <div class=\"col-span-full py-8 text-center text-neutral-500 text-xs\">Loading players...</div>\r\n        </div>\r\n      </div>\r\n    </section>\r\n\r\n    <!-- ================= TAB 5: STORAGE & USAGE ================= -->\r\n    <section id=\"view-storage\" class=\"hidden flex flex-col gap-6\">\r\n      <!-- Storage Banner -->\r\n      <div class=\"bg-[#0a0a0a] border border-[#222] rounded-xl p-6\">\r\n        <div class=\"flex flex-col md:flex-row md:items-center justify-between gap-4 mb-4\">\r\n          <div>\r\n            <h2 class=\"text-base font-bold text-white flex items-center gap-2\">\r\n              <i data-lucide=\"hard-drive\" class=\"w-5 h-5 text-white\"></i> Storage & Disk Analyzer\r\n            </h2>\r\n            <p class=\"text-xs text-neutral-400 mt-1\">Directory: <code class=\"text-neutral-200 font-mono\">server world</code></p>\r\n          </div>\r\n          <div class=\"flex items-center gap-2\">\r\n            <button onclick=\"loadStorageOverview()\" class=\"px-3 py-1.5 rounded-lg bg-[#141414] hover:bg-[#202020] text-neutral-300 border border-[#333] text-xs flex items-center gap-1.5 transition\">\r\n              <i data-lucide=\"refresh-cw\" class=\"w-3.5 h-3.5\"></i> Refresh Analysis\r\n            </button>\r\n            <button onclick=\"triggerWorldBackup()\" class=\"px-3.5 py-1.5 rounded-lg bg-white hover:bg-neutral-200 text-black font-semibold text-xs flex items-center gap-1.5 transition\">\r\n              <i data-lucide=\"archive\" class=\"w-3.5 h-3.5\"></i> Backup World (.zip)\r\n            </button>\r\n          </div>\r\n        </div>\r\n\r\n        <!-- Proportional Storage Bar - Monochrome -->\r\n        <div class=\"space-y-2\">\r\n          <div class=\"flex justify-between text-xs text-neutral-300 font-mono\">\r\n            <span>Total Server Size: <strong id=\"totalServerSize\" class=\"text-white\">Calculating...</strong></span>\r\n            <span>Host Drive (C:) Available: <strong id=\"driveFreeLabel\" class=\"text-white\">-- GB</strong></span>\r\n          </div>\r\n          <div class=\"w-full bg-[#181818] rounded-lg h-3.5 p-0.5 flex overflow-hidden gap-0.5\" id=\"storageMultiBar\">\r\n            <div id=\"barWorld\" class=\"bg-white h-full rounded-sm transition-all\" style=\"width: 50%\" title=\"World\"></div>\r\n            <div id=\"barMods\" class=\"bg-neutral-300 h-full rounded-sm transition-all\" style=\"width: 15%\" title=\"Mods\"></div>\r\n            <div id=\"barArchives\" class=\"bg-neutral-500 h-full rounded-sm transition-all\" style=\"width: 15%\" title=\"Zip Archives\"></div>\r\n            <div id=\"barLibraries\" class=\"bg-neutral-600 h-full rounded-sm transition-all\" style=\"width: 5%\" title=\"Libraries\"></div>\r\n            <div id=\"barLogs\" class=\"bg-neutral-700 h-full rounded-sm transition-all\" style=\"width: 5%\" title=\"Logs\"></div>\r\n            <div id=\"barOther\" class=\"bg-neutral-800 h-full rounded-sm transition-all\" style=\"width: 10%\" title=\"Configs/Cache\"></div>\r\n          </div>\r\n          <!-- Legend -->\r\n          <div class=\"flex flex-wrap items-center gap-4 text-[11px] text-neutral-400 pt-1\">\r\n            <div class=\"flex items-center gap-1.5\"><span class=\"w-2.5 h-2.5 rounded-sm bg-white\"></span> World Data</div>\r\n            <div class=\"flex items-center gap-1.5\"><span class=\"w-2.5 h-2.5 rounded-sm bg-neutral-300\"></span> Mods</div>\r\n            <div class=\"flex items-center gap-1.5\"><span class=\"w-2.5 h-2.5 rounded-sm bg-neutral-500\"></span> Setup Archives (.zip)</div>\r\n            <div class=\"flex items-center gap-1.5\"><span class=\"w-2.5 h-2.5 rounded-sm bg-neutral-600\"></span> Libraries</div>\r\n            <div class=\"flex items-center gap-1.5\"><span class=\"w-2.5 h-2.5 rounded-sm bg-neutral-700\"></span> Logs</div>\r\n            <div class=\"flex items-center gap-1.5\"><span class=\"w-2.5 h-2.5 rounded-sm bg-neutral-800\"></span> Configs & Caches</div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- Cleanup Tools Cards -->\r\n      <div class=\"grid grid-cols-1 md:grid-cols-3 gap-5\">\r\n        <!-- Cleaner 1: Old Logs -->\r\n        <div class=\"bg-[#0a0a0a] border border-[#222] rounded-xl p-5 flex flex-col justify-between\">\r\n          <div>\r\n            <div class=\"w-8 h-8 rounded-lg bg-[#141414] border border-[#333] text-white flex items-center justify-center mb-3\">\r\n              <i data-lucide=\"file-text\" class=\"w-4 h-4\"></i>\r\n            </div>\r\n            <h3 class=\"font-semibold text-white text-sm\">Purge Old Logs</h3>\r\n            <p class=\"text-xs text-neutral-400 mt-1\">Delete accumulated compressed <code class=\"text-white\">.log.gz</code> files while keeping <code class=\"text-neutral-300\">latest.log</code> intact.</p>\r\n            <div class=\"my-3 py-2 px-3 bg-black rounded-lg border border-[#222] text-xs font-mono flex justify-between\">\r\n              <span class=\"text-neutral-400\">Reclaimable:</span>\r\n              <span class=\"text-white font-bold\" id=\"logCleanSize\">0 MB</span>\r\n            </div>\r\n          </div>\r\n          <button onclick=\"cleanOldLogs()\" class=\"w-full py-2 rounded-lg bg-white hover:bg-neutral-200 text-black text-xs font-semibold flex items-center justify-center gap-1.5 transition\">\r\n            <i data-lucide=\"trash-2\" class=\"w-3.5 h-3.5\"></i> Clear Old Logs Now\r\n          </button>\r\n        </div>\r\n\r\n        <!-- Cleaner 2: CARPG Zip Archive -->\r\n        <div class=\"bg-[#0a0a0a] border border-[#222] rounded-xl p-5 flex flex-col justify-between\">\r\n          <div>\r\n            <div class=\"w-8 h-8 rounded-lg bg-[#141414] border border-[#333] text-white flex items-center justify-center mb-3\">\r\n              <i data-lucide=\"archive\" class=\"w-4 h-4\"></i>\r\n            </div>\r\n            <h3 class=\"font-semibold text-white text-sm\">Setup Archive Reclaimer</h3>\r\n            <p class=\"text-xs text-neutral-400 mt-1\">Delete original server pack ZIP (<code class=\"text-neutral-300\">CARPG Ultimate V7b Serv.zip</code>) to reclaim space.</p>\r\n            <div class=\"my-3 py-2 px-3 bg-black rounded-lg border border-[#222] text-xs font-mono flex justify-between\">\r\n              <span class=\"text-neutral-400\">Archive Size:</span>\r\n              <span class=\"text-white font-bold\" id=\"archiveZipSize\">0 MB</span>\r\n            </div>\r\n          </div>\r\n          <button id=\"btnDeleteZip\" onclick=\"deleteSetupArchive()\" class=\"w-full py-2 rounded-lg bg-[#141414] hover:bg-[#202020] text-white border border-[#333] text-xs font-medium flex items-center justify-center gap-1.5 transition\">\r\n            <i data-lucide=\"trash\" class=\"w-3.5 h-3.5\"></i> Delete Setup Zip\r\n          </button>\r\n        </div>\r\n\r\n        <!-- Cleaner 3: Cache & Temp Files -->\r\n        <div class=\"bg-[#0a0a0a] border border-[#222] rounded-xl p-5 flex flex-col justify-between\">\r\n          <div>\r\n            <div class=\"w-8 h-8 rounded-lg bg-[#141414] border border-[#333] text-white flex items-center justify-center mb-3\">\r\n              <i data-lucide=\"sparkles\" class=\"w-4 h-4\"></i>\r\n            </div>\r\n            <h3 class=\"font-semibold text-white text-sm\">Cache & Crash Reports</h3>\r\n            <p class=\"text-xs text-neutral-400 mt-1\">Clear old Mixin outputs (<code class=\"text-neutral-300\">.mixin.out</code>) and outdated crash reports.</p>\r\n            <div class=\"my-3 py-2 px-3 bg-black rounded-lg border border-[#222] text-xs font-mono flex justify-between\">\r\n              <span class=\"text-neutral-400\">Temporary data:</span>\r\n              <span class=\"text-white font-bold\" id=\"cacheSizeText\">Ready</span>\r\n            </div>\r\n          </div>\r\n          <button onclick=\"cleanCache()\" class=\"w-full py-2 rounded-lg bg-[#141414] hover:bg-[#202020] text-white border border-[#333] text-xs font-medium flex items-center justify-center gap-1.5 transition\">\r\n            <i data-lucide=\"refresh-cw\" class=\"w-3.5 h-3.5\"></i> Clean Cache Files\r\n          </button>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- World Dimensions Deep Dive -->\r\n      <div class=\"bg-[#0a0a0a] border border-[#222] rounded-xl p-5\">\r\n        <h3 class=\"font-semibold text-sm text-white flex items-center gap-2 mb-4\">\r\n          <i data-lucide=\"globe\" class=\"w-4 h-4 text-white\"></i> World Storage Breakdown\r\n        </h3>\r\n        <div class=\"grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-5 gap-3 text-center\">\r\n          <div class=\"bg-black p-3 rounded-xl border border-[#222]\">\r\n            <span class=\"text-neutral-400 text-xs\">Overworld</span>\r\n            <div class=\"text-lg font-bold font-mono text-white mt-1\" id=\"dimOverworld\">-- MB</div>\r\n          </div>\r\n          <div class=\"bg-black p-3 rounded-xl border border-[#222]\">\r\n            <span class=\"text-neutral-400 text-xs\">Nether</span>\r\n            <div class=\"text-lg font-bold font-mono text-white mt-1\" id=\"dimNether\">-- MB</div>\r\n          </div>\r\n          <div class=\"bg-black p-3 rounded-xl border border-[#222]\">\r\n            <span class=\"text-neutral-400 text-xs\">The End</span>\r\n            <div class=\"text-lg font-bold font-mono text-white mt-1\" id=\"dimEnd\">-- MB</div>\r\n          </div>\r\n          <div class=\"bg-black p-3 rounded-xl border border-[#222]\">\r\n            <span class=\"text-neutral-400 text-xs\">Playerdata</span>\r\n            <div class=\"text-lg font-bold font-mono text-white mt-1\" id=\"dimPlayerdata\">-- MB</div>\r\n          </div>\r\n          <div class=\"bg-black p-3 rounded-xl border border-[#222]\">\r\n            <span class=\"text-neutral-400 text-xs\">Entities</span>\r\n            <div class=\"text-lg font-bold font-mono text-white mt-1\" id=\"dimEntities\">-- MB</div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- Backup Center -->\r\n      <div class=\"bg-[#0a0a0a] border border-[#222] rounded-xl p-5\">\r\n        <div class=\"flex items-center justify-between mb-4\">\r\n          <div>\r\n            <h3 class=\"font-semibold text-sm text-white flex items-center gap-2\">\r\n              <i data-lucide=\"archive\" class=\"w-4 h-4 text-white\"></i> World Backup Manager\r\n            </h3>\r\n            <p class=\"text-xs text-neutral-400 mt-0.5\">Manage and restore zip archives</p>\r\n          </div>\r\n          <button onclick=\"triggerWorldBackup()\" class=\"px-3.5 py-1.5 rounded-lg bg-white hover:bg-neutral-200 text-black text-xs font-semibold flex items-center gap-1.5 transition\">\r\n            <i data-lucide=\"plus\" class=\"w-3.5 h-3.5\"></i> New Backup\r\n          </button>\r\n        </div>\r\n\r\n        <div class=\"overflow-x-auto\">\r\n          <table class=\"w-full text-left text-xs\">\r\n            <thead class=\"bg-black text-neutral-400 uppercase font-semibold border-b border-[#222]\">\r\n              <tr>\r\n                <th class=\"py-2.5 px-4\">Backup Name</th>\r\n                <th class=\"py-2.5 px-4\">File Size</th>\r\n                <th class=\"py-2.5 px-4\">Date Created</th>\r\n                <th class=\"py-2.5 px-4 text-right\">Actions</th>\r\n              </tr>\r\n            </thead>\r\n            <tbody id=\"backupTableBody\" class=\"divide-y divide-[#1e1e1e] text-neutral-300\">\r\n              <tr>\r\n                <td colspan=\"4\" class=\"py-6 text-center text-neutral-500\">Loading backups...</td>\r\n              </tr>\r\n            </tbody>\r\n          </table>\r\n        </div>\r\n      </div>\r\n    </section>\r\n\r\n    <!-- ================= TAB: GLOBAL TUNNEL (playit.gg) ================= -->\r\n    <section id=\"view-playit\" class=\"hidden flex flex-col gap-6\">\r\n      <div class=\"bg-[#0a0a0a] border border-[#222] rounded-xl p-6 shadow-xl\">\r\n        <div class=\"flex flex-col md:flex-row md:items-center justify-between gap-4 pb-4 border-b border-[#222]\">\r\n          <div class=\"flex items-center gap-3\">\r\n            <div class=\"w-10 h-10 rounded-lg bg-white text-black flex items-center justify-center font-bold\">\r\n              <i data-lucide=\"globe\" class=\"w-5 h-5\"></i>\r\n            </div>\r\n            <div>\r\n              <h2 class=\"text-base font-bold text-white flex items-center gap-2\">\r\n                playit.gg Global Hosting Tunnel\r\n                <span id=\"playitStatusPill\" class=\"text-[10px] font-mono px-2 py-0.2 rounded bg-neutral-900 border border-[#333] text-neutral-400\">OFFLINE</span>\r\n              </h2>\r\n              <p class=\"text-xs text-neutral-400 mt-0.5\">\r\n                <span>Configure global addresses for profile:</span>\r\n                <strong id=\"playitActiveProfileName\" class=\"text-white font-mono px-1.5 py-0.2 rounded bg-[#181818] border border-[#333]\">--</strong>\r\n              </p>\r\n            </div>\r\n          </div>\r\n          <div class=\"flex items-center gap-2\">\r\n            <button id=\"btnPlayitToggle\" onclick=\"togglePlayitTunnel()\" class=\"px-4 py-1.5 rounded-lg bg-white hover:bg-neutral-200 text-black font-semibold text-xs flex items-center gap-1.5 transition\">\r\n              <i data-lucide=\"play\" class=\"w-3.5 h-3.5 fill-current\"></i> Start Tunnel\r\n            </button>\r\n            <button onclick=\"resetPlayitAgent()\" class=\"px-3 py-1.5 rounded-lg bg-[#141414] hover:bg-[#202020] text-neutral-300 border border-[#333] text-xs flex items-center gap-1.5 transition\" title=\"Link new account\">\r\n              <i data-lucide=\"link-2\" class=\"w-3.5 h-3.5\"></i> Re-Link Account\r\n            </button>\r\n          </div>\r\n        </div>\r\n\r\n        <!-- Claiming Banner (shown if user needs to link/sign up first) -->\r\n        <div id=\"playitClaimBanner\" class=\"hidden my-4 p-5 rounded-xl bg-[#141414] border border-white/40 flex flex-col md:flex-row items-start md:items-center justify-between gap-4\">\r\n          <div>\r\n            <div class=\"flex items-center gap-2 text-white font-bold text-sm\">\r\n              <span class=\"w-2 h-2 rounded-full bg-white animate-ping\"></span>\r\n              <span>Account Setup Required</span>\r\n            </div>\r\n            <p class=\"text-xs text-neutral-300 mt-1\">Visit your unique playit.gg claim link to sign in or create an account, then click \"Add Tunnel\" for Minecraft.</p>\r\n          </div>\r\n          <a id=\"btnPlayitClaimLink\" href=\"#\" target=\"_blank\" class=\"px-5 py-2.5 rounded-xl bg-white text-black font-bold text-xs flex items-center gap-2 transition hover:bg-neutral-200 shadow-xl\">\r\n            Open Claim Link <i data-lucide=\"external-link\" class=\"w-3.5 h-3.5\"></i>\r\n          </a>\r\n        </div>\r\n\r\n        <!-- Dual Tunnel Configuration Cards: Java & Bedrock -->\r\n        <div class=\"grid grid-cols-1 lg:grid-cols-3 gap-4 my-4 text-xs font-mono\">\r\n          <!-- Left: 2 Tunnel Inputs (Java & Bedrock) -->\r\n          <div class=\"lg:col-span-2 space-y-3\">\r\n            <!-- Tunnel 1: Java (PC) -->\r\n            <div class=\"bg-black border border-[#222] rounded-xl p-4 flex flex-col justify-between\">\r\n              <div class=\"flex items-center justify-between mb-1.5\">\r\n                <span class=\"text-white font-bold flex items-center gap-1.5 text-xs\">\r\n                  <span>🖥️ Java Edition Tunnel (PC)</span>\r\n                  <span class=\"text-[9px] font-mono px-1.5 py-0.2 rounded bg-[#181818] border border-[#333] text-neutral-400\">TCP</span>\r\n                </span>\r\n                <span class=\"text-[10px] text-neutral-500 font-mono\" id=\"playitJavaLocalPort\">Local Target: 127.0.0.1:25565</span>\r\n              </div>\r\n              <div class=\"flex gap-2 mt-1\">\r\n                <input type=\"text\" id=\"playitJavaAddressInput\" placeholder=\"e.g. your-subdomain.gl.joinmc.link\" class=\"flex-1 bg-[#111] border border-[#2e2e2e] rounded-lg px-3 py-2 text-white font-mono text-xs focus:outline-none focus:border-white\">\r\n                <button onclick=\"savePlayitAddresses()\" class=\"px-3 py-2 bg-[#1a1a1a] hover:bg-[#282828] border border-[#333] text-white rounded-lg transition\">Save</button>\r\n                <button onclick=\"copySpecificAddress('java')\" class=\"px-4 py-2 bg-white hover:bg-neutral-200 text-black font-semibold rounded-lg flex items-center gap-1.5 transition\">\r\n                  <i data-lucide=\"copy\" class=\"w-3.5 h-3.5\"></i> Copy\r\n                </button>\r\n              </div>\r\n              <p class=\"text-[11px] text-neutral-500 mt-1.5\">PC / Mac / Linux players direct connect to this domain.</p>\r\n            </div>\r\n\r\n            <!-- Tunnel 2: Bedrock (Mobile / Console / Geyser) -->\r\n            <div class=\"bg-black border border-[#222] rounded-xl p-4 flex flex-col justify-between\">\r\n              <div class=\"flex items-center justify-between mb-1.5\">\r\n                <span class=\"text-white font-bold flex items-center gap-1.5 text-xs\">\r\n                  <span>📱 Bedrock Edition Tunnel (Geyser / Mobile)</span>\r\n                  <span class=\"text-[9px] font-mono px-1.5 py-0.2 rounded bg-[#181818] border border-[#333] text-neutral-400\">UDP</span>\r\n                </span>\r\n                <span class=\"text-[10px] text-neutral-500 font-mono\" id=\"playitBedrockLocalPort\">Local Target: 127.0.0.1:19132</span>\r\n              </div>\r\n              <div class=\"flex gap-2 mt-1\">\r\n                <input type=\"text\" id=\"playitBedrockAddressInput\" placeholder=\"Server IP: e.g. your-subdomain.gl.ply.gg\" class=\"flex-1 bg-[#111] border border-[#2e2e2e] rounded-lg px-3 py-2 text-white font-mono text-xs focus:outline-none focus:border-white\">\r\n                <input type=\"text\" id=\"playitBedrockPortInput\" placeholder=\"Port: 19132\" class=\"w-24 bg-[#111] border border-[#2e2e2e] rounded-lg px-2.5 py-2 text-white font-mono text-xs focus:outline-none focus:border-white\">\r\n                <button onclick=\"savePlayitAddresses()\" class=\"px-3 py-2 bg-[#1a1a1a] hover:bg-[#282828] border border-[#333] text-white rounded-lg transition\">Save</button>\r\n                <button onclick=\"copySpecificAddress('bedrock')\" class=\"px-4 py-2 bg-white hover:bg-neutral-200 text-black font-semibold rounded-lg flex items-center gap-1.5 transition\">\r\n                  <i data-lucide=\"copy\" class=\"w-3.5 h-3.5\"></i> Copy\r\n                </button>\r\n              </div>\r\n              <p class=\"text-[11px] text-neutral-500 mt-1.5\">Phone, Tablet & Console players use this Server IP & Port (with Geyser plugin).</p>\r\n            </div>\r\n          </div>\r\n\r\n          <!-- Status & Tunnels Count -->\r\n          <div class=\"bg-black border border-[#222] rounded-xl p-4 flex flex-col justify-between\">\r\n            <span class=\"text-neutral-400 text-[11px]\">Tunnel Statistics</span>\r\n            <div class=\"my-3\">\r\n              <div class=\"text-3xl font-bold text-white\" id=\"playitTunnelsCount\">--</div>\r\n              <div class=\"text-xs text-neutral-400 mt-1\" id=\"playitActiveTunnelText\">Tunnels Connected</div>\r\n            </div>\r\n            <div class=\"space-y-1.5 border-t border-[#1c1c1c] pt-2 text-[11px] text-neutral-400\">\r\n              <div class=\"flex justify-between items-center\">\r\n                <span>Agent Status:</span>\r\n                <span id=\"playitAgentHealth\" class=\"text-white font-bold\">READY</span>\r\n              </div>\r\n              <div class=\"flex justify-between items-center\">\r\n                <span>Cross-play Geyser:</span>\r\n                <span id=\"playitGeyserStatus\" class=\"text-white font-mono text-[10px]\">Checking...</span>\r\n              </div>\r\n              <div id=\"playitGeyserInstallRow\" class=\"hidden pt-1\">\r\n                <button onclick=\"installGeyserToActiveServer()\" class=\"w-full py-1.5 px-2 rounded bg-white hover:bg-neutral-200 text-black font-semibold text-[11px] flex items-center justify-center gap-1 transition\">\r\n                  <i data-lucide=\"download\" class=\"w-3 h-3\"></i> Install Geyser & Floodgate (1-Click)\r\n                </button>\r\n              </div>\r\n            </div>\r\n            <a href=\"https://playit.gg/account/tunnels\" target=\"_blank\" class=\"mt-3 block text-center py-2 rounded-lg bg-[#141414] hover:bg-[#202020] text-neutral-200 border border-[#333] text-[11px] transition\">\r\n              Manage on playit.gg dashboard &rarr;\r\n            </a>\r\n          </div>\r\n        </div>\r\n\r\n        <!-- Playit Agent Logs -->\r\n        <div class=\"mt-4\">\r\n          <div class=\"flex justify-between items-center mb-2 text-xs\">\r\n            <span class=\"text-neutral-400 font-semibold flex items-center gap-1.5\">\r\n              <i data-lucide=\"terminal\" class=\"w-3.5 h-3.5 text-white\"></i> playit.gg Agent Console\r\n            </span>\r\n            <button onclick=\"refreshPlayitStatus()\" class=\"text-neutral-500 hover:text-white flex items-center gap-1\">\r\n              <i data-lucide=\"refresh-cw\" class=\"w-3 h-3\"></i> Refresh Status\r\n            </button>\r\n          </div>\r\n          <div id=\"playitLogsScreen\" class=\"h-44 bg-black border border-[#222] rounded-lg p-3 font-mono text-[11px] text-neutral-300 overflow-y-auto space-y-1\">\r\n            <div class=\"text-neutral-500\">[playit.gg] Agent ready. Click \"Start Tunnel\" above.</div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </section>\r\n\r\n    <!-- ================= TAB 6: LIVE CONSOLE ================= -->\r\n    <section id=\"view-console\" class=\"hidden flex-1 flex flex-col gap-4\">\r\n      <div class=\"bg-[#0a0a0a] border border-[#222] rounded-xl p-4 flex flex-col flex-1\">\r\n        <!-- Terminal Header Controls -->\r\n        <div class=\"flex flex-wrap items-center justify-between gap-3 pb-3 border-b border-[#222]\">\r\n          <div class=\"flex items-center gap-2\">\r\n            <div class=\"w-2.5 h-2.5 rounded-full bg-white\"></div>\r\n            <div class=\"w-2.5 h-2.5 rounded-full bg-neutral-500\"></div>\r\n            <div class=\"w-2.5 h-2.5 rounded-full bg-neutral-800\"></div>\r\n            <span class=\"font-mono text-xs text-neutral-400 ml-2\">minecraft-console@localhost</span>\r\n          </div>\r\n\r\n          <div class=\"flex items-center gap-2\">\r\n            <input type=\"text\" id=\"consoleFilter\" oninput=\"filterConsoleLogs()\" placeholder=\"Filter logs...\" class=\"bg-black border border-[#262626] rounded px-2.5 py-1 text-xs font-mono text-white focus:outline-none focus:border-white w-36\">\r\n\r\n            <label class=\"flex items-center gap-1.5 text-xs text-neutral-400 cursor-pointer select-none\">\r\n              <input type=\"checkbox\" id=\"autoScrollCheck\" checked class=\"rounded bg-black border-[#333] text-white\"> Auto-scroll\r\n            </label>\r\n\r\n            <button onclick=\"clearConsoleView()\" class=\"px-2.5 py-1 rounded bg-[#141414] hover:bg-[#202020] text-neutral-300 border border-[#333] text-xs transition\">\r\n              Clear Screen\r\n            </button>\r\n          </div>\r\n        </div>\r\n\r\n        <!-- Terminal Output Screen -->\r\n        <div id=\"fullConsoleScreen\" class=\"flex-1 bg-black border border-[#222] rounded-lg p-4 font-mono text-xs text-neutral-200 overflow-y-auto space-y-0.5 mt-3 min-h-[450px] max-h-[600px] leading-relaxed select-text\">\r\n          <div class=\"text-neutral-500\">[Dashboard] Terminal initialized. Waiting for events...</div>\r\n        </div>\r\n\r\n        <!-- Command Quick Presets -->\r\n        <div class=\"flex flex-wrap items-center gap-1.5 mt-3 pt-2 border-t border-[#1c1c1c] text-xs\">\r\n          <span class=\"text-neutral-500 mr-1 text-[11px]\">Quick:</span>\r\n          <button onclick=\"sendQuickCommand('list')\" class=\"px-2 py-0.5 rounded bg-[#141414] hover:bg-[#222] border border-[#262626] text-neutral-300 font-mono text-[11px]\">/list</button>\r\n          <button onclick=\"sendQuickCommand('save-all flush')\" class=\"px-2 py-0.5 rounded bg-[#141414] hover:bg-[#222] border border-[#262626] text-neutral-300 font-mono text-[11px]\">/save-all</button>\r\n          <button onclick=\"sendQuickCommand('forge tps')\" class=\"px-2 py-0.5 rounded bg-[#141414] hover:bg-[#222] border border-[#262626] text-neutral-300 font-mono text-[11px]\">/forge tps</button>\r\n          <button onclick=\"sendQuickCommand('weather clear')\" class=\"px-2 py-0.5 rounded bg-[#141414] hover:bg-[#222] border border-[#262626] text-neutral-300 font-mono text-[11px]\">/weather clear</button>\r\n          <button onclick=\"sendQuickCommand('time set day')\" class=\"px-2 py-0.5 rounded bg-[#141414] hover:bg-[#222] border border-[#262626] text-neutral-300 font-mono text-[11px]\">/time set day</button>\r\n        </div>\r\n\r\n        <!-- Terminal Command Input Bar -->\r\n        <form onsubmit=\"handleFullConsoleCommand(event)\" class=\"mt-2 flex gap-2\">\r\n          <div class=\"relative flex-1\">\r\n            <span class=\"absolute left-3 top-2.5 font-mono text-neutral-500 text-xs\">&gt;</span>\r\n            <input type=\"text\" id=\"fullConsoleInput\" placeholder=\"Type command...\" class=\"w-full bg-black border border-[#262626] rounded-lg pl-7 pr-3 py-2 text-xs font-mono text-white focus:outline-none focus:border-white\">\r\n          </div>\r\n          <button type=\"submit\" class=\"px-4 py-2 bg-white hover:bg-neutral-200 text-black rounded-lg text-xs font-semibold flex items-center gap-1.5 transition\">\r\n            Execute <i data-lucide=\"corner-down-left\" class=\"w-3.5 h-3.5\"></i>\r\n          </button>\r\n        </form>\r\n      </div>\r\n    </section>\r\n\r\n    <!-- ================= TAB 7: FILE EXPLORER ================= -->\r\n    <section id=\"view-files\" class=\"hidden flex flex-col gap-4\">\r\n      <div class=\"bg-[#0a0a0a] border border-[#222] rounded-xl p-5\">\r\n        <!-- Breadcrumb & Actions -->\r\n        <div class=\"flex flex-wrap items-center justify-between gap-3 pb-3 border-b border-[#222]\">\r\n          <div class=\"flex items-center gap-2 text-xs font-mono\">\r\n            <button onclick=\"loadFiles('')\" class=\"text-white hover:underline flex items-center gap-1\">\r\n              <i data-lucide=\"home\" class=\"w-3.5 h-3.5\"></i> server world\r\n            </button>\r\n            <span id=\"filePathBreadcrumbs\" class=\"text-neutral-500\">/</span>\r\n          </div>\r\n          <button onclick=\"refreshCurrentFolder()\" class=\"px-3 py-1 rounded bg-[#141414] hover:bg-[#222] text-neutral-300 border border-[#333] text-xs flex items-center gap-1.5 transition\">\r\n            <i data-lucide=\"refresh-cw\" class=\"w-3.5 h-3.5\"></i> Refresh\r\n          </button>\r\n        </div>\r\n\r\n        <!-- File Table -->\r\n        <div class=\"overflow-x-auto mt-3\">\r\n          <table class=\"w-full text-left text-xs\">\r\n            <thead class=\"bg-black text-neutral-400 uppercase font-semibold border-b border-[#222]\">\r\n              <tr>\r\n                <th class=\"py-2.5 px-4\">Name</th>\r\n                <th class=\"py-2.5 px-4\">Size</th>\r\n                <th class=\"py-2.5 px-4\">Modified</th>\r\n                <th class=\"py-2.5 px-4 text-right\">Action</th>\r\n              </tr>\r\n            </thead>\r\n            <tbody id=\"fileExplorerBody\" class=\"divide-y divide-[#1e1e1e] text-neutral-300\">\r\n              <tr>\r\n                <td colspan=\"4\" class=\"py-6 text-center text-neutral-500\">Loading files...</td>\r\n              </tr>\r\n            </tbody>\r\n          </table>\r\n        </div>\r\n      </div>\r\n    </section>\r\n\r\n    <!-- ================= TAB 8: SETTINGS ================= -->\r\n    <section id=\"view-settings\" class=\"hidden flex flex-col gap-6\">\r\n      <div class=\"grid grid-cols-1 lg:grid-cols-2 gap-6\">\r\n        <!-- Launch & RAM Settings -->\r\n        <div class=\"bg-[#0a0a0a] border border-[#222] rounded-xl p-5\">\r\n          <h3 class=\"font-bold text-sm text-white flex items-center gap-2 mb-4\">\r\n            <i data-lucide=\"zap\" class=\"w-4 h-4 text-white\"></i> Memory & Startup Configuration\r\n          </h3>\r\n          <form onsubmit=\"saveLaunchSettings(event)\" class=\"space-y-4 text-xs\">\r\n            <div>\r\n              <label class=\"block text-neutral-400 mb-1\">Max Allocated RAM (-Xmx)</label>\r\n              <div class=\"grid grid-cols-4 gap-2 mb-2\">\r\n                <button type=\"button\" onclick=\"setRam('4G')\" class=\"ram-preset px-2 py-1.5 rounded bg-[#141414] hover:bg-[#222] border border-[#262626] text-center font-mono text-neutral-300\">4 GB</button>\r\n                <button type=\"button\" onclick=\"setRam('6G')\" class=\"ram-preset px-2 py-1.5 rounded bg-white text-black font-semibold text-center font-mono\">6 GB</button>\r\n                <button type=\"button\" onclick=\"setRam('8G')\" class=\"ram-preset px-2 py-1.5 rounded bg-[#141414] hover:bg-[#222] border border-[#262626] text-center font-mono text-neutral-300\">8 GB</button>\r\n                <button type=\"button\" onclick=\"setRam('10G')\" class=\"ram-preset px-2 py-1.5 rounded bg-[#141414] hover:bg-[#222] border border-[#262626] text-center font-mono text-neutral-300\">10 GB</button>\r\n              </div>\r\n              <input type=\"text\" id=\"cfgMaxRam\" class=\"w-full bg-black border border-[#262626] rounded-lg px-3 py-2 font-mono text-white focus:outline-none focus:border-white\" placeholder=\"e.g. 6G\">\r\n              <p class=\"text-[11px] text-neutral-500 mt-1\">Configured for Cisco CARPG (6GB).</p>\r\n            </div>\r\n\r\n            <div>\r\n              <label class=\"block text-neutral-400 mb-1\">Min Allocated RAM (-Xms)</label>\r\n              <input type=\"text\" id=\"cfgMinRam\" class=\"w-full bg-black border border-[#262626] rounded-lg px-3 py-2 font-mono text-white focus:outline-none focus:border-white\" placeholder=\"e.g. 4G\">\r\n            </div>\r\n\r\n            <div>\r\n              <label class=\"block text-neutral-400 mb-1\">Java Runtime Path</label>\r\n              <input type=\"text\" id=\"cfgJavaPath\" class=\"w-full bg-black border border-[#262626] rounded-lg px-3 py-2 font-mono text-white text-[11px] focus:outline-none focus:border-white\">\r\n            </div>\r\n\r\n            <div class=\"flex items-center gap-2 pt-2\">\r\n              <input type=\"checkbox\" id=\"cfgAutoRestart\" class=\"rounded bg-black border-[#333] text-white\">\r\n              <label for=\"cfgAutoRestart\" class=\"text-neutral-300\">Auto-restart server if it crashes</label>\r\n            </div>\r\n\r\n            <button type=\"submit\" class=\"w-full py-2.5 bg-white hover:bg-neutral-200 text-black font-semibold rounded-lg transition\">\r\n              Save Launch Configuration\r\n            </button>\r\n          </form>\r\n        </div>\r\n\r\n        <!-- Visual Server Properties Editor -->\r\n        <div class=\"bg-[#0a0a0a] border border-[#222] rounded-xl p-5\">\r\n          <h3 class=\"font-bold text-sm text-white flex items-center gap-2 mb-4\">\r\n            <i data-lucide=\"sliders\" class=\"w-4 h-4 text-white\"></i> Server Properties\r\n          </h3>\r\n          <form onsubmit=\"savePropertiesSettings(event)\" class=\"space-y-3.5 text-xs\">\r\n            <div class=\"grid grid-cols-2 gap-3\">\r\n              <div>\r\n                <label class=\"block text-neutral-400 mb-1\">Server Port</label>\r\n                <input type=\"number\" id=\"propPort\" class=\"w-full bg-black border border-[#262626] rounded-lg px-3 py-1.5 font-mono text-white focus:outline-none focus:border-white\">\r\n              </div>\r\n              <div>\r\n                <label class=\"block text-neutral-400 mb-1\">Max Players</label>\r\n                <input type=\"number\" id=\"propMaxPlayers\" class=\"w-full bg-black border border-[#262626] rounded-lg px-3 py-1.5 font-mono text-white focus:outline-none focus:border-white\">\r\n              </div>\r\n            </div>\r\n\r\n            <div>\r\n              <label class=\"block text-neutral-400 mb-1\">Server MOTD</label>\r\n              <input type=\"text\" id=\"propMotd\" class=\"w-full bg-black border border-[#262626] rounded-lg px-3 py-1.5 font-mono text-white focus:outline-none focus:border-white\">\r\n            </div>\r\n\r\n            <div class=\"grid grid-cols-2 gap-3\">\r\n              <div>\r\n                <label class=\"block text-neutral-400 mb-1\">Gamemode</label>\r\n                <select id=\"propGamemode\" class=\"w-full bg-black border border-[#262626] rounded-lg px-3 py-1.5 text-white focus:outline-none focus:border-white\">\r\n                  <option value=\"survival\">Survival</option>\r\n                  <option value=\"creative\">Creative</option>\r\n                  <option value=\"adventure\">Adventure</option>\r\n                  <option value=\"spectator\">Spectator</option>\r\n                </select>\r\n              </div>\r\n              <div>\r\n                <label class=\"block text-neutral-400 mb-1\">Difficulty</label>\r\n                <select id=\"propDifficulty\" class=\"w-full bg-black border border-[#262626] rounded-lg px-3 py-1.5 text-white focus:outline-none focus:border-white\">\r\n                  <option value=\"peaceful\">Peaceful</option>\r\n                  <option value=\"easy\">Easy</option>\r\n                  <option value=\"normal\">Normal</option>\r\n                  <option value=\"hard\">Hard</option>\r\n                </select>\r\n              </div>\r\n            </div>\r\n\r\n            <div class=\"grid grid-cols-2 gap-3\">\r\n              <div>\r\n                <label class=\"block text-neutral-400 mb-1\">Online Mode</label>\r\n                <select id=\"propOnlineMode\" class=\"w-full bg-black border border-[#262626] rounded-lg px-3 py-1.5 text-white focus:outline-none focus:border-white\">\r\n                  <option value=\"false\">False (Offline/Cracked)</option>\r\n                  <option value=\"true\">True (Mojang verification)</option>\r\n                </select>\r\n              </div>\r\n              <div>\r\n                <label class=\"block text-neutral-400 mb-1\">PvP Enabled</label>\r\n                <select id=\"propPvp\" class=\"w-full bg-black border border-[#262626] rounded-lg px-3 py-1.5 text-white focus:outline-none focus:border-white\">\r\n                  <option value=\"true\">Enabled</option>\r\n                  <option value=\"false\">Disabled</option>\r\n                </select>\r\n              </div>\r\n            </div>\r\n\r\n            <button type=\"submit\" class=\"w-full py-2.5 bg-neutral-900 hover:bg-neutral-800 text-white border border-[#333] rounded-lg font-medium transition\">\r\n              Save Server Properties\r\n            </button>\r\n          </form>\r\n        </div>\r\n\r\n        <!-- Dashboard Navigation Layout Preference Card -->\r\n        <div class=\"bg-[#0a0a0a] border border-[#222] rounded-xl p-5 lg:col-span-2\">\r\n          <h3 class=\"font-bold text-sm text-white flex items-center gap-2 mb-2\">\r\n            <i data-lucide=\"layout\" class=\"w-4 h-4 text-white\"></i> <span data-i18n=\"layout_pref_title\">Dashboard Layout &amp; Navigation Preference</span>\r\n          </h3>\r\n          <p class=\"text-xs text-neutral-400 mb-4\" data-i18n=\"layout_pref_desc\">Choose your preferred dashboard navigation style. Your preference is automatically remembered across sessions.</p>\r\n          \r\n          <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-4\">\r\n            <!-- Left Sidebar Card -->\r\n            <div onclick=\"setLayoutMode('sidebar')\" id=\"layoutCardSidebar\" class=\"p-4 rounded-xl bg-[#0f181f] border border-emerald-500 hover:border-emerald-400 cursor-pointer transition flex items-start gap-3.5 group\">\r\n              <div class=\"p-2.5 rounded-lg bg-emerald-500/10 text-emerald-400 mt-0.5 border border-emerald-500/20\">\r\n                <i data-lucide=\"columns-2\" class=\"w-5 h-5\"></i>\r\n              </div>\r\n              <div class=\"flex-1 space-y-1\">\r\n                <div class=\"flex items-center justify-between\">\r\n                  <span class=\"font-bold text-sm text-white\" data-i18n=\"layout_sidebar_title\">Left Sidebar (Argonara / Pterodactyl)</span>\r\n                  <span id=\"layoutCheckSidebar\" class=\"text-emerald-400 text-xs font-mono font-bold\">ACTIVE</span>\r\n                </div>\r\n                <p class=\"text-xs text-neutral-400 leading-relaxed\" data-i18n=\"layout_sidebar_desc\">Full-height vertical sidebar on the left with General, Management, and Palette categories. Gives your workspace maximum horizontal breathing room.</p>\r\n              </div>\r\n            </div>\r\n\r\n            <!-- Top Horizontal Bar Card -->\r\n            <div onclick=\"setLayoutMode('topbar')\" id=\"layoutCardTopbar\" class=\"p-4 rounded-xl bg-black border border-[#2e2e2e] hover:border-white cursor-pointer transition flex items-start gap-3.5 group\">\r\n              <div class=\"p-2.5 rounded-lg bg-white/10 text-white mt-0.5\">\r\n                <i data-lucide=\"layout-grid\" class=\"w-5 h-5\"></i>\r\n              </div>\r\n              <div class=\"flex-1 space-y-1\">\r\n                <div class=\"flex items-center justify-between\">\r\n                  <span class=\"font-bold text-sm text-white\" data-i18n=\"layout_topbar_title\">Top Horizontal Tabs</span>\r\n                  <span id=\"layoutCheckTopbar\" class=\"text-neutral-500 text-xs font-mono\">SELECT</span>\r\n                </div>\r\n                <p class=\"text-xs text-neutral-400 leading-relaxed\" data-i18n=\"layout_topbar_desc\">Compact horizontal tab strip across the top header. Best for compact displays or classic minimalist view.</p>\r\n              </div>\r\n            </div>\r\n          </div>\r\n        </div>\r\n\r\n        <!-- Language & Localization Card -->\r\n        <div class=\"bg-[#0a0a0a] border border-[#222] rounded-xl p-5 lg:col-span-2\">\r\n          <h3 class=\"font-bold text-sm text-white flex items-center gap-2 mb-2\">\r\n            <i data-lucide=\"languages\" class=\"w-4 h-4 text-white\"></i> <span data-i18n=\"lang_pref_title\">Language &amp; Localization</span>\r\n          </h3>\r\n          <p class=\"text-xs text-neutral-400 mb-4\" data-i18n=\"lang_pref_desc\">Select your preferred interface display language. Changes take effect instantly across all panels.</p>\r\n          \r\n          <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-4\">\r\n            <!-- English (US) Card -->\r\n            <div onclick=\"setLanguage('en')\" id=\"langCardEn\" class=\"p-4 rounded-xl bg-[#0f181f] border border-emerald-500 hover:border-emerald-400 cursor-pointer transition flex items-start gap-3.5 group\">\r\n              <div class=\"p-2.5 rounded-lg bg-emerald-500/10 text-emerald-400 mt-0.5 border border-emerald-500/20 text-lg\">\r\n                🇺🇸\r\n              </div>\r\n              <div class=\"flex-1 space-y-1\">\r\n                <div class=\"flex items-center justify-between\">\r\n                  <span class=\"font-bold text-sm text-white\">English (Native US)</span>\r\n                  <span id=\"langSettingCheck-en\" class=\"text-emerald-400 text-xs font-mono font-bold\">ACTIVE</span>\r\n                </div>\r\n                <p class=\"text-xs text-neutral-400 leading-relaxed\">Default native English terminology for hosting, telemetry, networking, and modding.</p>\r\n              </div>\r\n            </div>\r\n\r\n            <!-- Bahasa Indonesia Card -->\r\n            <div onclick=\"setLanguage('id')\" id=\"langCardId\" class=\"p-4 rounded-xl bg-black border border-[#2e2e2e] hover:border-white cursor-pointer transition flex items-start gap-3.5 group\">\r\n              <div class=\"p-2.5 rounded-lg bg-white/10 text-white mt-0.5 text-lg\">\r\n                🇮🇩\r\n              </div>\r\n              <div class=\"flex-1 space-y-1\">\r\n                <div class=\"flex items-center justify-between\">\r\n                  <span class=\"font-bold text-sm text-white\">Bahasa Indonesia</span>\r\n                  <span id=\"langSettingCheck-id\" class=\"text-neutral-500 text-xs font-mono\">SELECT</span>\r\n                </div>\r\n                <p class=\"text-xs text-neutral-400 leading-relaxed\">Terjemahan antarmuka Bahasa Indonesia untuk navigasi, pengaturan, dan pesan ajakan mabar.</p>\r\n              </div>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </section>\r\n  </main>\r\n    </div><!-- End #mainViewWrapper -->\r\n  </div><!-- End #appShell -->\r\n\r\n  <!-- In-Browser File Editor Modal -->\r\n  <div id=\"fileEditorModal\" class=\"fixed inset-0 z-50 bg-black/80 backdrop-blur-sm hidden flex items-center justify-center p-4\">\r\n    <div class=\"bg-[#0a0a0a] border border-[#333] rounded-xl w-full max-w-4xl max-h-[90vh] flex flex-col shadow-2xl overflow-hidden\">\r\n      <div class=\"px-5 py-3.5 border-b border-[#222] flex items-center justify-between\">\r\n        <div class=\"flex items-center gap-2\">\r\n          <i data-lucide=\"file-code\" class=\"w-4 h-4 text-white\"></i>\r\n          <span id=\"editorFileName\" class=\"font-mono text-xs font-semibold text-white\">filename.txt</span>\r\n        </div>\r\n        <button onclick=\"closeFileEditor()\" class=\"text-neutral-400 hover:text-white transition\">\r\n          <i data-lucide=\"x\" class=\"w-5 h-5\"></i>\r\n        </button>\r\n      </div>\r\n      <div class=\"p-4 flex-1 flex flex-col\">\r\n        <textarea id=\"editorContent\" class=\"flex-1 w-full bg-black border border-[#222] rounded-lg p-3 font-mono text-xs text-white focus:outline-none focus:border-white resize-none min-h-[400px]\"></textarea>\r\n      </div>\r\n      <div class=\"px-5 py-3 border-t border-[#222] flex justify-end gap-2 bg-[#080808]\">\r\n        <button onclick=\"closeFileEditor()\" class=\"px-4 py-2 rounded-lg bg-[#141414] hover:bg-[#202020] text-neutral-300 border border-[#333] text-xs transition\">\r\n          Cancel\r\n        </button>\r\n        <button onclick=\"saveFileEditor()\" class=\"px-4 py-2 rounded-lg bg-white hover:bg-neutral-200 text-black text-xs font-semibold flex items-center gap-1.5 transition\">\r\n          <i data-lucide=\"save\" class=\"w-3.5 h-3.5\"></i> Save Changes\r\n        </button>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- Add Server Instance Modal -->\r\n  <div id=\"addInstanceModal\" class=\"fixed inset-0 z-50 bg-black/80 backdrop-blur-sm hidden flex items-center justify-center p-4\">\r\n    <div class=\"bg-[#0a0a0a] border border-[#333] rounded-xl w-full max-w-lg shadow-2xl overflow-hidden\">\r\n      <div class=\"px-5 py-3.5 border-b border-[#222] flex items-center justify-between\">\r\n        <div class=\"flex items-center gap-2\">\r\n          <i data-lucide=\"folder-plus\" class=\"w-4 h-4 text-white\"></i>\r\n          <span class=\"font-bold text-sm text-white\">Add Minecraft Server Folder</span>\r\n        </div>\r\n        <button onclick=\"closeAddInstanceModal()\" class=\"text-neutral-400 hover:text-white transition\">\r\n          <i data-lucide=\"x\" class=\"w-5 h-5\"></i>\r\n        </button>\r\n      </div>\r\n\r\n      <form onsubmit=\"submitAddInstance(event)\" class=\"p-5 space-y-4 text-xs\">\r\n        <div>\r\n          <label class=\"block text-neutral-400 mb-1\">Server Folder Path (Absolute on PC)</label>\r\n          <div class=\"flex gap-2\">\r\n            <input type=\"text\" id=\"addInstPath\" required placeholder=\"e.g. C:\\Users\\msi_9\\Desktop\\bedrock server\" class=\"flex-1 bg-black border border-[#262626] rounded-lg px-3 py-2 text-white font-mono focus:outline-none focus:border-white\">\r\n            <button type=\"button\" onclick=\"detectInstPath()\" class=\"px-3 py-2 bg-[#161616] hover:bg-[#222] border border-[#333] text-neutral-200 rounded-lg font-medium transition\">\r\n              Scan\r\n            </button>\r\n          </div>\r\n          <p id=\"detectResultText\" class=\"text-[11px] text-neutral-500 mt-1\">Enter folder path to auto-detect engine type (Forge, Bedrock, Paper, Fabric, Vanilla).</p>\r\n        </div>\r\n\r\n        <div>\r\n          <label class=\"block text-neutral-400 mb-1\">Server Display Name</label>\r\n          <input type=\"text\" id=\"addInstName\" placeholder=\"e.g. Survival World\" class=\"w-full bg-black border border-[#262626] rounded-lg px-3 py-2 text-white focus:outline-none focus:border-white\">\r\n        </div>\r\n\r\n        <div class=\"grid grid-cols-2 gap-3\">\r\n          <div>\r\n            <label class=\"block text-neutral-400 mb-1\">Server Type</label>\r\n            <select id=\"addInstType\" class=\"w-full bg-black border border-[#262626] rounded-lg px-3 py-2 text-white focus:outline-none focus:border-white\">\r\n              <option value=\"forge\">Minecraft Forge</option>\r\n              <option value=\"fabric\">Fabric</option>\r\n              <option value=\"neoforge\">NeoForge</option>\r\n              <option value=\"paper\">PaperMC / Purpur / Spigot</option>\r\n              <option value=\"vanilla\">Vanilla</option>\r\n              <option value=\"bedrock\">Bedrock Dedicated Server</option>\r\n              <option value=\"custom\">Custom</option>\r\n            </select>\r\n          </div>\r\n          <div>\r\n            <label class=\"block text-neutral-400 mb-1\">Max RAM (-Xmx)</label>\r\n            <input type=\"text\" id=\"addInstMaxRam\" value=\"4G\" class=\"w-full bg-black border border-[#262626] rounded-lg px-3 py-2 text-white font-mono focus:outline-none focus:border-white\">\r\n          </div>\r\n        </div>\r\n\r\n        <div class=\"pt-3 border-t border-[#222] flex justify-end gap-2\">\r\n          <button type=\"button\" onclick=\"closeAddInstanceModal()\" class=\"px-4 py-2 rounded-lg bg-[#141414] hover:bg-[#202020] text-neutral-300 border border-[#333] text-xs transition\">\r\n            Cancel\r\n          </button>\r\n          <button type=\"submit\" class=\"px-4 py-2 rounded-lg bg-white hover:bg-neutral-200 text-black text-xs font-semibold transition\">\r\n            Add & Register Server\r\n          </button>\r\n        </div>\r\n      </form>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- Auto-Host from World (Egg System) Modal -->\r\n  <div id=\"autoEggModal\" class=\"fixed inset-0 z-50 bg-black/85 backdrop-blur-sm hidden flex items-center justify-center p-4\">\r\n    <div class=\"bg-[#0a0a0a] border border-[#333] rounded-2xl w-full max-w-2xl max-h-[92vh] flex flex-col shadow-2xl overflow-hidden\">\r\n      <!-- Header -->\r\n      <div class=\"px-6 py-4 border-b border-[#222] flex items-center justify-between\">\r\n        <div class=\"flex items-center gap-2.5\">\r\n          <div class=\"w-8 h-8 rounded-lg bg-white text-black flex items-center justify-center font-bold\">\r\n            <i data-lucide=\"sparkles\" class=\"w-4 h-4\"></i>\r\n          </div>\r\n          <div>\r\n            <h3 class=\"font-bold text-sm text-white\">Auto-Host & World Deployer</h3>\r\n            <p class=\"text-[11px] text-neutral-400\">Host an existing singleplayer world or generate a clean world for any specific Minecraft version.</p>\r\n          </div>\r\n        </div>\r\n        <button onclick=\"closeAutoEggModal()\" class=\"text-neutral-400 hover:text-white transition\">\r\n          <i data-lucide=\"x\" class=\"w-5 h-5\"></i>\r\n        </button>\r\n      </div>\r\n\r\n      <!-- Mode Switcher: Existing vs Fresh World -->\r\n      <div class=\"px-6 pt-3 pb-0 border-b border-[#1c1c1c] flex items-center gap-2 bg-[#080808]\">\r\n        <button type=\"button\" id=\"tabAutoEggExisting\" onclick=\"switchAutoEggMode('existing')\" class=\"px-3.5 py-2 text-xs font-semibold rounded-t-lg bg-white text-black transition flex items-center gap-1.5\">\r\n          <i data-lucide=\"folder\" class=\"w-3.5 h-3.5\"></i> Singleplayer / Saved World\r\n        </button>\r\n        <button type=\"button\" id=\"tabAutoEggFresh\" onclick=\"switchAutoEggMode('fresh')\" class=\"px-3.5 py-2 text-xs font-semibold rounded-t-lg bg-transparent text-neutral-400 hover:text-white transition flex items-center gap-1.5\">\r\n          <i data-lucide=\"plus-circle\" class=\"w-3.5 h-3.5\"></i> Fresh World (Pick Version)\r\n        </button>\r\n      </div>\r\n\r\n      <div class=\"p-6 overflow-y-auto space-y-5 text-xs flex-1\">\r\n        <!-- MODE 1: EXISTING WORLD SELECTOR -->\r\n        <div id=\"autoEggExistingContainer\" class=\"space-y-4\">\r\n          <div class=\"space-y-2\">\r\n            <div class=\"flex justify-between items-center\">\r\n              <label class=\"block text-white font-semibold\">1. Select World Folder</label>\r\n              <button type=\"button\" onclick=\"refreshScannedWorlds()\" class=\"text-[11px] text-neutral-400 hover:text-white flex items-center gap-1 transition\">\r\n                <i data-lucide=\"refresh-cw\" class=\"w-3 h-3\"></i> Rescan PC Worlds\r\n              </button>\r\n            </div>\r\n            \r\n            <!-- Dropdown of scanned singleplayer worlds -->\r\n            <div>\r\n              <select id=\"autoEggScannedSelect\" onchange=\"onSelectScannedWorld(event)\" class=\"w-full bg-black border border-[#262626] rounded-lg px-3 py-2 text-white focus:outline-none focus:border-white\">\r\n                <option value=\"\">-- Choose from your Singleplayer / Modpack Worlds --</option>\r\n              </select>\r\n            </div>\r\n\r\n            <!-- Or manual path -->\r\n            <div class=\"flex gap-2 items-center pt-1\">\r\n              <input type=\"text\" id=\"autoEggWorldPath\" oninput=\"onManualWorldPathInput()\" placeholder=\"Or paste absolute world folder path (e.g. C:\\Users\\...\\saves\\world)\" class=\"flex-1 bg-black border border-[#262626] rounded-lg px-3 py-2 text-white font-mono focus:outline-none focus:border-white\">\r\n              <button type=\"button\" onclick=\"inspectSelectedWorld()\" class=\"px-4 py-2 bg-white hover:bg-neutral-200 text-black font-semibold rounded-lg transition\">\r\n                Inspect\r\n              </button>\r\n            </div>\r\n          </div>\r\n\r\n          <!-- Section 2: Detected World Specs -->\r\n          <div id=\"autoEggSpecsCard\" class=\"hidden p-4 rounded-xl bg-black border border-[#262626] space-y-2.5\">\r\n            <div class=\"flex items-center justify-between\">\r\n              <span class=\"text-neutral-400\">Detected World Name:</span>\r\n              <strong id=\"autoEggDetectedName\" class=\"text-white font-mono text-xs\">--</strong>\r\n            </div>\r\n            <div class=\"flex items-center justify-between\">\r\n              <span class=\"text-neutral-400\">Minecraft Version:</span>\r\n              <span id=\"autoEggDetectedVersion\" class=\"px-2 py-0.5 rounded bg-white text-black font-mono font-bold text-xs\">--</span>\r\n            </div>\r\n            <div class=\"flex items-center justify-between\">\r\n              <span class=\"text-neutral-400\">World Origin / Modded:</span>\r\n              <span id=\"autoEggDetectedType\" class=\"text-neutral-300 font-mono text-xs\">--</span>\r\n            </div>\r\n          </div>\r\n        </div>\r\n\r\n        <!-- MODE 2: FRESH WORLD & SPECIFIC VERSION PICKER -->\r\n        <div id=\"autoEggFreshContainer\" class=\"hidden space-y-4\">\r\n          <div class=\"space-y-2\">\r\n            <label class=\"block text-white font-semibold\">1. Choose Specific Minecraft Version</label>\r\n            <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-3\">\r\n              <div>\r\n                <span class=\"text-[11px] text-neutral-400 block mb-1\">Version Preset</span>\r\n                <select id=\"autoEggFreshVersionSelect\" onchange=\"onFreshVersionSelect(event)\" class=\"w-full bg-black border border-[#262626] rounded-lg px-3 py-2 text-white focus:outline-none focus:border-white\">\r\n                  <option value=\"26.2\">26.2 / 1.26 (Latest 2026 - Java 25)</option>\r\n                  <option value=\"26.1.2\">26.1.2 / 1.26 (Minecraft 26.1 - Java 25)</option>\r\n                  <option value=\"1.21.4\">1.21.4 (Latest 1.21 - Java 21)</option>\r\n                  <option value=\"1.21.1\">1.21.1 (Stable 1.21 - Java 21)</option>\r\n                  <option value=\"1.20.4\">1.20.4 (Recommended Paper - Java 17)</option>\r\n                  <option value=\"1.20.1\">1.20.1 (Best for Mods - Java 17)</option>\r\n                  <option value=\"1.19.4\">1.19.4 (Java 17)</option>\r\n                  <option value=\"1.19.2\">1.19.2 (Classic RPG Modpack - Java 17)</option>\r\n                  <option value=\"1.18.2\">1.18.2 (Java 17)</option>\r\n                  <option value=\"1.16.5\">1.16.5 (Legacy Java 8)</option>\r\n                  <option value=\"1.12.2\">1.12.2 (Classic Forge - Java 8)</option>\r\n                  <option value=\"custom\">Custom / Other Version...</option>\r\n                </select>\r\n              </div>\r\n              <div id=\"autoEggCustomVersionBox\" class=\"hidden\">\r\n                <span class=\"text-[11px] text-neutral-400 block mb-1\">Enter Custom Version String</span>\r\n                <input type=\"text\" id=\"autoEggCustomVersionInput\" placeholder=\"e.g. 1.20.2, 1.17.1, 26.2\" class=\"w-full bg-black border border-[#262626] rounded-lg px-3 py-2 text-white font-mono focus:outline-none focus:border-white\">\r\n              </div>\r\n            </div>\r\n          </div>\r\n\r\n          <!-- World Seed input -->\r\n          <div>\r\n            <label class=\"block text-neutral-400 mb-1\">World Generation Seed (Optional)</label>\r\n            <input type=\"text\" id=\"autoEggFreshSeed\" placeholder=\"Leave blank for random world seed\" class=\"w-full bg-black border border-[#262626] rounded-lg px-3 py-1.5 text-white font-mono focus:outline-none focus:border-white\">\r\n          </div>\r\n        </div>\r\n\r\n        <!-- Section: Select Egg Template -->\r\n        <div id=\"autoEggEngineSection\" class=\"hidden space-y-2.5\">\r\n          <label class=\"block text-white font-semibold\">2. Choose Server Engine (Egg)</label>\r\n          <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-2.5\" id=\"autoEggOptionsContainer\">\r\n            <!-- Rendered dynamically (Paper, Purpur, Vanilla, Fabric) -->\r\n          </div>\r\n        </div>\r\n\r\n        <!-- Section: Hosting Configurations -->\r\n        <div id=\"autoEggConfigSection\" class=\"hidden space-y-3 pt-2\">\r\n          <div class=\"grid grid-cols-1 sm:grid-cols-3 gap-3\">\r\n            <div>\r\n              <label class=\"block text-neutral-400 mb-1\">Server Name</label>\r\n              <input type=\"text\" id=\"autoEggServerName\" class=\"w-full bg-black border border-[#262626] rounded-lg px-3 py-1.5 text-white focus:outline-none focus:border-white\">\r\n            </div>\r\n            <div>\r\n              <label class=\"block text-neutral-400 mb-1\">Server Port</label>\r\n              <input type=\"number\" id=\"autoEggPort\" value=\"25565\" class=\"w-full bg-black border border-[#262626] rounded-lg px-3 py-1.5 font-mono text-white focus:outline-none focus:border-white\">\r\n            </div>\r\n            <div>\r\n              <label class=\"block text-neutral-400 mb-1\">Max RAM (-Xmx)</label>\r\n              <input type=\"text\" id=\"autoEggMaxRam\" value=\"4G\" class=\"w-full bg-black border border-[#262626] rounded-lg px-3 py-1.5 font-mono text-white focus:outline-none focus:border-white\">\r\n            </div>\r\n          </div>\r\n\r\n          <!-- Geyser Cross-Play Auto-Install Option (Only shown for Paper Egg) -->\r\n          <div id=\"autoEggGeyserToggleContainer\" class=\"hidden items-center gap-2 p-2.5 rounded-lg bg-black border border-[#222]\">\r\n            <input type=\"checkbox\" id=\"autoEggEnableGeyser\" checked class=\"rounded bg-[#141414] border-[#333] text-white\">\r\n            <label for=\"autoEggEnableGeyser\" class=\"text-white text-xs font-medium cursor-pointer flex-1\">\r\n              <span>Auto-install Geyser & Floodgate plugins</span>\r\n              <span class=\"text-neutral-400 block text-[11px]\">Enables Mobile (Android/iOS) and Bedrock friends to join this Paper/Spigot server via port 19132.</span>\r\n            </label>\r\n          </div>\r\n        </div>\r\n\r\n        <!-- Progress status display with percentage bar -->\r\n        <div id=\"autoEggProgressBox\" class=\"hidden p-3.5 rounded-xl bg-black border border-[#333] text-xs font-mono text-neutral-300 space-y-2\">\r\n          <div class=\"flex items-center justify-between\">\r\n            <span class=\"flex items-center gap-2\">\r\n              <span class=\"w-2 h-2 rounded-full bg-white animate-ping\"></span>\r\n              <span id=\"autoEggProgressText\">Preparing dependencies...</span>\r\n            </span>\r\n            <span id=\"autoEggProgressPercent\" class=\"font-bold text-white\">0%</span>\r\n          </div>\r\n          <div class=\"w-full bg-[#181818] rounded-full h-1.5 overflow-hidden\">\r\n            <div id=\"autoEggProgressBar\" class=\"bg-white h-full rounded-full transition-all duration-300\" style=\"width: 0%\"></div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- Modal Footer -->\r\n      <div class=\"px-6 py-4 border-t border-[#222] flex justify-end gap-2 bg-[#080808]\">\r\n        <button type=\"button\" onclick=\"closeAutoEggModal()\" class=\"px-4 py-2 rounded-lg bg-[#141414] hover:bg-[#202020] text-neutral-300 border border-[#333] text-xs transition\">\r\n          Cancel\r\n        </button>\r\n        <button type=\"button\" id=\"btnAutoEggDeploy\" onclick=\"deployAutoEggServer()\" disabled class=\"px-5 py-2 rounded-lg bg-white hover:bg-neutral-200 text-black text-xs font-semibold flex items-center gap-1.5 transition opacity-40 cursor-not-allowed\">\r\n          <i data-lucide=\"zap\" class=\"w-3.5 h-3.5 fill-current\"></i> Deploy & Host World\r\n        </button>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- Import Modpack (.zip) Modal -->\r\n  <div id=\"importModpackModal\" class=\"fixed inset-0 z-50 bg-black/85 backdrop-blur-sm hidden flex items-center justify-center p-4\">\r\n    <div class=\"bg-[#0a0a0a] border border-[#333] rounded-2xl w-full max-w-lg shadow-2xl overflow-hidden\">\r\n      <div class=\"px-6 py-4 border-b border-[#222] flex items-center justify-between\">\r\n        <div class=\"flex items-center gap-2.5\">\r\n          <div class=\"w-8 h-8 rounded-lg bg-white text-black flex items-center justify-center font-bold\">\r\n            <i data-lucide=\"archive\" class=\"w-4 h-4\"></i>\r\n          </div>\r\n          <div>\r\n            <h3 class=\"font-bold text-sm text-white\">Import Modpack Archive (.zip)</h3>\r\n            <p class=\"text-[11px] text-neutral-400\">Unpacks mods, configs, scripts, and default configs directly into the active server.</p>\r\n          </div>\r\n        </div>\r\n        <button onclick=\"closeImportModpackModal()\" class=\"text-neutral-400 hover:text-white transition\">\r\n          <i data-lucide=\"x\" class=\"w-5 h-5\"></i>\r\n        </button>\r\n      </div>\r\n\r\n      <form onsubmit=\"submitImportModpack(event)\" class=\"p-6 space-y-4 text-xs\">\r\n        <div>\r\n          <label class=\"block text-white font-semibold mb-1\">Modpack ZIP Path (on your PC)</label>\r\n          <input type=\"text\" id=\"importModpackPath\" required placeholder=\"e.g. C:\\Downloads\\MyModpack-Server.zip\" class=\"w-full bg-black border border-[#262626] rounded-lg px-3 py-2 text-white font-mono focus:outline-none focus:border-white\">\r\n          <p class=\"text-[11px] text-neutral-500 mt-1\">Paste the full path to any CurseForge or Modrinth server-pack ZIP.</p>\r\n        </div>\r\n\r\n        <div id=\"importModpackProgress\" class=\"hidden p-3 rounded-lg bg-black border border-[#333] text-xs font-mono text-neutral-300 flex items-center gap-2\">\r\n          <span class=\"w-2 h-2 rounded-full bg-white animate-ping\"></span>\r\n          <span>Unpacking modpack files into server folder...</span>\r\n        </div>\r\n\r\n        <div class=\"pt-3 border-t border-[#222] flex justify-end gap-2\">\r\n          <button type=\"button\" onclick=\"closeImportModpackModal()\" class=\"px-4 py-2 rounded-lg bg-[#141414] hover:bg-[#202020] text-neutral-300 border border-[#333] text-xs transition\">\r\n            Cancel\r\n          </button>\r\n          <button type=\"submit\" id=\"btnSubmitImportModpack\" class=\"px-5 py-2 rounded-lg bg-white hover:bg-neutral-200 text-black text-xs font-semibold flex items-center gap-1.5 transition\">\r\n            <i data-lucide=\"folder-down\" class=\"w-3.5 h-3.5\"></i> Extract & Install Modpack\r\n          </button>\r\n        </div>\r\n      </form>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- Command Palette Modal (Ctrl+K) -->\r\n  <div id=\"commandPaletteModal\" class=\"fixed inset-0 z-50 bg-black/85 backdrop-blur-sm hidden flex items-start justify-center pt-20 p-4\" onclick=\"onCommandPaletteBackdrop(event)\">\r\n    <div class=\"bg-[#0a0a0a] border border-[#333] rounded-2xl w-full max-w-xl shadow-2xl overflow-hidden\" onclick=\"event.stopPropagation()\">\r\n      <div class=\"p-3.5 border-b border-[#222] flex items-center gap-3\">\r\n        <i data-lucide=\"search\" class=\"w-4 h-4 text-neutral-400\"></i>\r\n        <input type=\"text\" id=\"paletteSearchInput\" oninput=\"filterPaletteItems()\" placeholder=\"Type a command or action (e.g. start, stop, day, backup, host)...\" class=\"flex-1 bg-transparent text-white text-xs font-mono focus:outline-none placeholder:text-neutral-500\">\r\n        <kbd class=\"px-1.5 py-0.5 rounded bg-[#181818] border border-[#333] text-[10px] text-neutral-400 font-mono\">ESC</kbd>\r\n      </div>\r\n      <div id=\"paletteItemsList\" class=\"max-h-80 overflow-y-auto p-2 space-y-1 text-xs\">\r\n        <!-- Loaded dynamically -->\r\n      </div>\r\n      <div class=\"px-3.5 py-2 bg-[#06080d] border-t border-[#1c2230] text-[11px] text-neutral-400 flex flex-wrap items-center justify-between gap-2 font-mono\">\r\n        <span class=\"flex items-center gap-1\"><kbd class=\"px-1.5 py-0.5 rounded bg-[#10141e] border border-[#263042] text-neutral-300\">Ctrl+B</kbd> Layout</span>\r\n        <span class=\"flex items-center gap-1\"><kbd class=\"px-1.5 py-0.5 rounded bg-[#10141e] border border-[#263042] text-neutral-300\">Alt+1-9</kbd> Tabs</span>\r\n        <span class=\"flex items-center gap-1\"><kbd class=\"px-1.5 py-0.5 rounded bg-[#10141e] border border-[#263042] text-neutral-300\">/</kbd> Terminal</span>\r\n        <span class=\"flex items-center gap-1\"><kbd class=\"px-1.5 py-0.5 rounded bg-[#10141e] border border-[#263042] text-neutral-300\">Esc</kbd> Close</span>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <script src=\"app.js?v=2.1\"></script>\r\n  <script>\r\n    lucide.createIcons();\r\n  </script>\r\n</body>\r\n</html>\r\n",
  "logo.svg": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 512 512\" width=\"100%\" height=\"100%\" fill=\"none\">\r\n  <defs>\r\n    <!-- Background Gradient -->\r\n    <radialGradient id=\"bgGlow\" cx=\"50%\" cy=\"50%\" r=\"50%\">\r\n      <stop offset=\"0%\" stop-color=\"#1e293b\" stop-opacity=\"0.8\"/>\r\n      <stop offset=\"100%\" stop-color=\"#07090e\" stop-opacity=\"1\"/>\r\n    </radialGradient>\r\n\r\n    <!-- Cube Gradients -->\r\n    <linearGradient id=\"topFace\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\r\n      <stop offset=\"0%\" stop-color=\"#ffffff\"/>\r\n      <stop offset=\"100%\" stop-color=\"#e2e8f0\"/>\r\n    </linearGradient>\r\n\r\n    <linearGradient id=\"leftFace\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\r\n      <stop offset=\"0%\" stop-color=\"#94a3b8\"/>\r\n      <stop offset=\"100%\" stop-color=\"#64748b\"/>\r\n    </linearGradient>\r\n\r\n    <linearGradient id=\"rightFace\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\r\n      <stop offset=\"0%\" stop-color=\"#475569\"/>\r\n      <stop offset=\"100%\" stop-color=\"#1e293b\"/>\r\n    </linearGradient>\r\n\r\n    <!-- Orbit Gradients -->\r\n    <linearGradient id=\"orbitGlowPrimary\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\r\n      <stop offset=\"0%\" stop-color=\"#38bdf8\" stop-opacity=\"0.2\"/>\r\n      <stop offset=\"40%\" stop-color=\"#ffffff\" stop-opacity=\"1\"/>\r\n      <stop offset=\"70%\" stop-color=\"#38bdf8\" stop-opacity=\"0.9\"/>\r\n      <stop offset=\"100%\" stop-color=\"#818cf8\" stop-opacity=\"0.1\"/>\r\n    </linearGradient>\r\n\r\n    <linearGradient id=\"orbitGlowSecondary\" x1=\"100%\" y1=\"0%\" x2=\"0%\" y2=\"100%\">\r\n      <stop offset=\"0%\" stop-color=\"#a855f7\" stop-opacity=\"0.1\"/>\r\n      <stop offset=\"50%\" stop-color=\"#38bdf8\" stop-opacity=\"0.8\"/>\r\n      <stop offset=\"100%\" stop-color=\"#34d399\" stop-opacity=\"0.1\"/>\r\n    </linearGradient>\r\n\r\n    <!-- Core Glow Filter -->\r\n    <filter id=\"glow\" x=\"-20%\" y=\"-20%\" width=\"140%\" height=\"140%\">\r\n      <feGaussianBlur stdDeviation=\"6\" result=\"blur\"/>\r\n      <feComposite in=\"SourceGraphic\" in2=\"blur\" operator=\"over\"/>\r\n    </filter>\r\n\r\n    <filter id=\"halo\" x=\"-30%\" y=\"-30%\" width=\"160%\" height=\"160%\">\r\n      <feGaussianBlur stdDeviation=\"16\" result=\"blur\"/>\r\n    </filter>\r\n  </defs>\r\n\r\n  <!-- Ambient Backdrop Halo -->\r\n  <circle cx=\"256\" cy=\"256\" r=\"140\" fill=\"#38bdf8\" opacity=\"0.15\" filter=\"url(#halo)\"/>\r\n\r\n  <!-- BACK ORBITS (Rendered Behind Cube) -->\r\n  <g transform=\"rotate(-25 256 256)\">\r\n    <!-- Primary Back Orbit Arc -->\r\n    <path d=\"M 56 256 A 200 68 0 0 1 456 256\" stroke=\"url(#orbitGlowPrimary)\" stroke-width=\"4\" stroke-linecap=\"round\" opacity=\"0.4\" stroke-dasharray=\"8 6\"/>\r\n  </g>\r\n\r\n  <g transform=\"rotate(35 256 256)\">\r\n    <!-- Secondary Back Orbit Arc -->\r\n    <path d=\"M 86 256 A 170 54 0 0 1 426 256\" stroke=\"url(#orbitGlowSecondary)\" stroke-width=\"3\" stroke-linecap=\"round\" opacity=\"0.3\"/>\r\n  </g>\r\n\r\n  <!-- THE MINECRAFT CORE CUBE -->\r\n  <!-- Left Shadow Casting Base -->\r\n  <g id=\"cube\">\r\n    <!-- Top Face -->\r\n    <polygon points=\"256,150 346,202 256,254 166,202\" fill=\"url(#topFace)\"/>\r\n    \r\n    <!-- Top Face Grid / Voxel Accent -->\r\n    <polygon points=\"256,150 301,176 256,202 211,176\" fill=\"#ffffff\" opacity=\"0.35\"/>\r\n    <polygon points=\"256,202 301,228 256,254 211,228\" fill=\"#cbd5e1\" opacity=\"0.2\"/>\r\n\r\n    <!-- Left Face -->\r\n    <polygon points=\"166,202 256,254 256,358 166,306\" fill=\"url(#leftFace)\"/>\r\n    \r\n    <!-- Left Face Voxel Inset -->\r\n    <polygon points=\"166,202 211,228 211,332 166,306\" fill=\"#64748b\" opacity=\"0.4\"/>\r\n    \r\n    <!-- Right Face -->\r\n    <polygon points=\"256,254 346,202 346,306 256,358\" fill=\"url(#rightFace)\"/>\r\n\r\n    <!-- Right Face Voxel Inset -->\r\n    <polygon points=\"301,228 346,202 346,306 301,332\" fill=\"#0f172a\" opacity=\"0.4\"/>\r\n\r\n    <!-- Cube Bevel Edge Lines -->\r\n    <line x1=\"256\" y1=\"150\" x2=\"256\" y2=\"254\" stroke=\"#ffffff\" stroke-width=\"2\" opacity=\"0.6\"/>\r\n    <line x1=\"166\" y1=\"202\" x2=\"256\" y2=\"254\" stroke=\"#ffffff\" stroke-width=\"1.5\" opacity=\"0.4\"/>\r\n    <line x1=\"346\" y1=\"202\" x2=\"256\" y2=\"254\" stroke=\"#ffffff\" stroke-width=\"1.5\" opacity=\"0.4\"/>\r\n    <line x1=\"256\" y1=\"254\" x2=\"256\" y2=\"358\" stroke=\"#38bdf8\" stroke-width=\"2\" opacity=\"0.8\"/>\r\n  </g>\r\n\r\n  <!-- FRONT ORBITS (Rendered in Front of Cube for 3D Depth) -->\r\n  <g transform=\"rotate(-25 256 256)\">\r\n    <!-- Primary Front Orbit Arc (Sweeps in front of the cube) -->\r\n    <path d=\"M 456 256 A 200 68 0 0 1 56 256\" stroke=\"url(#orbitGlowPrimary)\" stroke-width=\"5\" stroke-linecap=\"round\" filter=\"url(#glow)\"/>\r\n\r\n    <!-- Satellite Node on Primary Orbit -->\r\n    <circle cx=\"390\" cy=\"298\" r=\"8\" fill=\"#ffffff\" filter=\"url(#glow)\"/>\r\n    <circle cx=\"390\" cy=\"298\" r=\"14\" stroke=\"#38bdf8\" stroke-width=\"2\" opacity=\"0.6\"/>\r\n    <circle cx=\"390\" cy=\"298\" r=\"4\" fill=\"#38bdf8\"/>\r\n  </g>\r\n\r\n  <g transform=\"rotate(35 256 256)\">\r\n    <!-- Secondary Front Orbit Arc -->\r\n    <path d=\"M 426 256 A 170 54 0 0 1 86 256\" stroke=\"url(#orbitGlowSecondary)\" stroke-width=\"3.5\" stroke-linecap=\"round\" opacity=\"0.85\"/>\r\n    \r\n    <!-- Secondary Satellite Node -->\r\n    <circle cx=\"120\" cy=\"275\" r=\"5\" fill=\"#ffffff\"/>\r\n    <circle cx=\"120\" cy=\"275\" r=\"10\" stroke=\"#a855f7\" stroke-width=\"1.5\" opacity=\"0.5\"/>\r\n  </g>\r\n\r\n  <!-- Sparkle Particle Accents -->\r\n  <circle cx=\"210\" cy=\"110\" r=\"2\" fill=\"#ffffff\" opacity=\"0.8\"/>\r\n  <circle cx=\"340\" cy=\"130\" r=\"3\" fill=\"#38bdf8\" opacity=\"0.7\"/>\r\n  <circle cx=\"130\" cy=\"370\" r=\"2.5\" fill=\"#38bdf8\" opacity=\"0.6\"/>\r\n  <circle cx=\"390\" cy=\"380\" r=\"2\" fill=\"#ffffff\" opacity=\"0.7\"/>\r\n</svg>\r\n",
  "styles.css": "/* ==========================================================================\r\n   CraftOrbit Design System — Modern Cyber-Dark / Obsidian Theme\r\n   Engineered with UI/UX Pro Max Guidelines\r\n   ========================================================================== */\r\n\r\n@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&family=JetBrains+Mono:wght@400;500;600;700&display=swap');\r\n\r\n:root {\r\n  /* Surface & Background System */\r\n  --bg-main: #07090e;\r\n  --bg-surface: #0a0d14;\r\n  --bg-card: rgba(13, 17, 26, 0.75);\r\n  --bg-card-hover: rgba(20, 26, 38, 0.85);\r\n  --bg-card-solid: #0d121c;\r\n  \r\n  /* Border System */\r\n  --border-subtle: rgba(255, 255, 255, 0.07);\r\n  --border-light: rgba(255, 255, 255, 0.14);\r\n  --border-focus: rgba(56, 189, 248, 0.5);\r\n\r\n  /* Typography Colors */\r\n  --text-primary: #f8fafc;\r\n  --text-secondary: #94a3b8;\r\n  --text-muted: #64748b;\r\n\r\n  /* Accent Glow Palette */\r\n  --accent-cyan: #38bdf8;\r\n  --accent-emerald: #10b981;\r\n  --accent-indigo: #818cf8;\r\n  --accent-amber: #f59e0b;\r\n  --accent-rose: #f43f5e;\r\n}\r\n\r\n/* Base Body Styling */\r\nbody {\r\n  background-color: var(--bg-main) !important;\r\n  color: var(--text-primary) !important;\r\n  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;\r\n  background-image: \r\n    radial-gradient(at 0% 0%, rgba(56, 189, 248, 0.04) 0px, transparent 50%),\r\n    radial-gradient(at 100% 100%, rgba(129, 140, 248, 0.04) 0px, transparent 50%),\r\n    radial-gradient(rgba(255, 255, 255, 0.04) 1px, transparent 1px);\r\n  background-size: 100% 100%, 100% 100%, 28px 28px;\r\n  background-attachment: fixed;\r\n}\r\n\r\n/* Monospace System */\r\n.font-mono, kbd, code, pre, .log-line, .cmd-chip {\r\n  font-family: 'JetBrains Mono', ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace !important;\r\n}\r\n\r\n/* Custom Sleek Scrollbar */\r\n::-webkit-scrollbar {\r\n  width: 7px;\r\n  height: 7px;\r\n}\r\n::-webkit-scrollbar-track {\r\n  background: #07090e;\r\n}\r\n::-webkit-scrollbar-thumb {\r\n  background: #1e293b;\r\n  border-radius: 4px;\r\n  border: 1px solid rgba(255, 255, 255, 0.04);\r\n}\r\n::-webkit-scrollbar-thumb:hover {\r\n  background: #334155;\r\n}\r\n\r\n.no-scrollbar::-webkit-scrollbar {\r\n  display: none;\r\n}\r\n.no-scrollbar {\r\n  -ms-overflow-style: none;\r\n  scrollbar-width: none;\r\n}\r\n\r\n/* Glass Card Elevation */\r\n.bg-brand-card,\r\n.glass-panel {\r\n  background-color: var(--bg-card) !important;\r\n  backdrop-filter: blur(16px);\r\n  -webkit-backdrop-filter: blur(16px);\r\n  border: 1px solid var(--border-subtle) !important;\r\n  transition: all 0.2s cubic-bezier(0.16, 1, 0.3, 1);\r\n}\r\n.bg-brand-card:hover {\r\n  border-color: var(--border-light) !important;\r\n}\r\n\r\n/* Header Bar Styling */\r\nheader {\r\n  background: rgba(7, 9, 14, 0.85) !important;\r\n  backdrop-filter: blur(20px) !important;\r\n  -webkit-backdrop-filter: blur(20px) !important;\r\n  border-bottom: 1px solid var(--border-subtle) !important;\r\n}\r\n\r\n/* Navigation Tabs — Segmented Control Style */\r\n.tab-btn {\r\n  color: var(--text-secondary);\r\n  background-color: transparent;\r\n  border: 1px solid transparent;\r\n  white-space: nowrap;\r\n  font-weight: 500;\r\n  transition: all 0.18s ease;\r\n  position: relative;\r\n}\r\n.tab-btn:hover {\r\n  color: #ffffff;\r\n  background-color: rgba(255, 255, 255, 0.05);\r\n  border-color: rgba(255, 255, 255, 0.08);\r\n}\r\n.tab-btn.active {\r\n  color: #ffffff !important;\r\n  background-color: rgba(255, 255, 255, 0.12) !important;\r\n  border-color: rgba(255, 255, 255, 0.22) !important;\r\n  font-weight: 600;\r\n  box-shadow: 0 0 15px rgba(255, 255, 255, 0.06), inset 0 1px 0 rgba(255, 255, 255, 0.2);\r\n}\r\n\r\n/* Terminal & Console Log Stream */\r\n.log-line {\r\n  white-space: pre-wrap;\r\n  word-break: break-all;\r\n  line-height: 1.6;\r\n}\r\n.log-error {\r\n  color: #fda4af !important;\r\n  background-color: rgba(244, 63, 94, 0.12);\r\n  padding: 2px 6px;\r\n  border-left: 3px solid #f43f5e;\r\n  border-radius: 0 4px 4px 0;\r\n  margin: 1px 0;\r\n}\r\n.log-warn {\r\n  color: #fde047 !important;\r\n  background-color: rgba(234, 179, 8, 0.08);\r\n  padding: 1px 6px;\r\n  border-left: 2px solid #eab308;\r\n  border-radius: 0 4px 4px 0;\r\n}\r\n.log-info {\r\n  color: #94a3b8;\r\n}\r\n.log-chat {\r\n  color: #ffffff !important;\r\n  font-weight: 600;\r\n  background: rgba(255, 255, 255, 0.04);\r\n  padding: 1px 4px;\r\n  border-radius: 4px;\r\n}\r\n.log-dash {\r\n  color: #38bdf8 !important;\r\n  font-style: italic;\r\n}\r\n\r\n/* Pulse Animations for Running Status */\r\n@keyframes pulse-emerald {\r\n  0%, 100% {\r\n    box-shadow: 0 0 0 0 rgba(16, 185, 129, 0.8);\r\n  }\r\n  50% {\r\n    box-shadow: 0 0 0 6px rgba(16, 185, 129, 0);\r\n  }\r\n}\r\n\r\n@keyframes pulse-amber {\r\n  0%, 100% {\r\n    box-shadow: 0 0 0 0 rgba(245, 158, 11, 0.8);\r\n  }\r\n  50% {\r\n    box-shadow: 0 0 0 6px rgba(245, 158, 11, 0);\r\n  }\r\n}\r\n\r\n.pulse-active {\r\n  animation: pulse-emerald 2s infinite;\r\n}\r\n\r\n.pulse-starting {\r\n  animation: pulse-amber 1.5s infinite;\r\n}\r\n\r\n/* Mod Switch Toggle */\r\n.mod-toggle {\r\n  appearance: none;\r\n  width: 38px;\r\n  height: 22px;\r\n  background-color: #1e293b;\r\n  border-radius: 9999px;\r\n  position: relative;\r\n  cursor: pointer;\r\n  outline: none;\r\n  transition: all 0.2s cubic-bezier(0.16, 1, 0.3, 1);\r\n  border: 1px solid rgba(255, 255, 255, 0.1);\r\n}\r\n.mod-toggle:checked {\r\n  background-color: #10b981;\r\n  border-color: #10b981;\r\n  box-shadow: 0 0 12px rgba(16, 185, 129, 0.4);\r\n}\r\n.mod-toggle::before {\r\n  content: '';\r\n  position: absolute;\r\n  top: 2px;\r\n  left: 2px;\r\n  width: 16px;\r\n  height: 16px;\r\n  border-radius: 50%;\r\n  background-color: #94a3b8;\r\n  transition: transform 0.2s cubic-bezier(0.16, 1, 0.3, 1), background-color 0.2s;\r\n}\r\n.mod-toggle:checked::before {\r\n  background-color: #ffffff;\r\n  transform: translateX(16px);\r\n}\r\n\r\n/* Command Chips */\r\n.cmd-chip {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  gap: 5px;\r\n  background-color: rgba(255, 255, 255, 0.05);\r\n  border: 1px solid var(--border-subtle);\r\n  color: #e2e8f0;\r\n  padding: 3px 8px;\r\n  border-radius: 6px;\r\n  font-size: 11px;\r\n  cursor: pointer;\r\n  transition: all 0.15s ease;\r\n}\r\n.cmd-chip:hover {\r\n  background-color: #ffffff;\r\n  border-color: #ffffff;\r\n  color: #000000;\r\n  box-shadow: 0 0 10px rgba(255, 255, 255, 0.3);\r\n  transform: translateY(-1px);\r\n}\r\n\r\n/* Modal Window Glass Backdrop */\r\n.modal-overlay {\r\n  background: rgba(3, 5, 8, 0.75) !important;\r\n  backdrop-filter: blur(12px) !important;\r\n  -webkit-backdrop-filter: blur(12px) !important;\r\n}\r\n\r\n.modal-content {\r\n  background: #0d121c !important;\r\n  border: 1px solid rgba(255, 255, 255, 0.12) !important;\r\n  box-shadow: 0 25px 60px -15px rgba(0, 0, 0, 0.9), 0 0 0 1px rgba(255, 255, 255, 0.05) !important;\r\n  border-radius: 16px !important;\r\n}\r\n\r\n/* Action Button Micro-Interactions */\r\nbutton {\r\n  transition: transform 0.12s ease, opacity 0.15s ease, background-color 0.15s ease, border-color 0.15s ease;\r\n}\r\nbutton:active:not(:disabled) {\r\n  transform: scale(0.97);\r\n}\r\n\r\n/* Input Fields Styling */\r\ninput[type=\"text\"],\r\ninput[type=\"number\"],\r\ninput[type=\"password\"],\r\ninput[type=\"search\"],\r\nselect,\r\ntextarea {\r\n  background-color: #090c13 !important;\r\n  border: 1px solid rgba(255, 255, 255, 0.1) !important;\r\n  color: #f8fafc !important;\r\n  transition: border-color 0.15s ease, box-shadow 0.15s ease;\r\n}\r\ninput:focus, select:focus, textarea:focus {\r\n  outline: none !important;\r\n  border-color: var(--accent-cyan) !important;\r\n  box-shadow: 0 0 0 2px rgba(56, 189, 248, 0.2) !important;\r\n}\r\n\r\n/* Quick Status Badges */\r\n.badge-online {\r\n  background: rgba(16, 185, 129, 0.12);\r\n  color: #34d399;\r\n  border: 1px solid rgba(16, 185, 129, 0.25);\r\n}\r\n.badge-offline {\r\n  background: rgba(244, 63, 94, 0.1);\r\n  color: #fb7185;\r\n  border: 1px solid rgba(244, 63, 94, 0.2);\r\n}\r\n.badge-starting {\r\n  background: rgba(245, 158, 11, 0.12);\r\n  color: #fbbf24;\r\n  border: 1px solid rgba(245, 158, 11, 0.25);\r\n}\r\n\r\n/* ==========================================================================\r\n   Left Sidebar Navigation Layout (Argonara / Pterodactyl Style)\r\n   ========================================================================== */\r\n.sidebar-tab-btn {\r\n  color: #94a3b8;\r\n  background-color: transparent;\r\n  border: 1px solid transparent;\r\n  transition: all 0.18s cubic-bezier(0.16, 1, 0.3, 1);\r\n  font-weight: 500;\r\n  position: relative;\r\n}\r\n.sidebar-tab-btn:hover {\r\n  color: #ffffff;\r\n  background-color: rgba(255, 255, 255, 0.05);\r\n  border-color: rgba(255, 255, 255, 0.08);\r\n  transform: translateX(2px);\r\n}\r\n.sidebar-tab-btn.active {\r\n  color: #ffffff !important;\r\n  background-color: rgba(56, 189, 248, 0.12) !important;\r\n  border-color: rgba(56, 189, 248, 0.3) !important;\r\n  box-shadow: 0 0 20px rgba(56, 189, 248, 0.1), inset 0 1px 0 rgba(255, 255, 255, 0.1);\r\n  font-weight: 600;\r\n}\r\n.sidebar-tab-btn.active i {\r\n  color: #38bdf8 !important;\r\n}\r\n\r\n/* Mode Switch Layout Specifics (Decluttered & Non-Redundant) */\r\n#appShell.mode-sidebar #leftSidebar {\r\n  display: flex !important;\r\n}\r\n#appShell.mode-sidebar #topNavTabs {\r\n  display: none !important;\r\n}\r\n#appShell.mode-sidebar #headerBrandSwitcher {\r\n  display: none !important;\r\n}\r\n#appShell.mode-sidebar #headerBreadcrumb {\r\n  display: flex !important;\r\n}\r\n#appShell.mode-sidebar #headerPowerActions {\r\n  display: none !important;\r\n}\r\n#appShell.mode-sidebar #statusBadge {\r\n  display: none !important;\r\n}\r\n#appShell.mode-sidebar #headerCmdPalette {\r\n  display: none !important;\r\n}\r\n#appShell.mode-sidebar #hardwareMetersRow {\r\n  display: none !important;\r\n}\r\n\r\n#appShell.mode-topbar #leftSidebar {\r\n  display: none !important;\r\n}\r\n#appShell.mode-topbar #topNavTabs {\r\n  display: flex !important;\r\n}\r\n#appShell.mode-topbar #headerBrandSwitcher {\r\n  display: flex !important;\r\n}\r\n#appShell.mode-topbar #headerBreadcrumb {\r\n  display: none !important;\r\n}\r\n#appShell.mode-topbar #headerPowerActions {\r\n  display: flex !important;\r\n}\r\n#appShell.mode-topbar #statusBadge {\r\n  display: flex !important;\r\n}\r\n#appShell.mode-topbar #headerCmdPalette {\r\n  display: flex !important;\r\n}\r\n#appShell.mode-topbar #hardwareMetersRow {\r\n  display: grid !important;\r\n}\r\n#appShell.mode-topbar #serverHeroCard {\r\n  display: none !important;\r\n}\r\n\r\n/* ==========================================================================\r\n   Smooth Micro-Transitions & Quality-of-Life Enhancements\r\n   ========================================================================== */\r\n\r\n@keyframes viewFadeIn {\r\n  from {\r\n    opacity: 0;\r\n    transform: translateY(5px);\r\n  }\r\n  to {\r\n    opacity: 1;\r\n    transform: translateY(0);\r\n  }\r\n}\r\n\r\nsection[id^=\"view-\"]:not(.hidden) {\r\n  animation: viewFadeIn 0.15s cubic-bezier(0.16, 1, 0.3, 1) forwards;\r\n}\r\n\r\n@keyframes modalBackdropFadeIn {\r\n  from { opacity: 0; }\r\n  to { opacity: 1; }\r\n}\r\n\r\n@keyframes modalContentZoomIn {\r\n  from {\r\n    opacity: 0;\r\n    transform: scale(0.96) translateY(6px);\r\n  }\r\n  to {\r\n    opacity: 1;\r\n    transform: scale(1) translateY(0);\r\n  }\r\n}\r\n\r\n.modal-overlay:not(.hidden),\r\ndiv[id$=\"Modal\"]:not(.hidden) {\r\n  animation: modalBackdropFadeIn 0.15s ease-out forwards;\r\n}\r\n\r\n.modal-overlay:not(.hidden) > div,\r\ndiv[id$=\"Modal\"]:not(.hidden) > div {\r\n  animation: modalContentZoomIn 0.18s cubic-bezier(0.16, 1, 0.3, 1) forwards;\r\n}\r\n\r\n/* Accessible reduced-motion query */\r\n@media (prefers-reduced-motion: reduce) {\r\n  *, ::before, ::after {\r\n    animation-duration: 0.01ms !important;\r\n    animation-iteration-count: 1 !important;\r\n    transition-duration: 0.01ms !important;\r\n    scroll-behavior: auto !important;\r\n  }\r\n}\r\n\r\n\r\n"
};

function ensurePublicAssets(targetDir) {
  const publicFolder = path.join(targetDir, 'public');
  if (!fs.existsSync(publicFolder)) {
    fs.mkdirSync(publicFolder, { recursive: true });
  }

  for (const [fileName, content] of Object.entries(EMBEDDED_PUBLIC)) {
    const targetFile = path.join(publicFolder, fileName);
    if (!fs.existsSync(targetFile)) {
      try {
        fs.writeFileSync(targetFile, content, 'utf8');
      } catch (e) {}
    }
  }
  return publicFolder;
}

module.exports = { ensurePublicAssets, EMBEDDED_PUBLIC };
